(window.GIM_TS=window.GIM_TS||{})["Ketubot.0"]={"from":0,"a":[["תיקנו חכמים שתהא \u0003בתולה נשאת ליום הרביעי\u0004 בשבוע \u0003ואלמנה ליום החמישי.\u0004 ומפני מה תיקנו שבתולה תנשא ביום רביעי? מפני \u0003שפעמים בשבת\u0004 (בשבוע) \u0003בתי דינין יושבין בעיירות: ביום השני וביום החמישי,\u0004 וכיון \u0003ש\u0004כך, \u0003אם היה לו\u0004 לבעל, שנשא אותה ביום הרביעי, \u0003טענת בתולים,\u0004 שמצא בביאתו שלא היתה בתולה, \u0003היה משכים\u0004 מיד למחרת \u0003לבית־דין,\u0004 ומעלה תביעתו בפניו.","\u0003אמר רב יוסף אמר רב יהודה אמר שמואל: מפני מה אמרו\u0004 חכמים שתהא \u0003בתולה נשאת ליום הרביעי? לפי ששנינו\u0004 במשנה אחרת: \u0003הגיע\u0004 ה\u0003זמן\u0004 שקבע הבעל לחתונה \u0003ו\u0004בשל עיכוב הבעל \u0003לא נישאו,\u0004 ונדחו הנישואין לתאריך מאוחר יותר — אותן הנשים שנקבע להן זמן — \u0003אוכלות משלו,\u0004 מרכוש הארוס, \u0003ו\u0004אף שהן ממשפחת ישראלים, מכל מקום \u0003אוכלות בתרומה\u0004 אם הארוס כהן.","\u0003יכול\u0004 הייתי לומר שאם \u0003הגיע זמן\u0004 זה \u0003באחד בשבת\u0004 ולא נישאה \u0003יהא\u0004 הארוס \u0003מעלה לה מזונות\u0004 מיד? \u0003לכך שנינו: בתולה נשאת ליום הרביעי.\u0004 שעד יום רביעי בשבוע אין אנחנו חושבים שהגיע הזמן, גם אם התאריך שקבע היה קצת קודם לכן.","דברים אלה \u0003אמר רב יוסף\u0004 כפי ששמעם מרבו. ועל כך תמה: \u0003מריה\u0004 \u0005[רבונו]\u0006 של \u0003אברהם! תלי תניא בדלא תניא\u0004 \u0005[תולה\u0006 שמואל כאן את מה ש\u0005שנוי בשאינו שנוי],\u0006 כלומר, הוא מסביר דבר שנוי ומפורש על פי דבר שלא שנינו כלל?! על דברי רב יוסף תוהים: \u0003הי תניא והי לא תניא\u0004 \u0005[איזו שנויה ואיזו אינה שנויה]?\u0006 הלא \u0003הא תניא והא תניא\u0004 \u0005[זו שנויה וזו שנויה],\u0006 שהרי גם משנתנו וגם המשנה האחרת שנויות הן! \u0003אלא\u0004 יש לפרש את תמיהתו כך: \u0003תלי תניא דמפרש טעמא\u0004 \u0005[תולה\u0006 שמואל הלכה \u0005שנויה שמפורש טעמה\u0006 במשנתנו\u0005]\u0006 \u0003בדתניא דלא מפרש טעמא\u0004 \u0005[ב\u0006מה \u0005ששנויה\u0006 ו\u0005שאין מפורש טעמה],\u0006 שהרי לא הוסיף ביאור למשנתנו מן המשנה האחרת שהביא.","\u0003אלא,\u0004 יש לחזור מנוסח זה של רב יוסף, ו\u0003אי איתמר, הכי איתמר\u0004 \u0005[\u0006ו\u0005אם נאמר, כך נאמר],\u0006 \u0003אמר רב יהודה אמר שמואל:\u0004 נאמר במשנה הטעם \u0003מפני מה אמרו בתולה נשאת ליום הרביעי — שאם היה לו טענת בתולים היה משכים לבית דין\u0004 מיד למחרת ביום החמישי, שבו בית הדין יושב. ויש לשאול על טעם זה: \u0003ותנשא\u0004 הבתולה \u0003באחד בשבת, ש\u0004גם אז \u0003אם היה לו טענת בתולים היה משכים לבית דין\u0004 ביום שני בשבוע, שאף הוא יום מושב בית־דין. ומסבירים: \u0003שקדו חכמים על תקנת בנות ישראל,\u0004 ולכן קבעו ברביעי דווקא, כדי \u0003שיהא\u0004 הבעל \u0003טורח בסעודה\u0004 של נישואין \u0003שלשה ימים: אחד בשבת, ושני בשבת, ושלישי בשבת, וברביעי כונסה\u0004 (נושאה).","\u0003ועכשיו ששנינו\u0004 (כלומר, שלמדנו מן המשנה) כי \u0003שקדו\u0004 חכמים על תקנת בנות ישראל, ומשום כך תיקנו שתינשאנה ביום רביעי, על כן, \u0003אותה\u0004 הלכה \u0003ששנינו\u0004 שאם \u0003הגיע זמן\u0004 הנישואין \u0003ולא נישאו אוכלות משלו ואוכלות בתרומה,\u0004 הרי אם \u0003הגיע זמן\u0004 זה \u0003באחד בשבת, מתוך שאינו יכול לכנוס\u0004 מיד בשל היותו \"טורח בסעודה\", שבשל כך תיקנו חכמים שיכנוס רק ברביעי — \u0003אינו מעלה לה מזונות.\u0004 שאין זה נקרא שהגיע כבר הזמן.","ומסיק מכאן רב יוסף: \u0003לפיכך,\u0004 על פי אותה סברה, אם \u0003חלה הוא\u0004 (הבעל) \u0003או שחלתה היא\u0004 (הארוסה) \u0003או שפירסה נדה\u0004 כשהגיע הזמן שקבעו ואינו יכול לכנוס אותה אז, ומן הצורך לדחות את החופה לזמן אחר — \u0003אינו מעלה לה מזונות.\u0004 שהרי למדנו שכאשר דחיית הנישואין אינה נעשית ברצונו — אין הוא מחוייב להעלות לה מזונות למרות שעבר הזמן שקבע לנישואין.","סוגיה זו נמסרה גם בצורה שונה: \u0003ואיכא דבעי לה מיבעיא\u0004 \u0005[ויש ששאל אותה\u0006 בצורת \u0005שאלה]:\u0006 \u0003חלה הוא,\u0004 הבעל, \u0003מהו\u0004 דינו לענין חיוב במזונות ארוסתו? וצדדי השאלה: \u0003התם טעמא מאי\u0004 \u0005[שם,\u0006 כשהגיע הזמן ביום ראשון בשבת, \u0005מה הטעם]\u0006 שפטור ממזונות — \u0003משום דאניס\u0004 \u0005[ש\u0006הוא \u0005אנוס]\u0006 ואינו יכול לכונסה בזמן שקבע, \u0003והכא נמי הא אניס\u0004 \u0005[וכאן גם כן הרי\u0006 הוא \u0005אנוס],\u0006 ויהא פטור, \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש לחלק: \u0003התם, אניס בתקנתא דתקינו ליה רבנן\u0004 \u0005[שם, אנוס\u0006 הוא \u0005ב\u0006של \u0005התקנה שתיקנו לו חכמים]\u0006 שישא ברביעי דווקא, והם גם שקבעו שלא יהא עליו חיוב מזונות עד אז, ואולם \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003לא,\u0004 שאף שאנוס הוא — מכל מקום לא נפטר מלמלא את התחייבותו.","על סמך כך ממשיכים ושואלים: \u0003ואם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ותסכים שאם \u0003חלה הוא — מעלה לה מזונות,\u0004 שאין אונסו פוטרו מחיוב מזונות, אם \u0003חלתה היא מהו\u0004 הדין? האם \u0003מצי אמר\u0004 \u0005[יכול לומר]\u0006 \u0003לה: אנא הא קאימנא\u0004 \u0005[אני הרי עומד]\u0006 ומוכן לנישואין, ואם את אינך מוכנה — אין זו אשמתי, \u0003או דלמא מציא אמרה ליה\u0004 \u0005[שמא יכולה\u0006 היא \u0005לומר לו]:\u0006 \u0003\"נסתחפה שדהו\",\u0004 כלומר, שמחלתה היא אונס, ולכן מצבו של הבעל כמצבו של אדם שהמים סחפו את שדהו, ויש לו הפסד, שאינו יכול לתלות אשמה בשום איש, ויהא חייב במזונותיה, שכן מזלו הוא שגרם לו להפסד זה.","\u0003ו\u0004עוד, \u0003אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ש\u0003אמרה ליה\u0004 \u0005[\u0006שיכולה היא \u0005לומר לו]\u0006 על מחלתה \u0003\"נסתחפה שדהו\"\u0004 ואנו מקבלים את טענתה זו, אם \u0003פירסה נדה\u0004 ונדחו הנישואין בשל כך, \u0003מהו\u0004 הדין? האם יש לראות בכך אונס כמחלה, או לומר שדבר זה צפוי מראש?","ומחלקים: אם פירסה נידה \u0003בשעת ווסתה,\u0004 כלומר, בזמן הרגיל לנידתה — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך,\u0004 שאין ספק בדבר"],["\u0003דלא מציא אמרה ליה\u0004 \u0005[שאינה יכולה לומר לו]\u0006 \u0003\"נסתחפה שדהו\",\u0004 כי הדבר אינו בגדר אונס, אלא דרכה הוא, והרי זה נחשב שבגללה נדחה זמן הנישואין. \u0003כי תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 שאלה זו — הרי זה כאשר פירסה נידה \u0003שלא בשעת ווסתה, מאי\u0004 \u0005[מה]\u0006 הדין? האם נאמר \u0003כיון\u0004 ש\u0003לא בשעת ווסתה הויא\u0004 \u0005[היתה\u0006 הנידות\u0005]\u0006 הריהי כמחלה, ולכן \u0003מציא אמרה ליה\u0004 \u0005[\u0006ו\u0005יכולה לומר לו]\u0006 \u0003\"נסתחפה שדהו\", או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאיכא נשי דקא משנייא ווסתייהו\u0004 \u0005[שיש נשים שמשנות\u0006 את \u0005ווסתן]\u0006 מזמן לזמן — אין זה אונס גמור ו\u0003כשעת ווסתה דמי\u0004 \u0005[נחשב]\u0006 הדבר, ובגללה נדחה זמן הנישואין.","שאלות אלה \u0003פשיט\u0004 \u0005[פתר]\u0006 \u0003רב אחאי\u0004 מדיוק לשון המשנה: \u0003הגיע זמן ולא נישאו\u0004 — \u0003אוכלות משלו ואוכלות בתרומה. \"לא נשאו\u0004 הארוסים \u0003\"\u0004\u0003לא קתני\u0004 \u0005[שנה],\u0006 \u0003אלא \"לא נישאו\".\u0004","ומעתה נברר \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]\u0006 שלא נישאו: \u0003אי דקא מעכבן אינהי\u0004 \u0005[אם שמעכבות הן],\u0006 שמשום מה אינן רוצות להינשא באותו זמן — \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אוכלות משלו ואוכלות בתרומה?\u0004 הלא הן שדחו את הנישואין! \u0003אלא לאו דאיתניס כי האי גוונא\u0004 \u0005[\u0006האם \u0005לא\u0006 מדובר באופן \u0005שנאנסו באופן כזה],\u0006 כגון שחלתה או שפירסה נידה, \u0003וקתני\u0004 \u0005[ושנה\u0006 שם\u0005]:\u0006 \u0003אוכלות משלו ואוכלות בתרומה,\u0004 שהרי זה כנסתחפה שדהו.","\u0003אמר רב אשי:\u0004 אפשר לדחות ראיה זו, \u0003לעולם אימא לך\u0004 \u0005[אומר לך]\u0006 כי ב\u0003כל אונסא\u0004 \u0005[אונס],\u0006 בין שלו ובין שלה, \u0003לא אכלה\u0004 \u0005[אינה אוכלת\u0006 בתרומה\u0005],\u0006 \u0003ו\u0004המקרה שמדובר בו במשנה הוא \u0003דקא מעכבי אינהו\u0004 \u0005[שהם\u0006 הארוסים \u0005מעכבים\u0006 את הנישואין\u0005].\u0006 \u0003ובדין הוא דאיבעי ליה למיתני\u0004 \u0005[ש\u0006אכן \u0005היה צריך לשנות]\u0006 בלשון \u0003\"לא נשאו\",\u0004 שמשמעו שהארוסים הם המעכבים, \u0003ו\u0004אולם \u0003איידי דתנא רישא בדידהי\u0004 \u0005[על ידי,\u0006 מכיון \u0005ששנה\u0006 ב\u0005תחילה בהן],\u0006 כלומר, בנשים, שהן היו נושא המשפט שבמשנה, \u0003תנא נמי סיפא בדידהי\u0004 \u0005[שנה גם כן\u0006 ב\u0005סופה בהן],\u0006 אבל אין לדייק בלשון. והכוונה היא, שאם הארוסים דחו את זמן הנשואין, צריכים הם לספק מזונות לנשים.","\u0003אמר רבא:\u0004 אף שאמרנו לענין דחיה בזמן נישואין, שאונס פוטר מן ההתחייבות למזונות, \u0003ו\u0004אולם \u0003לענין גיטין אינו כן,\u0004 שאין מתחשבים כלל באונס. ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבור]\u0006 \u0003רבא\u0004 ש\u0003אין אונס בגיטין.\u0004 שאם העמיד אדם תנאי בגט ואירע לו אונס שבעטיו התקיים התנאי — אין אנו מתחשבים בכך אלא הולכים אחר התנאי כפי שהוא, בלא להתחשב בנסיבות שהביאו לקיום התנאי.","ושואלים: \u0003מנא ליה\u0004 \u0005[מנין לו]\u0006 \u0003לרבא הא\u0004 \u0005[\u0006הלכה \u0005זו]?\u0006 \u0003אילימא מהא דתנן\u0004 \u0005[אם תאמר מזו ששנינו\u0006 במשנה\u0005]:\u0006 האומר לאשתו \u0003\"הרי זה גיטיך אם לא באתי מכאן ועד שנים עשר חדש\" ומת בתוך שנים עשר חדש — אינו גט,\u0004 כיון שלא התקיים התנאי, ואם אין לה בנים ממנו — הריהי זקוקה לייבום. ונדייק: \u0003מת — הוא\u0004 ש\u0003אינו גט,\u0004 שהרי אין גט חל לאחר מיתה, \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 אירע אונס אחר, וכגון ש\u0003חלה\u0004 ובשל כך לא בא — \u0003הרי זה גט,\u0004 ומשמע שאונס אינו נחשב כביטול תנאי בגט.","\u0003ו\u0004אולם אין זו ראיה גמורה, שכן \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 שהדין הוא שאם \u0003חלה נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו גט,\u0004 ומה שנאמר במשנה \"מת\", הריהו דוגמא לכל אונס שבעולם, \u0003ו\u0004מדוע השתמש דווקא בדוגמא זו של מת — \u0003היא גופא קא משמע לן\u0004 \u0005[\u0006בהלכה \u0005זו עצמה השמיע לנו]\u0006 התנא ש\u0003אין גט לאחר מיתה.\u0004 שגם אם לא היה תנאי בגט, אלא שקבע הבעל שיחול הגט לאחר מותו — אינו גט.","ומשיבים: והרי דין זה ש\u0003אין גט לאחר מיתה הא תנא ליה רישא\u0004 \u0005[הרי שנה אותו\u0006 כבר ב\u0005ראשה]\u0006 של אותה משנה, ששנינו שם: שכיב מרע שכתב גט לאשתו ואמר לה: \u0003\"הרי זה גיטיך אם מתי\u0004 (אמות)\u0003\",\u0004 או: \u0003הרי זה גיטיך\u0004 אם אמות \u0003מחולי זה\",\u0004 או אמר לה: \u0003\"הרי זה גיטיך לאחר מיתה\" — לא אמר כלום.\u0004 שאין לגט תוקף אלא בחייו של הבעל ולא לאחר מותו.","אלא יש לדחות את הראיה לדברי רבא באופן אחר: \u0003דלמא\u0004 \u0005[שמא]\u0006 מה שאמרו ש\"אם לא באתי יהא גט\" ומת — אינו גט, הרי הוא \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003רבותינו\u0004 ואין לדייק מכאן למקרה שחלה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]\u0006 שהאומר \"אם לא באתי יהיה גט\" ומת — אינו גט, \u0003ורבותינו התירוה להנשא. ואמרינן\u0004 \u0005[ואמרנו]\u0006 על כך: \u0003מאן\u0004 \u0005[מי\u0006 הם\u0005]\u0006 \u0003רבותינו\u0004 אלו שהוזכרו שם? \u0003אמר רב יהודה אמר שמואל: בי דינא דשרו משחא\u0004 \u0005[\u0006אותם דייני \u0005בית הדין שהתירו שמן]\u0006 של גויים באכילה. ומסבירים את טעמם: \u0003סברי לה\u0004 \u0005[סבורים הם]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי\u0004 ש\u0003אמר\u0004 בכלל: \u0003זמנו של שטר מוכיח עליו.\u0004 וכיון שכתב בגט תאריך מסויים, יש ללמוד מכאן שכוונתו היתה שהגט יחול מיום כתיבתו ומסירתו, ולא לאחר מיתה. ולכן אנו אומרים שלא פירש כראוי את התנאי, ולא נתכוון שיחול הגט אחר מותו, אלא שעם מותו יחול הגט משעת כתיבתו בחייו. ומכל מקום אין הוכחה ממשנתנו לשיטת רבא שאין טענת אונס בגיטין.","\u0003ואלא\u0004 ההוכחה היא \u0003מסיפא\u0004 \u0005[מסוף]\u0006 המשנה, ששנינו, האומר לאשה: \u0003\"\u0004הרי זה גיטך \u0003מעכשיו אם לא באתי מכאן ועד שנים עשר חדש\" ומת בתוך שנים עשר חדש — הרי זה גט.\u0004 ונדייק מכאן: הדין כן במקרה ש\u0003מת\u0004 אף על פי שהוא אונס גדול, \u0003ו\u0004אם כן בודאי \u0003הוא הדין\u0004 אם כן ודאי גם \u0003לחלה\u0004 שהוא אונס קטן ממנו ולכל אונס שהוא, שאם לא התבטל תנאו, הגט קיים למרות האונס, משמע שאין אונס נחשב בגיטין.","ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 ב\u0003מת דוקא,\u0004 אמרו שהגט קיים, מפני ש\u0003לא ניחא ליה\u0004 \u0005[נוח לו]\u0006 ש\u0003תפול קמי\u0004 \u0005[לפני]\u0006 \u0003יבם,\u0004 שאם לא היו לו בנים תזדקק אלמנתו לייבום או לחליצה, וכיון שהוא רוצה בטובתה, היתה דעתו מתחילה שאם ימות — בכל מקרה יהא זה גט, ושמא אם היה אונס אחר שעיכב אותו אכן ייבטל התנאי!","\u0003אלא\u0004 ההוכחה היא \u0003מהא\u0004 \u0005[מ\u0006הלכה \u0005זו]:\u0006 \u0003דההוא\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לשליחים שמסר בידם גט: \u0003\"אי לא אתינא מיכן\u0004 \u0005[אם אינני בא,\u0006 חוזר, \u0005מכאן]\u0006 \u0003ועד תלתין יומין\u0004 \u0005[שלושים יום] —\u0006 \u0003ליהוי גיטא\u0004 \u0005[שיהא\u0006 זה \u0005גט]\u0006 \u0003\".\u0004\u0003אתא\u0004 \u0005[בא]\u0006 \u0003בסוף תלתין יומין\u0004 \u0005[שלושים יום]\u0006 \u0003ופסקיה מברא\u0004 \u0005[והפסיקתו המעבורת]\u0006 ולא היה יכול לעבור את הנהר, ונמצא שלא הגיע בתוך שלושים יום. \u0003אמר להו\u0004 \u0005[להם]\u0006 לאנשים העומדים בצד השני של הנהר: \u0003חזו דאתאי, חזו דאתאי\u0004 \u0005[ראו שבאתי, ראו שבאתי].\u0006 \u0003אמר שמואל: לאו שמיה מתיא\u0004 \u0005[אין שמו,\u0006 אין זה נחשב \u0005הגעה].\u0006 ומדברי שמואל נלמד שגם במקרה של אונס אין האונס מבטל את התנאי.","ודוחים: מכאן אין ראיה גמורה; \u0003ודלמא אונסא דשכיח שאני\u0004 \u0005[ושמא אונס שמצוי שונה].\u0006 ש\u0003כיון דאיבעי ליה לאתנויי\u0004 \u0005[שהיה לו להתנות]\u0006 \u0003ולא אתני\u0004 \u0005[התנה] —\u0006 \u0003איהו דאפסיד אנפשיה\u0004 \u0005[הוא שהפסיד לעצמו],\u0006 שהיה עליו להעלות בדעתו אפשרות שכיחה כזו שלא יוכל לעבור את הנהר. ואם לא הגביל את התנאי שעשה — הוא הפסיד לעצמו, ואפשר לומר שרק אחר כך התחרט. אבל אין ללמוד מכאן שאונס בכלל אינו מבטל תנאי, ושמא באונס שאינו מצוי בטל התנאי.","\u0003אלא\u0004 אין ראיה מן המקורות לדברי רבא, ו\u0003רבא סברא דנפשיה קאמר\u0004 \u0005[סברה\u0006 מ\u0005של עצמו אמר]\u0006 בענין זה. ומהי הסברה לזה שאמר שאין אונס בגיטין — \u0003משום\u0004 תקנת הנשים ה\u0003צנועות, ומשום\u0004 תקנת ה\u0003פרוצות.\u0004 ומסבירים: \u0003משום\u0004 ה\u0003צנועות — דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 ש\u0003לא להוי\u0004 \u0005[יהא]\u0006 \u0003גט\u0004 אם היה אונס, אם כן,"],["\u0003זימנין דלא אניס\u0004 \u0005[פעמים שאיננו אנוס]\u0006 ומרצונו קיים את התנאי, שהתכוון הבעל שיהא גט, \u0003וסברה דאניס ומיעגנא ויתבה\u0004 \u0005[ו\u0006היא \u0005סבורה ש\u0006היה \u0005אנוס\u0006 בקיום התנאי, ואינו גט, \u0005ו\u0006היא \u0005עגונה ויושבת]\u0006 וממתינה לבעלה ואיננה נישאת לאחר. \u0003ו\u0004כן \u0003משום\u0004 ה\u0003פרוצות, דאי אמרת\u0004 \u0005[שאם אומר אתה]\u0006 שכשהוא אנוס \u0003לא ליהוי גיטא\u0004 \u0005[יהא גט] —\u0006 \u0003זימנין דאניס\u0004 \u0005[פעמים ש\u0006הוא \u0005אנוס]\u0006 \u0003ואמרה לא אניס\u0004 \u0005[איננו אנוס]\u0006 \u0003ואזלא ומינסבא\u0004 \u0005[והולכת ונישאת],\u0006 \u0003ו\u0004כשמתגלה שהיה אנוס בדבר \u0003נמצא גט בטל ובניה\u0004 מהשני \u0003ממזרים.\u0004","על שיטה זו שההלכה שאין אונס בגיטין אינה מעיקר דיני הגט, אלא תקנת חכמים היא, שואלים: \u0003ומי איכא מידי דמדאורייתא לא להוי\u0004 \u0005[והאם יש דבר שמן התורה אינו]\u0006 \u0003גט, ומשום צנועות ומשום פרוצות שרינן\u0004 \u0005[מתירים אנו]\u0006 \u0003אשת איש לעלמא\u0004 \u0005[לעולם,\u0006 להינשא לכול\u0005]?!\u0006","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 בכוח חכמים לתקן כך, כי \u0003כל\u0004 מי ש\u0003מקדש\u0004 אשה, \u0003אדעתא דרבנן\u0004 \u0005[על דעת החכמים]\u0006 הוא \u0003מקדש, ו\u0004במקרה כגון זה \u0003אפקעינהו רבנן לקידושי מיניה\u0004 \u0005[הפקיעו חכמים את הקידושין ממנו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: תינח קדיש בכספא\u0004 \u0005[ניחא,\u0006 נוח הסבר זה יהיה, אם \u0005קידש בכסף],\u0006 שאז אפשר לומר שבית הדין הפקיר את כסף הקידושין ונמצא שלא היו קידושין כלל. אולם אם \u0003קדיש\u0004 \u0005[קידש]\u0006 את האשה \u0003בביאה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 והשיב לו: \u0003שויוה רבנן\u0004 \u0005[עשו,\u0006 החשיבו \u0005חכמים]\u0006 \u0003לבעילתו בעילת זנות,\u0004 שהפקיעו את צד קניין הקידושין שיש בביאה זו. עד כאן לשון אחת בדברי רבא.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רבא\u0004 להיפך: \u0003וכן לענין גיטין\u0004 מתחשבים באונס. ומסיקים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבור]\u0006 \u0003רבא\u0004 כי \u0003יש\u0004 להתחשב ב\u0003אונס ב\u0004ענין \u0003גיטין.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003\"הרי זה גיטיך אם לא באתי מכאן ועד שנים עשר חדש\", ומת בתוך שנים עשר חדש — אינו גט.\u0004 ונדייק: \u0003מת — הוא\u0004 ש\u0003אינו גט,\u0004 שהרי אין גט לאחר מיתה, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003חלה — הרי זה גט,\u0004 ואין אומרים שהאונס מבטל את התנאי!","ודוחים: \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי ב\u0003חלה נמי\u0004 \u0005[גם כן]\u0006 \u0003אינו גט, והיא גופה קא משמע לן\u0004 \u0005[ואותה\u0006 הלכה \u0005עצמה השמיע לנו],\u0006 שיש בכך חידוש: ש\u0003אין גט\u0004 חל \u0003לאחר מיתה.\u0004","ותוהים: דבר זה ש\u0003אין גט לאחר מיתה הא תנא ליה רישא\u0004 \u0005[הרי שנה אותו\u0006 ב\u0005תחילה]\u0006 ואין בכך חידוש! ומשיבים: \u0003דלמא לאפוקי\u0004 \u0005[שמא\u0006 בא \u0005להוציא]\u0006 \u0003מ\u0004דברי \u0003רבותינו\u0004 שאמרו שבכגון זה הריהו גט, משום שדנים לפי זמן כתיבת הגט ולא לפי הזמן שהתנה שיחול בו.","ומקשים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: האומר לאשה: \u0003\"\u0004הרי זה גיטך \u0003מעכשיו אם לא באתי מכאן ועד שנים עשר חדש\", ומת בתוך שנים עשר חדש — הרי זה גט. מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003הוא הדין לחלה\u0004 בתוך שנים עשר חודש ולא בא, ומשמע שאין אונס בגיטין! ודוחים: \u0003לא, מת דוקא,\u0004 ולא מפני שאין אונס, אלא מטעם אחר, שאנו אומרים שהיתה כוונתו במה שאמר \"מעכשיו\", \u0003דלא ניחא ליה\u0004 \u0005[שאין נוח לו]\u0006 ש\u0003תפול קמי\u0004 \u0005[לפני]\u0006 ה\u0003יבם\u0004 לכשימות, ולכן אמר שהגט יחול למפרע מעכשיו.","ומביאים ראיה אחרת, \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע]\u0006 \u0003מההוא\u0004 \u0005[מאותו\u0006 אדם\u0005]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לעדים או לשלוחי הגט: \u0003\"אי\u0004 \u0005[אם]\u0006 \u0003לא אתינא\u0004 \u0005[אבוא]\u0006 \u0003מכאן ועד שלשים יום ליהוי גיטא\u0004 \u0005[שיהא\u0006 זה \u0005גט]\u0006 \u0003\". אתא\u0004 \u0005[בא]\u0006 \u0003בסוף תלתין יומין\u0004 \u0005[שלושים יום]\u0006 \u0003ופסקיה מברא\u0004 \u0005[והפסיקתו המעבורת]\u0006 ולא היה יכול לעבור את הנהר, \u0003ואמר להו\u0004 \u0005[להם],\u0006 לעומדים בצד השני של הנהר: \u0003\"חזו דאתאי, חזו דאתאי\u0004 \u0005[ראו שבאתי, ראו שבאתי]\u0006 \u0003\"! ואמר שמואל: לא שמיה מתיא\u0004 \u0005[אין שמה,\u0006 אינה נחשבת \u0005הגעה],\u0006 ומשמע שאין אונס בגיטין!","ומשיבים: \u0003אונסא דשכיח\u0004 \u0005[אונס שמצוי] —\u0006 \u0003שאני\u0004 \u0005[שונה],\u0006 ש\u0003כיון דאיבעי ליה\u0004 \u0005[שהיה לו]\u0006 להעלות אפשרות זו על דעתו שבמקרה כזה יבוטל הגט ו\u0003לאתנויי\u0004 \u0005[\u0006ו\u0005להתנות],\u0006 \u0003ולא אתני\u0004 \u0005[התנה] —\u0006 \u0003איהו הוא דאפסיד אנפשיה\u0004 \u0005[הוא שהפסיד לעצמו].\u0006","\u0003אמר רב שמואל בר יצחק: לא שנו\u0004 הלכה זו שבתולה נישאת ביום הרביעי בשבוע, \u0003אלא מתקנת עזרא ואילך,\u0004 שתיקן \u0003שאין בתי דינין קבועין אלא בשני ובחמישי. אבל קודם תקנת עזרא ש\u0004היו \u0003בתי דינין קבועין בכל יום — אשה נשאת בכל יום.\u0004","ותוהים: \u0003קודם תקנת עזרא? מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 ומה לו לרב שמואל לפסוק הלכה בדבר שכבר עבר! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אי איכא\u0004 \u0005[אם יש]\u0006 מקום שבו \u0003בתי דינין\u0004 ש\u0003קבועין האידנא\u0004 \u0005[עכשיו,\u0006 בזמן הזה\u0005]\u0006 בכל יום \u0003כקודם תקנת עזרא\u0004 — הרי \u0003אשה נשאת בכל יום.\u0004","ומקשים: והרי יש טעם נוסף לנישואין ביום רביעי, שכן \u0003הא בעינן\u0004 \u0005[הרי צריכים אנו]\u0006 לקיים גם מה ש\u0003שקדו\u0004 חכמים על תקנת בנות ישראל, שתהא לו אפשרות לטרוח במשך ימים אחדים קודם לכן בהכנת הסעודה! ומשיבים: כאן מדובר \u0003דטריח ליה\u0004 \u0005[שטרח בה]\u0006 והכין כבר את כל צרכי הסעודה לפני שבת, ומכיון שכן, יכול לשאתה כבר ביום ראשון או שני."],["\u0003מאי\u0004 \u0005[מה\u0006 ענין\u0005]\u0006 \u0003\"שקדו\"\u0004 זה שאנו רואים בו מקור לתקנה? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003מפני מה אמרו בתולה נשאת ליום הרביעי? שאם היה לו טענת בתולים, היה משכים לבית דין.\u0004 ושאלו על ברייתא זו: \u0003ותנשא באחד בשבת, ואם היה לו טענת בתולים היה משכים לבית דין\u0004 ביום שני! והשיבו: \u0003שקדו חכמים על תקנת בנות ישראל, שיהא אדם טורח בסעודה שלשה ימים: אחד בשבת, ושני בשבת, ושלישי בשבת, וברביעי כונסה.\u0004","ומוסיפה הברייתא: \u0003ומ\u0004זמן ה\u0003סכנה ואילך נהגו העם לכנוס\u0004 גם \u0003ב\u0004יום \u0003שלישי, ולא מיחו בידם חכמים. וב\u0004יום \u0003שני לא יכנוס\u0004 אפילו בזמן הסכנה. \u0003ואם מחמת האונס — מותר.\u0004 ועוד הוסיפו: \u0003ומפרישין את החתן מן הכלה\u0004 ב\u0003לילי שבת תחלה,\u0004 כלומר, אם נישאו ביום שישי אין מניחים להם להתייחד בפעם הראשונה בליל שבת, \u0003מפני ש\u0004בבעילתו את הבתולה \u0003הוא עושה\u0004 בה \u0003חבורה,\u0004 שכן הוא קורע את קרום הבתולים, ועשיית חבורה אסורה בשבת.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 אותה \u0003סכנה\u0004 שהוזכרה? \u0003אילימא דאמרי\u0004 \u0005[אם תאמר שאמרו]\u0006 וגזרו השלטונות ש\u0003בתולה הנשאת ליום הרביעי תיהרג,\u0004 אם כן וכי בסכנה כעין זו רק \u0003נהגו\u0004 לכנוס בשלישי? \u0003לגמרי ניעקריה\u0004 \u0005[נעקרנה]\u0006 את תקנת הנישואין ביום רביעי, שוודאי אין להקפיד על תקנת חכמים במקום סכנת נפשות!","\u0003אמר רבה: דאמרי\u0004 \u0005[ש\u0006היו \u0005אומרים]:\u0006 \u0003בתולה הנשאת ביום הרביעי תיבעל להגמון\u0004 (לשר) \u0003תחלה.\u0004 ושואלים: אם כך, הרי הברייתא אינה מדוייקת, \u0003האי\u0004 \u0005[זו]\u0006 \u0003סכנה\u0004 היא? הלוא \u0003אונס הוא!\u0004 ומשיבים: שיש גם סכנה בדבר \u0003משום דאיכא\u0004 \u0005[שיש]\u0006 \u0003צנועות דמסרן נפשייהו לקטלא\u0004 \u0005[שמוסרות עצמן למיתה]\u0006 שלא להיבעל לאחר, \u0003ואתיין\u0004 \u0005[ויבואו]\u0006 \u0003לידי סכנה.\u0004","ושואלים: \u0003ולידרוש להו\u0004 \u0005[ושידרשו להן]\u0006 חכמים לצנועות ש\u0003אונס שרי\u0004 \u0005[מותר]\u0006 ואינן חייבות למסור את נפשן למיתה? ומשיבים: אי אפשר לדרוש ברבים שבאונס מותר להיבעל כי \u0003איכא\u0004 \u0005[יש]\u0006 \u0003פרוצות\u0004 שבשבילן לא יהא בדבר כל אונס, אלא תבעלנה מרצון, ואשה הנבעלת ברצון לאחר — אסורה לבעלה. \u0003ו\u0004עוד, \u0003איכא נמי\u0004 \u0005[יש גם כן]\u0006 בין הצנועות \u0003כהנות\u0004 האסורות לבעליהן אפילו אם נבעלו באונס. ובשל טעמים אלה אין לדרוש זאת כהלכה מוחלטת.","ושואלים: אם כך, שיש בדבר חשש סכנה לצנועות, אם כן \u0003וליעקריה\u0004 \u0005[ושיעקרוה]\u0006 את התקנה הזו של יום רביעי לגמרי ויקבעו יום אחר! ומשיבים: \u0003שמדא עביד דבטל\u0004 \u0005[\u0006גזירת \u0005שמד עשויה שתיבטל],\u0006 \u0003ותקנתא דרבנן מקמי שמדא לא עקרינן\u0004 \u0005[ותקנת חכמים מפני שמד אין אנו עוקרים]\u0006 לגמרי, אלא אין מקפידים בקיומה עד שתיבטל הגזירה. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שזה היה הטעם, מה הועילו אם כן כאשר שינו את יום הנישואין, הלא \u0003בשלישי נמי אתי ובעיל\u0004 \u0005[גם כן יבוא\u0006 ההגמון \u0005ויבעל]!\u0006 ומשיבים: \u0003מספיקא\u0004 \u0005[מ\u0006תוך \u0005ספק]\u0006 \u0003לא עקר נפשיה\u0004 \u0005[יעקור עצמו]\u0006 ממקומו ללכת למקום אחר, שהרי אין קביעות של נישואין ביום שלישי.","שנינו באותה ברייתא: \u0003ובשני לא יכנוס\u0004 אף בשעת הסכנה, \u0003ואם מחמת האונס — מותר.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אונס\"\u0004 זה? \u0003אילימא, הא דאמרן\u0004 \u0005[אם לומר, זהו שאמרנו],\u0006 גזירת הבעילה להגמון, הלא \u0003התם קרי ליה\u0004 \u0005[שם\u0006 בתחילה \u0005קורא לו]\u0006 \u0003\"סכנה\" והכא קא קרי ליה\u0004 \u0005[וכאן קורא לו]\u0006 \u0003\"אונס\"?! ותו\u0004 \u0005[ועוד\u0006 שואלים\u0005]:\u0006 מדוע \u0003התם\u0004 \u0005[שם]\u0006 בתחילה נאמר רק ש\u0003נהגו\u0004 להקדים, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 נאמר ש\u0003מותר?\u0004","\u0003אמר רבא:\u0004 האונס הוא, \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003שר צבא בא לעיר\u0004 ביום הרביעי ויש לחשוש שיחטפו אנשי הצבא את צורכי הסעודה. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005היה הדבר]?\u0006 \u0003אי דאתי וחליף\u0004 \u0005[אם\u0006 הוא \u0005בא ויוצא]\u0006 משם — \u0003ליעכב\u0004 \u0005[שיעכבו\u0006 את הנישואין\u0005]\u0006 ויעשו אותם בשבוע הבא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה],\u0006 אלא באופן \u0003דאתי וקבע\u0004 \u0005[ש\u0006הוא \u0005בא וקובע]\u0006 עצמו במקום. ושואלים: אם כן, \u0003בשלישי מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003לכנוס,\u0004 ולמה נתיר להקדים אפילו ליום שני? ומשיבים: \u0003אספרווא דידיה\u0004 \u0005[הפמליה שלו]\u0006 \u0003ב\u0004יום \u0003שלישי קאתו\u0004 \u0005[הם\u0006 \u0005באים]\u0006 ולכן היה צורך להקדים ליום שני.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מחמת האונס\"\u0004 — אונס מסוג אחר, \u0003כדתניא\u0004 \u0005[כ\u0006פי \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה פתו אפוי, וטבחו טבוח, ויינו מזוג\u0004 והכל מוכן לסעודת החתונה, \u0003ומת אביו של חתן או אמה של כלה\u0004 לפני מועד החתונה, אזי לפני הקבורה, קודם שחלה חובת האבילות, \u0003מכניסין את המת לחדר\u0004 אחר ואין קוברים אותו מיד, \u0003ואת החתן ואת הכלה\u0004 מכניסים \u0003לחופה\u0004 ומשיאים אותם,"],["\u0003ובועל\u0004 החתן \u0003בעילת מצוה ופורש\u0004 מיד מאשתו, וקוברים את המת, \u0003ונוהג שבעת ימי המשתה.\u0004 כי מאחר שכבר נשא, ימי חתונתו הינם לגביו כמו ימי הרגל ואין אבילות חלה עליו, \u0003ואחר כך נוהג שבעת ימי אבילות\u0004 על מתו. \u0003וכל אותן הימים,\u0004 מתחילת ימי המשתה עד אחרי ימי האבל, \u0003הוא ישן בין האנשים\u0004 (הגברים) \u0003והיא ישנה בין הנשים,\u0004 ואין מניחים אותם להתייחד. ומוסיפים: \u0003ואין מונעין תכשיטין מן הכלה\u0004 אפילו בשעת אבילות \u0003כל שלשים יום,\u0004 כדי שלא תתגנה על בעלה.","\u0003ו\u0004זה שנוהג שבעת ימי המשתה קודם, הוא \u0003דוקא\u0004 כשהמקרה שאירע הוא בדיוק כפי הלשון שבו נאמרו הדברים, כלומר, כשמת \u0003אביו של חתן או אמה של כלה,\u0004 משום שהם היו כרגיל הטורחים בצרכי החתונה, וכיון שמתו, אם לא ישתמשו עכשיו במה שהכינו לחתונה, \u0003דליכא איניש דטרח להו\u0004 \u0005[שאין אדם\u0006 אחר \u0005שטורח עבורם]\u0006 להכין להם משתה חתונה מחדש, התירו להם לדחות את האבילות, \u0003אבל איפכא\u0004 \u0005[להיפך],\u0006 כגון שמתו אמו של חתן או אביה של הכלה — \u0003לא,\u0004 שכיון שיש מי שיטרח אחר כך להכין משתה נוסף, עליהם לנהוג תחילה באבילות, שחלה קודם הנישואין.","\u0003אמר רפרם בר פפא אמר רב חסדא: לא שנו\u0004 שעושים מיד את החתונה \u0003אלא שנתן\u0004 כבר \u0003מים על גבי בשר,\u0004 ואי אפשר עוד למכרו לאחרים, ואם לא יבשלוהו מיד יהיה הפסד מרובה ושמא יגרום שייבטלו מסעודת חתונה, \u0003אבל\u0004 אם \u0003לא נתן\u0004 עדיין \u0003מים על גבי בשר — מזדבן\u0004 \u0005[נמכר\u0006 הוא\u0005],\u0006 ואין זה הפסד מרובה, ואין דוחים בגלל זה את האבילות.","\u0003אמר רבא: ובכרך\u0004 שיש בו מטבע הדברים קונים רבים, \u0003אף על פי שנתן מים על גבי בשר — מזדבן\u0004 \u0005[נמכר\u0006 הוא\u0005],\u0006 ואין צורך לדחות. \u0003אמר רב פפא: ובכפר, אף על פי שלא נתן מים על גבי בשר — לא מזדבן\u0004 \u0005[אינו נמכר],\u0006 שאין למצוא בכפר קונים לכמות גדולה של בשר. ושואלים: אם כן, שדין זה אינו קיים לא בכרך ולא בכפר, \u0003ואלא\u0004 הלכה זו של \u0003רב חסדא\u0004 המבדילה בין אם כבר נתנו מים לבין אם עדיין לא נתנו, \u0003היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה]?\u0006 \u0003אמר רב אשי: כגון\u0004 בעירו \u0003מתא מחסיא, דמפקא\u0004 \u0005[שמוצאת,\u0006 שאינה\u0005]\u0006 \u0003מ\u0004כלל \u0003כרך,\u0004 שהיא קטנה יותר, \u0003ומפקא\u0004 \u0005[ומוצאת]\u0006 \u0003מ\u0004כלל \u0003כפר,\u0004 שהיא גדולה ממנו.","\u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב חסדא: הרי שהיה פתו אפויה וטבחו טבוח ויינו מזוג, ונתן מים על גבי בשר, ומת אביו של חתן או אמה של כלה — מכניסין את המת לחדר, ואת החתן ואת הכלה לחופה, ובועל בעילת מצוה ופורש, ונוהג שבעת ימי המשתה ואחר כך נוהג שבעת ימי אבילות. וכל אותן הימים הוא ישן בין האנשים ואשתו ישנה בין הנשים.\u0004","\u0003וכן מי שפירסה אשתו\u0004 (כלומר, הכלה) בשעת חופתה \u0003נדה — הוא ישן בין האנשים והיא ישנה בין הנשים,\u0004 עד שתיטהר מנידתה. \u0003ואין מונעין תכשיטין מן הכלה\u0004 כשהיא אבילה \u0003כל שלשים יום. בין כך ובין כך,\u0004 כלומר, בכל מקרה \u0003לא יבעול\u0004 החתן את הכלה בעילה ראשונה, \u0003לא בערב שבת\u0004 בגלל החבורה כמו שהסברנו, \u0003ולא במוצאי שבת.\u0004","ומפרשים את פרטי הדברים: \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003הוא ישן בין האנשים והיא ישנה בין הנשים.\u0004 ומעירים: \u0003מסייע ליה\u0004 \u0005[לו]\u0006 דבר זה \u0003ל\u0004שיטת \u0003ר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן: אף על פי שאמרו אין אבילות במועד,\u0004 ואין נוהגים במועד מנהגי אבילות, \u0003אבל דברים של צינעא,\u0004 כלומר, ענייני אבילות שנעשים בצינעה ואינו ניכר לבריות שהוא אבל — \u0003נוהג,\u0004 ואסור בהם. ותשמיש המיטה הרי הוא מדברים שבצינעה, ולכן החתן והכלה אף שלגביהם ימי החתונה הם כימי המועד — אסורים בתשמיש, ואף בייחוד, שמא יבואו לידי תשמיש.","\u0003דרש רב יוסף בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לא שנו\u0004 שאין מניחים לחתן ולכלה להתייחד כשפירסה נדה, \u0003אלא\u0004 כאשר \u0003לא בעל\u0004 אותה כלל, \u0003אבל\u0004 אם \u0003בעל\u0004 ואחר כך פירסה נידה — \u0003אשתו ישנה עמו\u0004 ואין לחשוש לבעילה.","ותוהים: \u0003והא הכא\u0004 \u0005[והרי כאן]\u0006 באבילות, \u0003דבבעל עסקינן\u0004 \u0005[\u0006במקרה \u0005שבעל\u0006 כבר \u0005אנו עוסקים],\u0006 שהרי התירו לו לבעול בעילת מצוה, \u0003וקתני\u0004 \u0005[ושנה\u0006 בכל זאת\u0005]:\u0006 \u0003הוא ישן בין האנשים והיא ישנה בין הנשים!\u0004 ודוחים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 דין זה שכשכבר בעל אשתו ישנה עמו, הרי זה רק במקרה ש\u0003פירסה אשתו נדה\u0004 ולא באבילות.","ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"וכן\" קתני\u0004 \u0005[שנה],\u0006 משמע שהאבל ומי שפירסה אשתו נידה דינם שוה!"],["\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003וכן מי שפירסה אשתו נדה ולא בעל — הוא ישן בין האנשים, ואשתו ישנה בין הנשים,\u0004 ואולם האבל אפילו בעל כבר — הוא ישן בין האנשים והיא בין הנשים.","ושואלים: \u0003למימרא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 ולהסיק מכאן ש\u0003אבילות קילא ליה\u0004 \u0005[קלה לו,\u0006 בעיניו\u0005]\u0006 \u0003מנדה?\u0004 שהרי אם נידה היא, סומכים עליו אחרי שבעל ואין חוששים שיבוא לבעול אותה, ובאבילות אנו חוששים לכך ואין מניחים להם להתייחד.","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יצחק בר חנינא אמר רב הונא: כל מלאכות שאשה עושה לבעלה\u0004 (בשביל בעלה) — גם אשה \u0003נדה עושה\u0004 אותן המלאכות \u0003לבעלה, חוץ ממזיגת הכוס והצעת המטה\u0004 שלו, \u0003והרחצת\u0004 (רחיצת) \u0003פניו ידיו ורגליו\u0004 שהם דברים של חיבה, ויש בהם קירוב יתר, \u0003ואילו גבי אבילות תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אף על פי שאמרו\u0004 ש\u0003אין אדם רשאי לכוף את אשתו\u0004 כשהיא אבילה \u0003להיות כוחלת\u0004 את עיניה \u0003ולהיות פוקסת\u0004 את לחייה, \u0003באמת אמרו\u0004 (הלכה מקובלת היא): \u0003מוזגת לו הכוס, ומצעת לו המטה, ומרחצת לו פניו ידיו ורגליו.\u0004 הרי שבזמן אבילות אין אנו חוששים שמא מתוך דברים של חיבה שביניהם יבוא לבעול אותה, ובנידה אנו מרחיקים יותר!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאמרו שיש להרחיק, מדובר \u0003באבילות דידיה\u0004 \u0005[שלו],\u0006 ו\u0003כאן\u0004 שהקילו במזיגת הכוס ושאר דברים הגורמים לחיבה — \u0003באבילות דידה\u0004 \u0005[שלה],\u0006 שבאמת אבילות אינה חמורה בעיניו כאיסור נידה, אלא שכאשר האשה היא האבלה, גם אם יתגבר יצרו עליו — לא תשמע לו האשה, ולכן לא גזרו הרחקות יתירות.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 באותה ברייתא \u0003אביו של חתן או אמה של כלה קתני\u0004 \u0005[שנה],\u0006 ומכאן שאין הבדל אם היתה זו אבילות שלו או שלה! ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 והשווה אבילות שלו ושלה, הרי זה \u0003אשארא\u0004 \u0005[על השאר],\u0006 שאר דיני אבילות המוזכרים שם, אבל לא לענין מניעת הייחוד בין הבעל והאשה.","ומקשים עוד: \u0003ומי שאני\u0004 \u0005[והאם שונה]\u0006 \u0003בין אבילות דידיה\u0004 \u0005[שלו]\u0006 \u0003לאבילות דידה\u0004 \u0005[שלה]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מי שמת חמיו או חמותו\u0004 — \u0003אינו יכול לכוף את אשתו להיות כוחלת ולהיות פוקסת, אלא\u0004 אף הוא \u0003כופה\u0004 (הופך) את \u0003מטתו\u0004 כמנהג אבל, \u0003ונוהג עמה אבילות. וכן היא שמת חמיה או חמותה\u0004 — \u0003אינה רשאה להיות כוחלת ולהיות פוקסת, אלא\u0004 אף היא \u0003כופה מטתה ונוהגת עמו אבילות.\u0004 ומכל מקום לא נאמר באבילות שלו שצריך להיזהר שלא יתייחד עמה.","ומשיבים: \u0003תני\u0004 \u0005[שנה\u0006 והוסף כך\u0005]:\u0006 \u0003באבילות דידיה\u0004 \u0005[שלו]\u0006 \u0003הוא ישן בין האנשים ואשתו ישנה בין הנשים.\u0004 ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"וכן\" קתני\u0004 \u0005[שנה].\u0006 משמע שאין הבדל בין המקרים! ומשיבים: \u0003כי קתני\u0004 \u0005[כאשר שנה]\u0006 \"וכן\", הרי זה רק לענין \u0003כיחול ופירכוס.\u0004 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"עמו\" קתני\u0004 \u0005[שנה],\u0006 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003עמו במטה,\u0004 ואף על פי כן אין חוששים שיבעל אותה! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003עמו בבית. וכדאמר ליה\u0004 \u0005[וכפי שאמר לו]\u0006 \u0003רב לחייא בריה\u0004 \u0005[בנו]\u0006 כשמת אביה של אשתו: \u0003באפה\u0004 \u0005[בפניה]\u0006 של אשתך \u0003נהוג אבילותא\u0004 \u0005[\u0006ב\u0005אבילות],\u0006 ש\u0003לא באפה\u0004 \u0005[בפניה]\u0006 \u0003לא תנהוג אבילותא\u0004 \u0005[אבילות],\u0006 אף כאן הכוונה \"עמו\" — בפניו.","\u0003רב אשי אמר\u0004 שהשאלה ששאלנו אינה נכונה מעיקרה: \u0003מי קמדמית אבילותא דהכא לאבילותא דעלמא\u0004 \u0005[האם\u0006 יכול אתה \u0005לדמות אבילות של כאן לאבילות בכלל]?\u0006 שהרי \u0003אבילותא דעלמא חמיר\u0004 \u0005[אבילות בכלל חמורה]\u0006 היא עליו \u0003ולא אתי\u0004 \u0005[יבוא]\u0006 \u0003לזלזולי ביה\u0004 \u0005[לזלזל בה],\u0006 ואילו \u0003אבילות דהכא\u0004 \u0005[של כאן],\u0006 \u0003כיון דאקילו רבנן\u0004 \u0005[שהקילו\u0006 בה \u0005חכמים],\u0006 \u0003אתי לזלזולי ביה\u0004 \u0005[יבוא לזלזל בה].\u0006","ושואלים: \u0003מאי קולא\u0004 \u0005[מה\u0006 היא \u0005ההקלה]\u0006 שהקלו פה חכמים? \u0003אילימא דקתני\u0004 \u0005[אם תאמר\u0006 מה \u0005ששנה]\u0006 ש\u0003בועל בעילת מצוה ופורש\u0004 — אולם \u0003התם\u0004 \u0005[שם]\u0006 הלא הטעם הוא \u0003משום\u0004 ש\u0003לא חל עליו\u0004 עדיין \u0003אבילותא\u0004 \u0005[\u0006דין \u0005אבילות],\u0006 שכן אבילות מתי היא מתחילה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר — עד שיצא\u0004 המת \u0003מפתח הבית\u0004 לקבורה, \u0003אי\u0004 \u0005[אם]\u0006 \u0003ל\u0004דעת \u0003ר' יהושע — עד שיסתם הגולל\u0004 (כיסוי הקבר), וכאן, כיון שהמת לא הוצא עדיין מן הבית אלא הוא בחדר — לא חלים על קרוביו דין אבילות, ואין כאן איפוא שום הקלה בדין אבילות.","\u0003אלא\u0004 יש לומר כי ההקלה היא בכך, \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003נוהג שבעת ימי המשתה ואחר כך נוהג שבעת ימי אבילות.\u0004 וכיון שהקלו עליו שנוהג בשמחת חתונה למרות שהוא אבל — שמא יחטא להקל באבלו, ולכן אסרו עליהם להתייחד.","באותה ברייתא \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בין כך ובין כך לא יבעול לא בערב שבת ולא במוצאי שבת.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003בערב שבת\u0004 לא יבעל \u0003משום חבורה\u0004 שעושה כאשר בא על בתולה, \u0003אלא במוצאי שבת אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004","\u0003אמר ר' זירא:\u0004"],["\u0003משום חשבונות\u0004 שמחשב במשך יום השבת מה עליו להכין לסעודה, ונמצא עוסק בשבת בדברי חול.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: וחשבונות של מצוה מי אסירי\u0004 \u0005[האם אסורים\u0006 הם\u0005]\u0006 בשבת? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב חסדא ורב המנונא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003חשבונות של מצוה מותר לחשבן בשבת! ו\u0004עוד \u0003אמר ר' אלעזר: פוסקין\u0004 (קובעים, מבטיחים) \u0003צדקה לעניים בשבת! ו\u0004כן \u0003אמר ר' יעקב אמר ר' יוחנן: הולכין לבתי כנסיות ולבתי מדרשות לפקח\u0004 (להשגיח) \u0003על עסקי רבים בשבת. ואמר ר' יעקב בר אידי אמר ר' יוחנן: מפקחין פיקוח נפש בשבת,\u0004 שדואגים בשבת לכל ענין שיכול להיות בו צד של פיקוח נפש.","\u0003ואמר רב שמואל בר נחמני אמר ר' יונתן: הולכין לטרטייאות ולקרקייאות\u0004 (תיאטראות וקרקסאות) \u0003לפקח על עסקי רבים בשבת,\u0004 שמא יוכלו להציל אדם מישראל, וכן שלא תבוא תקלה לישראל מאותם המקומות. \u0003ותנא דבי\u0004 \u0005[ושנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003מנשיא: משדכין,\u0004 מדברים ומשוחחים על כך בין המשפחות \u0003על התינוקת ליארס\u0004 ואפילו \u0003בשבת, ו\u0004כן מדברים \u0003על התינוק\u0004 כיצד \u0003ללמדו ספר\u0004 (לקרוא) \u0003וללמדו אומנות.\u0004 ומשמע מכל אלה שמותר לדבר ולחשוב חשבונות של מצוה בשבת, ונישואין, כמו כן, הרי הם מצוה, ואם כן ודאי טעם האיסור לשאת אשה במוצאי שבת אינו בשל האיסור בעריכת חשבונות בשבת!","\u0003אלא,\u0004 יש לדחות ולומר טעם אחר, \u0003אמר ר' זירא: גזירה שמא\u0004 מתוך טרדתו \u0003ישחוט\u0004 בשבת \u0003בן עוף\u0004 לצורך סעודת הלילה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 אם חושש אתה לכך, אם כן \u0003יום הכפורים שחל להיות בשני בשבת ידחה.\u0004 ומה טעם: \u0003גזירה שמא ישחוט\u0004 בשבת \u0003בן עוף\u0004 לסעודה של ערב יום הכיפורים, שגם היא סעודת מצוה! ודוחים: אין הדברים דומים, כי \u0003התם דלנפשיה\u0004 \u0005[שם\u0006 בערב יום כיפור \u0005ש\u0006הוא מכין ארוחה \u0005לעצמו] —\u0006 \u0003לא טריד\u0004 \u0005[אינו טרוד]\u0006 ולא ישכח ששבת היא, אבל \u0003הכא\u0004 \u0005[כאן]\u0006 שהוא מכין סעודה \u0003לאחרים — טריד\u0004 \u0005[\u0006הוא \u0005טרוד].\u0006 \u0003אי נמי\u0004 \u0005[או גם כן],\u0006 הבדל אחר: \u0003התם, אית ליה רווחא\u0004 \u0005[שם,\u0006 בערב יום כיפור, \u0005יש לו רווח\u0006 זמן\u0005],\u0006 שהרי יכול הוא לשחוט גם במשך היום, שאינו זקוק לסעודה מיד במוצאי שבת, ואילו \u0003הכא לית ליה רווחא\u0004 \u0005[כאן אין לו רווח\u0006 זמן\u0005],\u0006 שהסעודה היא בלילה, בזמן הנישואין.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך],\u0006 להסבר זה, הטעם שב\u0003ערב שבת\u0004 לא יבעל הוא \u0003נמי\u0004 \u0005[גם כן]\u0006 מאותו טעם — \u0003גזירה שמא ישחוט בן עוף\u0004 לסעודת הנישואין.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: האם \u0003בתולה נשאת ברביעי ונבעלת ברביעי\u0004 עצמו, \u0003ולא חיישינן לאיקרורי דעתא\u0004 \u0005[ואין אנו חוששים לקירור דעתו],\u0006 שכעסו יפוג במשך הלילה, אלא וודאי יבוא להתלונן למחרת, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003בתולה נשאת ברביעי ונבעלת בחמישי,\u0004 והטעם הוא משום \u0003דחיישינן לאיקרורי דעתא\u0004 \u0005[שאנו חוששים לקירור דעתו].\u0006","ומביאים ראיה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003בר קפרא: בתולה נשאת ברביעי ונבעלת בחמישי, הואיל ונאמרה בו\u0004 ביום חמישי \u0003ברכה\u0004 של \"פרו ורבו\" \u0003לדגים. אלמנה נשאת בחמישי ונבעלת בששי\u0004 ומדוע — \u0003הואיל ונאמרה בו\u0004 ביום השישי \u0003ברכה\u0004 של פריה ורביה \u0003לאדם.\u0004 ונדייק: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שעושים זאת, הוא דווקא \u0003משום ברכה, אבל משום איקרורי דעתא\u0004 \u0005[קירור דעת] —\u0006 \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006","על דברי בר קפרא מקשים לגופם: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אלמנה נמי\u0004 \u0005[גם כן]\u0006 \u0003תיבעל בחמישי, הואיל ונאמרה בו ברכה לדגים!\u0004 ומשיבים: \u0003ברכה\u0004 שנאמרה ל\u0003אדם עדיפא ליה\u0004 \u0005[עדיפה לו],\u0006 וכיון שאפשר לדחות את הדבר ליום שנאמרה בו ברכה לבני אדם, מוטב לעשות כן.","\u0003ואי נמי\u0004 \u0005[או גם כן],\u0006 מטעם אחר תיקנו יום זה לאלמנה: \u0003משום\u0004 ש\u0003שקדו\u0004 חכמים על תקנת בנות ישראל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003מפני מה אמרו אלמנה נשאת בחמישי ונבעלת בששי? שאם אתה אומר תיבעל בחמישי — למחר משכים\u0004 הבעל \u0003לאומנתו\u0004 (עבודתו) \u0003והולך לו\u0004 מאשתו, שהרי באלמנה אין נוהגים שבעת ימי משתה שהם כימי חג. ולכן \u0003שקדו חכמים על תקנת בנות ישראל, שיהא שמח עמה שלשה ימים: חמישי בשבת,\u0004 שהוא יום החתונה, \u0003וערב שבת,\u0004 של חובת הבעילה, \u0003ושבת.\u0004","ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש,\u0006 מה ההבדל למעשה\u0005]\u0006 \u0003בין\u0004 הטעם של \u0003\"ברכה\" ל\u0004טעם של \u0003\"שקדו\"?\u0004 שהרי מסקנת הדברים אחת היא. ומסבירים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005]\u0006 כשהחתן הוא \u0003אדם בטל,\u0004 שאינו הולך למלאכתו. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003יום טוב שחל להיות בערב שבת,\u0004 שבין כה וכה איננו יכול ללכת למלאכתו. שמטעם \"שקדו\" אין הבדל מתי יבעל, שהרי לא ילך למלאכתו, אבל מפני הנימוק של הברכה — צריך גם במקרה זה לבעול בשישי.","כיון שהבאנו דברי בר קפרא אלה, מביאים עוד מה ש\u0003דרש בר קפרא: גדולים מעשה צדיקים\u0004 וחשובים \u0003יותר ממעשה שמים וארץ,\u0004 ש\u0003אילו במעשה שמים וארץ כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"אף ידי יסדה ארץ וימיני טפחה שמים\"\u0004 (ישעיה מח, יג), משמע שהם נעשים ביד אחת, \u0003ואילו במעשה ידיהם של צדיקים,\u0004 בבנין בית המקדש, שהקדוש ברוך הוא משתתף בו, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"מכון לשבתך פעלת ה' מקדש אדני כוננו ידיך\"\u0004 (שמות טו, יז), ומלשון הכתוב משמע שדבר זה מתייחס לשתי ידיים, ולא ליד אחת.","\u0003השיב\u0004 (הקשה) \u0003בבלי אחד, ור' חייא שמו:\u0004 הלוא נאמר \u0003\"ויבשת ידיו יצרו\"\u0004 (תהלים צה, ה), הרי שאף בבריאת העולם נאמרו שתי ידיים! ומשיבים: \u0003\"ידו\" כתיב\u0004 \u0005[כתוב]\u0006 שהכתיב הוא חסר, ומרמז ללשון יחיד. ומקשים: \u0003והכתיב\u0004 \u0005[והרי כתוב]\u0006 \u0003\"יצרו\"\u0004 לשון רבים! \u0003אמר רב נחמן בר יצחק:\u0004 הכוונה היא ש\u0003יצרו אצבעותיו,\u0004 ו\u0003כדכתיב\u0004 \u0005[כפי שנאמר]:\u0006 \u0003\"כי אראה שמיך מעשה אצבעתיך ירח וכוכבים אשר כוננתה\"\u0004 (תהלים ח, ד).","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד: נאמר \u0003\"השמים מספרים כבוד אל ומעשה ידיו מגיד הרקיע\"\u0004 (תהלים יט, ב), הרי שאף הרקיע הוא מעשה שתי ידיו! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר,\u0006 כוונת הכתוב\u0005]:\u0006 \u0003מעשה ידיהם של צדיקים\u0004 שהם עושים רצונו של ה' \u0003מי מגיד — הרקיע, ומאי ניהו\u0004 \u0005[ומהו זה]\u0006 שהרקיע מגיד מעשה צדיקים — \u0003מטר\u0004 היורד מן הרקיע על ידי תפילתם של צדיקים.","ועוד \u0003דרש בר קפרא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ויתד תהיה לך על אזנך...\u0004 וכסית את צאתך\u0003\"\u0004 (דברים כג, יד) — \u0003אל תקרי\u0004 \u0005[תקרא]\u0006 \u0003\"\u0004על \u0003אזנך\" אלא \"על אוזנך\",\u0004 וכוונתו: \u0003שאם ישמע אדם דבר שאינו הגון\u0004 ומזוהם כצואה,"],["\u0003יניח אצבעו\u0004 (שצורתה כעין יתד) \u0003באזניו. והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' אלעזר: מפני מה אצבעותיו של אדם דומות ליתידות?\u0004 ומיד מבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם],\u0006 מה משמעותה של שאלה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהשאלה היתה \u0003משום דמחלקן\u0004 \u0005[ש\u0006הן \u0005מחולקות]\u0006 זו מזו ואינן מחוברות יחד, הלוא \u0003כל חדא וחדא\u0004 \u0005[אחת ואחת]\u0006 מן האצבעות \u0003למילתיה עבידא\u0004 \u0005[לעניינה\u0006 היא \u0005עשויה],\u0006 ודרושה לאדם לא רק לצרכי חולין אלא גם לצרכי שמיים. ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003זו,\u0004 האצבע הקטנה, היא \u0003זרת,\u0004 שממנה עד קצה הבוהן מודדים את מידת הזרת, המשמשת במעשה החושן, בבגדי הכהן הגדול. \u0003זו\u0004 שלאחריה היא \u0003קמיצה,\u0004 שבה מתחילים את קמיצת המנחות במקדש. \u0003זו\u0004 האמצעית היא \u0003אמה,\u0004 שמקצה אצבע זו עד המרפק היא מידת האמה. \u0003זו\u0004 שליד הבוהן היא \u0003אצבע,\u0004 שבה מזים את דם הקרבנות על המזבח. \u0003זה,\u0004 הבוהן, הוא \u0003גודל\u0004 שעליו נותנים דם ושמן לטהרת המצורע.","\u0003אלא\u0004 השאלה היתה: \u0003מה טעם משופות\u0004 (מחודדות) האצבעות \u0003כיתידות?\u0004 והטעם הוא — \u0003שאם ישמע אדם דבר שאינו הגון, יניח אצבעותיו באזניו.\u0004 כיוצא בו \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: מפני מה אוזן כולה קשה והאליה\u0004 שמתחתיה \u0003רכה? — שאם ישמע אדם דבר שאינו הגון, יכוף אליה לתוכה\u0004 של האוזן, כדי שלא ישמע. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אל ישמיע אדם לאזניו דברים בטלים, מפני שהן,\u0004 האזניים, רגישות ביותר ורואים אנו שהן \u0003נכוות תחלה\u0004 (ראשונה, קודם) \u0003לאיברים\u0004 אחרים, ולכן ראוי לו להיזהר שלא ייענש בהן על שמיעת דברים מגונים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]:\u0006 \u0003מהו לבעול בתחלה,\u0004 כלומר, לבעול בתולה, \u0003בשבת.\u0004 וצדדי השאלה: האם \u0003דם\u0004 בתולים \u0003מיפקד פקיד\u0004 \u0005[פקוד,\u0006 אצור וכנוס\u0005]\u0006 במקומו ורק שותת ויוצא על ידי הבעילה, \u0003או\u0004 שמא \u0003חבורי מיחבר\u0004 \u0005[מחובר\u0006 הוא בגוף\u0005]\u0006 ויוצא על ידי הדחיקה?","מכאן מפתחים ומרחיבים את הבעיות: \u0003ואם תימצי\u0004 (תרצה) \u0003לומר\u0004 ותחליט כי \u0003דם מיפקד פקיד\u0004 \u0005[פקוד]\u0006 ואין בבעילה משום איסור עשיית חבורה, אזי יש לשאול: האם בזמן הבעילה \u0003לדם הוא צריך, ושרי\u0004 \u0005[ומותר],\u0006 שהרי הוצאת דם כזה אין בה משום מלאכה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לפתח הוא צריך\u0004 שבקריעת קרום הבתולים עושה פתח, \u0003ואסיר\u0004 \u0005[ואסור]\u0006 לעשות פתח בשבת.","\u0003ואם תימצי לומר לדם הוא צריך ופתח ממילא קאתי\u0004 \u0005[מעצמו הוא בא],\u0006 שאינו מתכוון ליצור פתח, אלא תוך כדי הבעילה נוצר פתח זה מאליו, אזי השאלה היא: האם \u0003הלכה כ\u0004שיטת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 בדיני שבת כי \u0003דבר שאין מתכוין,\u0004 שאם עשה האדם דבר, ואגב כך, בלא להתכוון לכך, נעשתה מלאכה אחרת, הרי זה \u0003מותר, או הלכה כ\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003אמר\u0004 שגם \u0003דבר שאין מתכוין אסור?\u0004","\u0003ואם תימצי לומר\u0004 כי \u0003הלכה כ\u0004שיטת \u0003ר' יהודה\u0004 בדין זה, יש עוד לשאול: האם \u0003מקלקל הוא אצל הפתח,\u0004 שאפשר לומר שיצירת פתח זה היא בעצם קלקול, ולא מלאכה, שהיא לפי הגדרתה דווקא מלאכת תיקון, \u0003או מתקן הוא אצל הפתח?\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכך היו צדדי השאלה: \u0003ואם תימצי לומר\u0004 ש\u0003דם חבורי מיחבר\u0004 \u0005[מחובר\u0006 הוא בגוף\u0005]\u0006 ויוצא על ידי הדחיקה, האם בבעילה \u0003לדם הוא צריך, ואסור,\u0004 שהוא עושה חבורה בכוונה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003להנאת עצמו\u0004 שבבעילה \u0003הוא צריך, ושרי\u0004 \u0005[ומותר]?\u0006","\u0003ואם תימצי לומר להנאת עצמו הוא צריך, ודם ממילא קאתי\u0004 \u0005[מעצמו הוא בא]\u0006 ואינו מתכוון לו, האם — \u0003הלכה כ\u0004שיטת \u0003ר' יהודה\u0004 בדבר שאינו מתכוון \u0003או הלכה כ\u0004שיטת \u0003ר' שמעון?\u0004","\u0003ואם תימצי לומר\u0004 ש\u0003הלכה כ\u0004שיטת \u0003ר' יהודה\u0004 שאף דבר שאינו מתכוון אסור, עדיין יש לשאול: האם \u0003מקלקל\u0004 הוא \u0003בחבורה\u0004 זו \u0003או מתקן בחבורה\u0004 זו \u0003הוא?\u0004","\u0003ואם תימצי\u0004 (תרצה) \u0003לומר\u0004 כי \u0003מקלקל בחבורה הוא,\u0004 האם \u0003במקלקל הלכה כ\u0004שיטת \u0003ר' יהודה,\u0004 שהעושה בשבת מעשה של קלקול אינו חייב עליו, אפילו מכוון למעשהו,"],["\u0003או הלכה כ\u0004שיטת \u0003ר' שמעון,\u0004 שהמקלקל בחבורה חייב אם הוא עושה זאת מתוך כוונה תחילה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 לגבי פסק ההלכה בבעיה זו: \u0003בבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב אמרי\u0004 \u0005[\u0006היו \u0005אומרים]\u0006 כי \u0003רב שרי\u0004 \u0005[התיר]\u0006 \u0003ושמואל אסר. בנהרדעא,\u0004 עירו של שמואל, \u0003אמרי\u0004 \u0005[אומרים],\u0006 מוסרים את ההלכה להיפך: \u0003רב אסר ושמואל שרי\u0004 \u0005[התיר].\u0006 \u0003אמר רב נחמן בר יצחק: וסימניך\u0004 (הסימן לכך) לזכור את השיטות ומוסריהן: ש\u0003אלו מקילין לעצמן ואלו מקילין לעצמן.\u0004 שהצד השווה בשיטות אלה הוא שבכל מקום אומרים שהרב שהוא רבם (וכשיטתו הם נוהגים), הוא זה שהתיר.","לעצם הענין שואלים: \u0003ו\u0004האם \u0003רב שרי\u0004 \u0005[התיר]\u0006 בענין זה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב שימי בר חזקיה משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: האי מסוכריא דנזייתא\u0004 \u0005[אותו פקק\u0006 העשוי מסמרטוטים ששמים בנקב \u0005חבית\u0006 יין\u0005]\u0006 — \u0003אסור להדוקה ביומא טבא\u0004 \u0005[להדק אותו ביום טוב],\u0006 כי תוך כדי ההידוק נסחט המשקה מתוך האריג, וסחיטה אסורה בשבת וביום טוב. משמע מכאן שאפילו בדבר שאין מתכוון אוסר רב!","ומשיבים: מכאן אין קושיה, שכן \u0003ב\u0004ענין \u0003ההוא\u0004 של החבית, \u0003אפילו ר' שמעון מודה,\u0004 ש\u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\",\u0004 כלומר, כאשר הדבר הוא תוצאה הכרחית מן המעשה, כפי שהכרחי הוא שבעל חיים מת כאשר כורתים את ראשו, והעושה כן אינו יכול לומר שלא התכוון לכך. ולא התיר ר' שמעון בדבר שאינו מתכוון, אלא כאשר התוצאה שלא התכוון לה אינה הכרחית, ואילו כאן — בהכרח תהיה סחיטה כתוצאה מההידוק.","וחוזרים ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב חייא בר אשי אמר רב\u0004 במפורש: \u0003הלכה כר' יהודה\u0004 במלאכה שאינו מתכוון לה, \u0003ורב חנן בר אמי אמר שמואל: הלכה כר' שמעון. ורב חייא בר אבין מתני לה\u0004 \u0005[\u0006היה \u0005שונה\u0006 את ההלכות הללו\u0005]\u0006 \u0003בלא גברי\u0004 \u0005[\u0006שמות ה\u0005אנשים]\u0006 שמסרו אותן, אלא במישרין, \u0003רב אמר: הלכה כר' יהודה, ושמואל אמר: הלכה כר' שמעון.\u0004 ואם כן ברור שפסק רב כשיטת ר' יהודה. ואם כן כיצד התיר לבעול בתחילה בשבת?","ומסבירים: \u0003לעולם רב כר' יהודה סבירא ליה\u0004 \u0005[הוא סבור],\u0006 אלא \u0003להך לישנא דאמר\u0004 \u0005[לאותה לשון,\u0006 שיטה, \u0005שאמרנו]\u0006 ש\u0003דם מיפקד פקיד\u0004 \u0005[פקוד,\u0006 צבור הוא\u0005],\u0006 והחשש הוא רק בגלל עשיית פתח, צריך לומר שהוא סבור ש\u0003מקלקל הוא אצל הפתח,\u0004 ובזה אפילו ר' יהודה מתיר. ו\u0003להך לישנא דאמר\u0004 \u0005[לאותה לשון שאמרנו]\u0006 שה\u0003דם חבורי מיחבר\u0004 \u0005[מחובר],\u0006 צריכים לומר שלדעתו \u0003מקלקל בחבורה הוא,\u0004 ואף בזה ר' יהודה מתיר.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב חסדא:\u0004 וכי יש מקום לאסור ביאת בתולה בשבת? והלא שנינו: \u0003תינוקת שלא הגיע זמנה לראות\u0004 דם נידה \u0003ונשאת, בית שמאי אומרים: נותנין לה ארבעה לילות,\u0004 שאם היא נבעלת ורואה דם במשך ארבעת הלילות הראשונים, קובעים שהדם הזה הוא דם הבתולים ומותרת לבעלה, \u0003ובית הלל אומרים:\u0004 אין לכך קצבה, אלא \u0003עד שתחיה המכה\u0004 (יבריא הפצע) של הבתולים, גם אם נמשך הדבר זמן רב.","ואם \u0003הגיע זמנה לראות\u0004 כבר דם נידה, שהיא כבר נערה, אף על פי שלא ראתה עדיין \u0003ונשאת, בית שמאי אומרים: נותנין לה\u0004 רק \u0003לילה הראשון,\u0004 שמניחים שהדם שהיא רואה בלילה זה הוא דם בתולים, ובשאר הימים חוששים שמא דם נידה הוא, ואסור. \u0003ובית הלל אומרים:\u0004 נותנים לה זמן מיום רביעי, שהוא היום שנקבע כזמן מיועד לחתונת בתולה, \u0003עד מוצאי שבת,\u0004 שהם \u0003ארבעה לילות.\u0004 שבכל הלילות האלו מותרת לבעלה, ומניחים שהדם שרואה בימים אלו הוא דם בתולים."],["\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא כך: \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא בעל\u0004 אותה בעילה גמורה במשך הלילות הללו, \u0003מצי בעיל\u0004 \u0005[יכול\u0006 מותר לו \u0005לבעול]\u0006 אותה \u0003אפילו בשבת,\u0004 ואין חוששים לאיסור עשיית חבורה בשבת, ומכאן שמותר לבעול בתולה אפילו בשבת. \u0003אמר רבא: לא,\u0004 הכוונה היא \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מ\u0004יום ה\u0003שבת. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אי אפשר לפרש כך, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"עד מוצאי שבת ארבעה לילות\" קתני\u0004 \u0005[שנה],\u0006 ואין אתה מוצא מיום רביעי עד מוצאי שבת ארבעה לילות אלא אם כן אתה כולל ליל שבת ביניהם? \u0003אלא\u0004 חזר בו רבא, וכך \u0003אמר רבא:\u0004 הכוונה היא \u0003כשבעל\u0004 אותה תחילה בעילה גמורה לפני שבת, שכשיבעול בשבת לא תתעורר בעיה של עשיית חבורה.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003כשבעל\u0004 כבר בעילה גמורה, אם כן \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 באומרו שמותר לבעול אותה אפילו בשבת? ומסבירים: \u0003קא משמע לן דשרי למיבעל\u0004 \u0005[השמיע לנו שמותר לבעול]\u0006 \u0003בשבת,\u0004 אף שייתכן שמחמת הביאה יגרום להוצאת דם, ו\u0003כ\u0004דברי \u0003שמואל.\u0004 ש\u0003אמר שמואל: פירצה דחוקה\u0004 המצויה בכותל \u0003מותר ליכנס בה בשבת, ואף על פי שמשיר\u0004 על ידי כניסתו לשם \u0003צרורות\u0004 (אבנים) מן הכותל. וגם כאן, אף שייתכן שבביאתו הוא גורם להוצאת דם ולחבלה כלשהי — מכל מקום לא אסרו עליו בשל כך לבוא עליה בשבת.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף,\u0004 שנינו: \u0003חתן פטור מקרית\u0004 (מקריאת) \u0003שמע\u0004 ב\u0003לילה הראשון\u0004 של חתונתו \u0003עד מוצאי שבת אם לא עשה מעשה\u0004 (כלומר, אם לא בעל את האשה במשך הלילות הללו). ונברר: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הטעם שפטור משום \u0003דטריד\u0004 \u0005[ש\u0006הוא \u0005מוטרד]\u0006 במחשבתו \u0003דבעי למיבעל\u0004 \u0005[ש\u0006הוא \u0005רוצה לבעול\u0006 אותה\u0005]\u0006 ודואג אם יוכל לעשות זאת כראוי, וכיון שאמרו שפטור עד מוצאי שבת, ושבת בכלל — משמע שמותר לו לבעול בעילה ראשונה אפילו בשבת! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: לא,\u0004 אפשר לפרש \u0003דטריד\u0004 \u0005[ש\u0006הוא \u0005מוטרד]\u0006 מכך שעדיין \u0003לא בעיל\u0004 \u0005[בעל]\u0006 אותה עד עכשיו ולפיכך הוא פטור מקריאת שמע, ואין מכאן ראיה לגבי היתר בעילה בשבת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא\u0004 לאביי: לפי פירושך זה, שהוא דואג על דבר שאירע לו, \u0003ו\u0004כי \u0003משום טירדא\u0004 שיש לו \u0003פטור\u0004 מקריאת שמע? \u0003אלא מעתה,\u0004 אם \u0003טבעה ספינתו בים\u0004 והוא דואג בשל כך, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שהוא \u0003פטור\u0004 מלקרוא קריאת שמע?! \u0003וכי תימא הכי נמי\u0004 \u0005[ואם תאמר כך\u0006 הוא \u0005גם כן]\u0006 שמי שמוטרד בטירדה כזו אכן פטור מקריאת שמע — \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא בר זבדא אמר רב: אבל חייב בכל המצות האמורות בתורה חוץ מן התפילין,\u0004 משום \u0003שנאמר בהן \"פאר\"\u0004 (ראה יחזקאל כד, יז), ומכיון שהוא אבל ומושפל, אין ראוי שיניח תפילין, שאין ראוי לאבל לפאר את עצמו. ומכאן אפשר ללמוד, שאם אבל, שבודאי הוא דואג ומצטער, חייב בקריאת שמע, הוא הדין גם בשאר דאגות וטרדות. שהרי מן האבל אתה למד שהדאגה או הצער על דבר שאירע בעבר אינם פוטרים אותו מקריאת שמע, ואינו נפטר אלא כשמוטרד מחמת מצוה שהוא עומד לעשות בעתיד!","\u0003אלא אמר רבא:\u0004 יש לומר כי שאלה זו, אם מותר לבעול תחילה בשבת, \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא. דתנא חדא\u0004 \u0005[ששנה\u0006 בברייתא \u0005אחת]:\u0006 \u0003אם לא עשה מעשה ב\u0004לילה ה\u0003ראשון — פטור\u0004 מקריאת שמע \u0003אף ב\u0004לילה ה\u0003שני.\u0004 לא עשה מעשה \u0003ב\u0004לילה ה\u0003שני — פטור אף\u0004 אם בעל \u0003ב\u0004לילה ה\u0003שלישי\u0004 שהוא ערב שבת.","\u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003ראשון ושני — פטור, שלישי — חייב.\u0004 ויש לומר שהטעם שבשלישי חייב, הוא משום שהלילה השלישי הוא ליל שבת שבו בלאו הכי אסור לו לבעול. ומן ההבדל בין הברייתות אפשר ללמוד שיש מחלוקת תנאים אם מותר או אסור לבעול בתחילה בשבת.","ושואלים: \u0003ואביי,\u0004 מה הוא אומר על הוכחה זו? ומשיבים, הוא אומר: \u0003התם נמי בטירדא פליגי\u0004 \u0005[שם גם כן בטירדה\u0006 הם \u0005חולקים],\u0006 שאפשר לומר שכולם מודים שאסור לבעול בשבת, אלא בכך נחלקו: האם טירדה כזו שלא יכול היה לבעול בעבר, נחשבת כטירדה של מצוה ופוטרתו מקריאת שמע, או לא.","ומעירים, \u0003והני תנאי כי הני תנאי\u0004 \u0005[ותנאים אלה\u0006 שנחלקו סוברים \u0005כ\u0006דעת \u0005תנאים אלה,\u0006 אחרים\u0005],\u0006 שנחלקו במפורש באותו נושא עצמו. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הכונס את הבתולה\u0004 — \u0003לא יבעול\u0004 אותה \u0003בתחלה בשבת, וחכמים מתירין.\u0004 והרי מפורש כאן שיש מחלוקת תנאים בענין זה.","ושואלים: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003חכמים\u0004 אלה המתירים? \u0003אמר רבה:\u0004 דעת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: דבר שאין מתכוין מותר.\u0004 שכיון שאינו מתכוון למלאכה שתיעשה, אלא לבעילה בלבד, אין לחשוש אם עשה אותה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והא\u0004 \u0005[והרי]\u0006 \u0003מודה ר' שמעון ב\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\",\u0004 שאם התוצאה היא הכרחית (כפי שכריתת הראש חייבת להביא למוות), אף ר' שמעון מסכים שאין יכול להיפטר משום שלא התכוון לתוצאה זו, ואם כן אפשר לומר שהוא מודה בבעילה, כאשר ברור שעל ידי הבעילה יקרע את קרום הבתולים ויוציא דם! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003לא כהללו בבליים שאין בקיאין בהטייה,\u0004 שאינם יודעים לבעול באופן כזה שאינו משיר בתולים, \u0003אלא, יש בקיאין בהטייה,\u0004 שיודעים לבעול בלא לגרום לקריעת הבתולים, ואין זו תוצאה הכרחית של הבעילה ואין זה איפוא בגדר \"פסיק רישיה\".","ושואלים: אם יש דרך לבעול באופן זה, \u0003אם כן, טורד למה?\u0004 שכיון שבקי לבעול בלא להוציא דם, מה הטירדה והדאגה שיש בדבר, עד שיפטר מקריאת שמע! ומשיבים: טירדה זו מיוחסת \u0003ל\u0004זה \u0003שאינו בקי\u0004 בכך. ומקשים, אם כן, \u0003יאמרו: בקי — מותר\u0004 בבעילה בתחילה בשבת, \u0003שאינו בקי — אסור!\u0004 ודוחים: \u0003רוב\u0004 האנשים \u0003בקיאין הן\u0004 בכך, ומשום שהם הרוב אין כאן משום \"פסיק רישיה\", שעל פי הרוב התוצאה אינה הכרחית. לפיכך אמרו שמותר לבעול בתחילה בשבת.","ומקשים: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר רב חנן לאביי:\u0004 אם כן, אם אמנם רוב בקיאים הם, ויכולים לבעול בלא שתראה האשה דם בתולים, \u0003אלא מעתה שושבינין\u0004 שהיו מעמידים כדי לבדוק שאמנם היו בתולים ולא היתה רמאות בדבר, \u0003למה?\u0004 וכן \u0003מפה\u0004 (סדין) שהיו פורסים על המיטה כדי שייראה עליה דם בתולים, \u0003למה?\u0004 שהרי ייתכן שיבעל ולא ימצא דם, ולא יועילו השושבינים והמפה להוכיח אם היתה האשה בתולה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הטעם הוא \u0003שמא יראה\u0004 בכל זאת דם \u0003ויאבד\u0004 אותו בכוונה. שוודאי אם רצונו שלא להשיר את הבתולים יכול הוא לעשות זאת, אבל כאשר בא עליה ביאה גמורה וקורע קרום הבתולים רוצים שהעובדות תהיינה ברורות לחלוטין.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' אמי,\u0004 שנינו: \u0003המפיס מורסא\u0004 (עושה חור בפצע מלא מוגלה) \u0003בשבת, אם\u0004 כוונתו \u0003לעשות לה פה,\u0004 כלומר, שיישאר פתח קבוע במורסה כדי שתתייבש — הרי הוא \u0003חייב,\u0004 משום שעשה מלאכה (כעין בנין) בשבת. \u0003ואם\u0004 פתח אותה רק כדי \u0003להוציא ממנה\u0004 את ה\u0003ליחה\u0004 —"],["\u0003פטור.\u0004 והוסבר שם ש\"פטור\" זה כוונתו — פטור ומותר לכתחילה, ואם כן, מה ההבדל בין פתיחת המורסה לבין בעילת בתולה בשבת? ודוחים, יש הבדל: \u0003התם\u0004 \u0005[שם]\u0006 המוגלה שבמורסה היא \u0003פקיד\u0004 \u0005[פקודה,\u0006 עצורה\u0005],\u0006 במקום אחד \u0003ועקיר\u0004 \u0005[ועקורה]\u0006 מן הבשר, וכשהוא פותח אותה אינו יוצר דבר, אלא רק מניח לה לצאת. ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 לגבי דם בתולים, ברור אפילו לדעת האומר מפקד פקיד שהדם רק \u0003פקיד ולא עקיר\u0004 \u0005[עצור,\u0006 כנוס, \u0005ואינו עקור]\u0006 ועל ידי הבעילה עוקר אותו ממקומו, ויש בזה צד של מלאכה אסורה.","מסופר כי \u0003ר' אמי שרא למיבעל\u0004 \u0005[התיר\u0006 לאדם אחד \u0005לבעול]\u0006 אשה \u0003בתחילה בשבת. אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 עדיין \u0003לא כתיבא\u0004 \u0005[כתובה]\u0006 \u0003כתובתה,\u0004 ואמרו חכמים שהבא על אשה בלא כתובה הרי זו כבעילת זנות! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אתפסוה\u0004 \u0005[התפיסו לה]\u0006 \u0003מטלטלין,\u0004 כלומר, תנו לה לפני שבת מטלטלין משלו כדי ערך כתובה ויהיו אלה כמשכון לכתובתה עד שיכתוב לה כתובה כראוי, ואחר כך מותר יהיה לו לבעול.","ועוד מסופר: \u0003רב זביד שרא למיבעל\u0004 \u0005[התיר לבעול]\u0006 \u0003בתחלה בשבת. איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003רב זביד גופיה\u0004 \u0005[עצמו]\u0006 כשנשא אשה \u0003בעל בתחלה בשבת.\u0004","ועוד מסופר: \u0003רב יהודה שרא למיבעל\u0004 \u0005[התיר לבעול]\u0006 \u0003בתחלה\u0004 אשה \u0003ביום טוב. אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: לא תימא\u0004 \u0005[אל תאמר],\u0006 אל תסיק, מתוך השמועה הזו שדווקא \u0003ביום טוב\u0004 הוא \u0003דשרי\u0004 \u0005[שמותר],\u0006 \u0003הא\u0004 \u0005[הרי,\u0006 אבל\u0005]\u0006 \u0003בשבת אסור,\u0004 וכמו שהותרו ביום טוב כמה מלאכות שיש בהן צורך אוכל נפש, אף שבשבת הן אסורות. אלא ש\u0003הוא הדין\u0004 ש\u0003אפילו בשבת נמי שרי\u0004 \u0005[גם כן מותר],\u0006 \u0003ו\u0004אולם \u0003מעשה שהיה כך היה.\u0004 שמה שסיפרו שרב יהודה התיר ביום טוב הוא מפני שכך אירע הדבר, אבל אין להבין שההיתר הוא רק ביום טוב דווקא.","ואילו \u0003רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא אמר: ביום טוב שרי\u0004 \u0005[מותר]\u0006 אבל \u0003בשבת אסור.\u0004 ומעתה מביאים את הדיון בין שני חכמים אלה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפי לרב פפא: מאי דעתיך\u0004 \u0005[מה דעתך],\u0006 מהו הנימוק לפיו אתה מחלק בין שבת ליום טוב — שאתה סבור ש\u0003מתוך שהותרה\u0004 עשיית \u0003חבורה לצורך\u0004 אוכל נפש ביום טוב, כגון בשחיטה, \u0003הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך,\u0004 ואין איפוא איסור בעשיית חבורה ביום טוב, ומשום כך אף מותר לבעול בתולה ביום טוב. אולם, האם אפשר לסמוך על נימוק זה? \u0003אלא מעתה\u0004 לפי שיטתך \u0003מותר לעשות מוגמר\u0004 (קטורת על גבי גחלים) \u0003ביום טוב,\u0004 ולפי אותו נימוק: ש\u0003מתוך שהותרה הבערה לצורך\u0004 בישול ואפייה, \u0003הותרה נמי\u0004 \u0005[גם כן]\u0006 \u0003שלא לצורך,\u0004 כגון לעשיית מוגמר, והרי אנו יודעים שהדבר אסור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב פפא: \u0003עליך,\u0004 כלומר כנגד טענה כזו \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 לגבי יום טוב: \u0003\"אך אשר יאכל לכל נפש\u0004 הוא לבדו יעשה לכם\u0003\"\u0004 (שמות יב, טז), והכוונה היא: \u0003דבר השוה לכל נפש.\u0004 ולכן אין להתיר עשיית מוגמר משום שאינו דבר השווה לכל נפש, שמוגמר הוא דבר שרק יחידים נהנים ממנו, ומשום כך לא הותרה עשייתו. מה שאין כן לגבי בעילה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: אלא מעתה,\u0004 לפי הסבר זה, אם \u0003נזדמן לו צבי ביום טוב, הואיל ואינו שוה לכל נפש,\u0004 שודאי אין זה מאכל מצוי, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003אסור למשחטיה\u0004 \u0005[לשחוט אותו]\u0006 ביום טוב מאותו נימוק, שאינו דבר השווה לכל נפש? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003דבר הצורך לכל נפש קאמינא\u0004 \u0005[אמרתי],\u0006 כלומר, הכוונה היא לדבר שכל נפש יכולה ליהנות ממנו, ו\u0003צבי צריך לכל נפש הוא,\u0004 אלא שקשה להשיג אותו. מה שאין כן במוגמר, שלא הכל נהנים ממנו ולא הכל זקוקים לו.","\u0003אמר ר' יעקב בר אידי, הורה ר' יוחנן ב\u0004עיר \u0003ציידן: אסור לבעול בתחלה בשבת.\u0004 ותחילה דנים בלשון: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 ומוצאים אנו לשון כזו של \u0003הוראה לאיסור?\u0004 כי בדרך כלל לשון הוראה משמעה דווקא ענין של חידוש, שהחכם מתיר דבר שהיה נראה לנו כאסור, אבל לאסור דבר כלשהו, אין צורך בהוראת חכם וכל אדם שספק לו איך צריך לנהוג, יכול לנהוג איסור כאוות נפשו.","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 מוצאים אנו שימוש לשון הוראה לאיסור, \u0003והתנן\u0004 \u0005[ואכן\u0006 כן \u0005שנינו\u0006 במשנה\u0005],\u0006 ביחס להילני המלכה שיצא בנה למלחמה ונדרה נזירות לשבע שנים, ונהגה כנדרה בהיותה בחוץ לארץ, ומשעלתה לארץ ישראל \u0003הורוה בית הלל שתהא נזירה עוד שבע שנים אחרות.\u0004 משמע שמשתמשים בלשון הוראה גם לאסור.","\u0003ואי נמי, כי הא דתניא\u0004 \u0005[או גם כן,\u0006 דוגמא נוספת, \u0005כמו זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003חוט השדרה\u0004 של בהמה \u0003שנפסק\u0004 (נחתך) \u0003ברובו,\u0004 הוא השיעור שתיעשה בו הבהמה טריפה, אלו \u0003דברי רבי. ר' יעקב אומר: אפילו\u0004 רק \u0003ניקב\u0004 החוט, הרי זה מטריף את הבהמה. ומספרים, כי הלכה למעשה \u0003הורה רבי כר' יעקב\u0004 לאסור אפילו בנקב. משמע שיש הוראה לאיסור. אגב אותו ענין \u0003אמר רב הונא: אין הלכה כר' יעקב,\u0004 אלא כרבי. למרות שרבי עצמו הורה כר' יעקב.","זו היתה גירסה אחת של השמועה הזו, ו\u0003רב נחמן בר יצחק מתני הכי\u0004 \u0005[היה שונה כך]:\u0006 \u0003אמר ר' אבהו, שאל ר' ישמעאל בן יעקב\u0004 ש\u0003מן\u0004 העיר \u0003צור את ר' יוחנן ב\u0004עיר \u0003ציידן, ואנא שמעי\u0004 \u0005[ואני שמעתי]\u0006 את השאלה והתשובה: \u0003מהו לבעול בתחלה בשבת? ואמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אסור.\u0004 ומסכמים למעשה את הסוגיה: \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003מותר לבעול בתחלה בשבת,\u0004 ואין חוששים לא מפני עשיית חבורה והוצאת דם או יצירת פתח, ולא לשאר חששות שהוזכרו בענין זה.","\u0003אמר ר' חלבו אמר רב הונא אמר ר' אבא בר זבדא אמר רב: אחת בתולה ואחת אלמנה\u0004 שנישאה \u0003טעונה ברכה\u0004 (ברכת חתנים). ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב הונא הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: אלמנה אינה טעונה ברכה!\u0004 ודוחים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 שאמר רב הונא שאלמנה טעונה ברכה, מדובר \u0003בבחור שנשא אלמנה,\u0004 ו\u0003כאן\u0004 שאמר רב הונא שאינה טעונה ברכה, מדובר \u0003באלמון\u0004 (אלמן) \u0003שנשא אלמנה.\u0004","ושואלים: \u0003ו\u0004כי \u0003אלמון שנשא אלמנה לא\u0004 טעון ברכה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן, אמר לי הונא בר נתן: תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003מנין לברכת חתנים\u0004 שנאמרת \u0003ב\u0004מעמד \u0003עשרה\u0004 אנשים? — \u0003שנאמר\u0004 בבועז כשנשא את רות: \u0003\"ויקח עשרה אנשים מזקני העיר ויאמר שבו פה וישבו\"\u0004 (רות ד, ב). \u0003ובועז\u0004 כשנשא את רות הלוא \u0003אלמון שנשא אלמנה הוה\u0004 \u0005[היה],\u0006 הרי שגם במקרה זה צריך לברך, שמכאן אנו למדים עיקר ברכה זו.","אלא יש לפרש \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינה טעונה ברכה\"\u0004 ש\u0003אמר רב הונא\u0004 — הכוונה היא ש\u0003אינה טעונה ברכה כל שבעה\u0004 ימים של הנישואין, \u0003אבל יום אחד\u0004 לכל הדעות \u0003טעונה ברכה.\u0004","ומקשים: \u0003אלא הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003שקדו חכמים על תקנת בנות ישראל שיהא\u0004 הנושא את האלמנה \u0003שמח עמה שלשה ימים,\u0004 ולכן תיקנו יום מסויים לחתונה. ונברר \u0003במאי\u0004 \u0005[במה\u0006 מדובר פה\u0005]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר פה \u0003בבחור\u0004 שנשא אלמנה, \u0003האמרת\u0004 \u0005[הרי אמרת]\u0006 ששמחתו היא \u0003שבעה\u0004 ימים, ולמה שקדו רק על שלושה? ו\u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 מדובר \u0003באלמון\u0004 שנשא אלמנה, \u0003האמרת\u0004 \u0005[הרי אמרת]\u0006 כי שמחתו רק \u0003יום אחד,\u0004 ומה ענין זה ששקדו על שלושה ימים?","ומשיבים: אפשר לפרש בכמה אופנים, \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 כך: \u0003באלמון\u0004 שנשא אלמנה — \u0003יום אחד\u0004 תיקנו \u0003לברכה, ושלשה\u0004 ימים תיקנו \u0003לשמחה,\u0004 ומשום כך תיקנו שתהיה חתונתו ביום חמישי, שישמח עמה לפחות שלושה ימים. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003בבחור\u0004 שנשא אלמנה — \u0003שבעה\u0004 ימים הם \u0003לברכה, ושלשה\u0004 ימים \u0003לשמחה\u0004 שיש בה גם ביטול מלאכה."],["\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003מברכין לבתולה שבעה\u0004 ימים \u0003ולאלמנה יום אחד. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003אפילו\u0004 ל\u0003אלמנה שנשאת לבחור\u0004 שמברכים לה רק יום אחד! ודוחים: \u0003לא,\u0004 הכוונה היא לאלמנה שנישאת \u0003לאלמון,\u0004 שאצלה יש רק יום אחד לברכה. ושואלים: \u0003אבל לבחור מאי\u0004 \u0005[מה]\u0006 יהא הדין, \u0003שבעה\u0004 ימים — \u0003אי הכי ליתני\u0004 \u0005[אם כן, שישנה]\u0006 בברייתא במפורש: \u0003מברכין לבתולה שבעה, ולאלמנה שנשאת לבחור שבעה, ולאלמנה\u0004 שנשאת לאלמון \u0003יום אחד,\u0004 ומדוע איפוא לא שנה גם מקרה זה?","ומשיבים: באמת יכול היה לשנות כך, אלא \u0003מילתא פסיקתא קתני\u0004 \u0005[דבר חתוך שנה]\u0006 בברייתא זו בלי להיכנס לחילוקי פרטים, ללמדנו \u0003דליכא\u0004 \u0005[שאין]\u0006 ברכה ל\u0003בתולה דבצרה\u0004 \u0005[שפחותה]\u0006 \u0003מ\u0004זמן של \u0003שבעה\u0004 ימים, \u0003וליכא\u0004 \u0005[ואין]\u0006 ברכה ל\u0003אלמנה דבצרה\u0004 \u0005[שפחותה]\u0006 \u0003מיום אחד,\u0004 אבל ייתכן שברכת אלמנה תהיה יותר מיום אחד.","כיון שהזכרנו את המקור לברכת חתנים, דנים עתה \u0003גופא\u0004 \u0005[\u0006ל\u0005גופה]\u0006 של אותה הלכה, \u0003אמר רב נחמן: אמר לי הונא בר נתן, תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003מנין לברכת חתנים\u0004 שצריכה להיות \u0003ב\u0004מעמד \u0003עשרה — שנאמר: \"ויקח עשרה אנשים מזקני העיר ויאמר שבו פה\"\u0004 (רות ד, ב). \u0003ור' אבהו אמר:\u0004 המקור לברכת חתנים הוא \u0003מהכא\u0004 \u0005[מכאן],\u0006 ממה שנאמר: \u0003\"במקהלות ברכו אלהים ה' ממקור ישראל\"\u0004 (תהלים סח, כז), ללמדנו שבמקהלות = בקהל, שהוא לפחות עשרה אנשים, מברכים את ה', כאשר יש ברכה שנוגעת ב\"מקור ישראל\" — בביאה שתוליד ילדים בישראל.","ושואלים: \u0003ורב נחמן בהאי קרא\u0004 \u0005[בכתוב זה]\u0006 שהביא \u0003ר' אבהו מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו],\u0006 מה למד הוא ממנו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך\u0006 הוא \u0005אותו]\u0006 \u0003לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003היה ר' מאיר אומר: מנין שאפילו עוברים שבמעי אמן אמרו שירה על הים\u0004 כשעברו את ים־סוף — \u0003שנאמר: \"במקהלות ברכו אלהים ה' ממקור ישראל\",\u0004 לומר שאפילו אלה שהיו ברחם (\"מקור\"), גם הם הצטרפו למקהלות שברכו את ה'. ושואלים: \u0003ואידך\u0004 \u0005[והאחר,\u0006 ר' אבהו\u0005],\u0006 מדוע אין הוא מפרש את הדברים כך? ומשיבים: \u0003אם כן,\u0004 שרק לצורך זה בא המקרא, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003\"מבטן\u0004 ישראל \u0003\", מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"ממקור\"\u0004 — הכוונה ודאי \u0003על עסקי מקור,\u0004 ללמדנו שברכה שמברכים בעסקי מקור צריכה שתהיה במקהלות.","ושואלים עוד: \u0003ור' אבהו בהאי קרא\u0004 \u0005[בכתוב זה]\u0006 שהביא \u0003רב נחמן מאי דריש ביה\u0004 \u0005[מה\u0006 הוא \u0005דורש בו],\u0006 מה לומד הוא ממנו? ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[\u0006דבר \u0005זה צריך לו]\u0006 לא לענין ברכת חתנים, אלא שבועז אסף עשרה אנשים כדי \u0003למידרש\u0004 \u0005[לדרוש]\u0006 בפניהם שאלו שאסרה תורה להם לבוא בקהל, הכוונה ל\u0003עמוני ולא\u0004 ל\u0003עמונית, מואבי ולא מואבית.\u0004 וראיה לדבר: \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שאסף אנשים רק \u0003ל\u0004צורך \u0003ברכה, לא סגיא\u0004 \u0005[די\u0006 לו\u0005]\u0006 \u0003דלאו\u0004 \u0005[שלא]\u0006 יהיו \u0003זקנים\u0004 (חכמים), שהרי לשם הברכה אין צורך בזקנים דווקא, וכיון שהביא עשרה זקנים, משמע שהיה בכך ענין של פסק הלכה.","\u0003ואידך\u0004 \u0005[והאחר,\u0006 רב נחמן\u0005]\u0006 אומר: \u0003אי סלקא דעתך למידרש\u0004 \u0005[אם עולה על דעתך\u0006 שהביא אותם כדי \u0005לדרוש],\u0006 האם \u0003לא סגיא\u0004 \u0005[די\u0006 לו\u0005]\u0006 \u0003דלאו\u0004 \u0005[שלא]\u0006 יהיו שם \u0003עשרה,\u0004 שהרי אין צורך במספר גדול של חכמים כדי לדון עימם בהלכה! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 ובכל זאת יש טעם שהביא עשרה — \u0003לפרסומי מילתא\u0004 \u0005[\u0006כדי \u0005לפרסם\u0006 את \u0005הדבר],\u0006 שכל דבר שרוצים שיהיה לו פרסום רחב עושים אותו בעשרה, \u0003וכדאמר ליה\u0004 \u0005[וכפי שאמר לו]\u0006 \u0003שמואל לרב חנא בגדתאה\u0004 \u0005[מבגדד]:\u0006 \u0003פוק ואייתי\u0004 \u0005[צא והבא]\u0006 \u0003לי בי עשרה\u0004 \u0005[עשרה\u0006 אנשים\u0005]\u0006 \u0003ואימא\u0004 \u0005[ואומר]\u0006 \u0003לך באנפייהו\u0004 \u0005[בפניהם]\u0006 הלכה שאני רוצה לפרסם: \u0003המזכה\u0004 מתנה \u0003לעובר — קנה\u0004 העובר, אף שעדיין לא בא לעולם. הרי שאף על פי שלעצם הענין אין צורך דווקא בעשרה, הרי כשהדבר נעשה בפני עשרה יש בזה משום פומבי, ולכן אפשר לפרש שבועז קרא לעשרה זקנים כדי לפרסם הלכה זו. \u0003ו\u0004אגב כך מעירים שעל כל פנים, באותו ענין שרצה שמואל לפרסם, אין הלכה כמותו, אלא \u0003הלכתא\u0004 \u0005[הלכה]\u0006 למעשה היא — \u0003המזכה לעובר לא קנה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים\u0006 בברייתא\u0005]:\u0006 \u0003מברכין ברכת חתנים בבית חתנים,\u0004 כלומר, בזמן החתונה. \u0003ר' יהודה אומר: אף בבית האירוסין מברכין אותה.\u0004","\u0003אמר אביי: ו\u0004דברי ר' יהודה אלה \u0003ב\u0004ארץ \u0003יהודה שנו, מפני ש\u0004שם הארוס \u0003מתייחד עמה\u0004 עם ארוסתו, ויש חשש שיבוא עליה, ולכן מברכים כבר אז ברכת חתנים.","\u0003תניא אידך\u0004 \u0005[שנוייה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003מברכין ברכת חתנים בבית חתנים, וברכת אירוסין בבית האירוסין.\u0004 ושואלים: \u0003ברכת האירוסין מאי\u0004 \u0005[מה]\u0006 \u0003מברך?\u0004 מה נוסח ברכה זו שמברכים באירוסין? \u0003רבין בר רב אדא ורבה בר רב אדא, תרוייהו משמיה\u0004 \u0005[שניהם משמו]\u0006 של \u0003רב יהודה אמרי\u0004 \u0005[אומרים]:\u0006 זהו נוסח הברכה: \u0003\"ברוך אתה ה' אלהינו מלך העולם אשר קדשנו במצותיו וצונו על העריות\u0004 (כלומר, שנתן לנו מצוה זו של איסורי עריות), \u0003ואסר לנו את הארוסות\u0004 (שהן אסורות לכל אדם, לאחרים — משום שדינן כאשת איש, ואף לארוס עצמו אסורות מדברי סופרים), \u0003והתיר לנו את הנשואות\u0004 לנו רק \u0003על ידי חופה וקדושין\".\u0004 ומוסיפים כי \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא\u0004 היה \u0003מסיים בה\u0004 בברכה זו \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב יהודה: \"ברוך אתה ה' מקדש ישראל על ידי חופה וקדושין\".\u0004","ומעירים: \u0003מאן דלא חתים\u0004 \u0005[מי שאינו חותם]\u0006 ברכה זו כרב אחא, אלא משאיר אותה בלא החתימה, סבור כי \u0003מידי דהוה\u0004 \u0005[כפי שהוא]\u0006 בענין \u0003ברכת\u0004 ה\u0003פירות\u0004 (כגון: \"בורא פרי העץ\") \u0003וברכת\u0004 ה\u0003מצות\u0004 (כגון: \"על המילה\", \"על השחיטה\" וכדומה) שבנוסח ברכות אלה יש רק פתיחה, אבל אין בהן חתימה. \u0003ומאן דחתים\u0004 \u0005[ומי שחותם]\u0006 בברכה זו של קידושין, סבור כי \u0003מידי דהוה אקידושא\u0004 \u0005[כפי שהוא\u0006 בענין \u0005קידוש],\u0006 שיש בנוסח הברכה בקידוש גם פתיחה וגם חתימה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מברכין ברכת חתנים בעשרה\u0004 אנשים \u0003כל שבעה\u0004 ימים של משתה החתונה. \u0003אמר רב יהודה: והוא שבאו פנים חדשות,\u0004 כלומר, כשבאו אנשים חדשים, שלא היו קודם לכן, מברכים שבע ברכות אלה בכל סעודה.","ושואלים לפרטי הדברים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מברך,\u0004 מה נוסח ברכת חתנים זו? \u0003אמר רב יהודה:\u0004 ברכה ראשונה מברכים \u0003\"ברוך אתה ה' אלהינו מלך העולם\u0004"],["\u0003שהכל ברא לכבודו\".\u0004","\u0003ו\u0004ברכה שניה — \u0003\"\u0004ברוך אתה ה'... \u0003יוצר האדם\", ו\u0004ברכה שלישית — \u0003\"\u0004ברוך אתה ה'...","\u0003אשר יצר את האדם בצלמו, בצלם דמות תבניתו, והתקין לו ממנו\u0004 (כלומר, מתוך עצמו, את האשה, כפי שנאמר: \"ויבן... את הצלע... אשר לקח מן האדם\". בראשית ב, כב) \u0003בנין עדי עד, ברוך אתה ה' יוצר האדם\".\u0004","ברכה רביעית — \u0003\"שוש תשיש ותגל העקרה\u0004 (היא כנסת ישראל, ציון), \u0003בקבוץ בניה לתוכה בשמחה\u0004 (בגאולת ישראל. ראה ישעיה נד א-ג), \u0003ברוך אתה ה' משמח ציון בבניה\".\u0004","ברכה חמישית — \u0003\"שמח תשמח ריעים האהובים\u0004 (החתן והכלה), \u0003כשמחך יצירך\u0004 (כפי ששמחת את יצירך, אדם הראשון) \u0003בגן עדן מקדם, ברוך אתה ה' משמח חתן וכלה\".\u0004","ברכה שישית — \u0003\"ברוך אתה ה' אלהינו מלך העולם אשר ברא ששון ושמחה, חתן וכלה, גילה, רינה, דיצה, חדוה, אהבה ואחוה ושלום וריעות. מהרה ה' אלהינו ישמע בערי יהודה ובחוצות ירושלים קול ששון וקול שמחה, קול חתן וקול כלה, קול מצהלות חתנים מחופתם ונערים ממשתה נגינתם\u0004 (כאמור בירמיה לג, יא), \u0003ברוך אתה ה' משמח חתן עם הכלה\".\u0004 אלה הן ברכות הנישואין. וכיון שמצרפים להן את הברכה על היין, הרי הן שבע ברכות.","מסופר: \u0003לוי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רבי בהלוליה\u0004 \u0005[בחתונתו]\u0006 של \u0003ר' שמעון בריה\u0004 \u0005[בנו]\u0006 של רבי, \u0003בריך\u0004 \u0005[ברך]\u0006 רק \u0003חמש\u0004 מהן. ו\u0003רב אסי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב אשי בהלוליה\u0004 \u0005[בחתונתו]\u0006 של \u0003מר בריה\u0004 \u0005[בנו],\u0006 \u0003בריך שית\u0004 \u0005[\u0006ו\u0005ברך שש]\u0006 ברכות.","מציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005בזה חלוקים]\u0006 חכמים אלה, \u0003דמר\u0004 \u0005[שחכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 כי \u0003חדא יצירה הואי\u0004 \u0005[יצירה אחת היתה],\u0006 שמתחילה נברא האדם בשני פרצופי־פנים: אחד זכר, ואחד נקבה, ולא היתה יצירה מיוחדת באשה אלא מאוחר יותר הפרידם זה מזה, ולכן אין צורך לכפול בברכות, גם \"יוצר האדם\" וגם ברכה נוספת של \"יצר את האדם בצלמו\", שהרי היא אותה יצירה עצמה. \u0003ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 ש\u0003שתי יצירות הואי\u0004 \u0005[היו].\u0006 ויצירת חוה היתה יצירה נפרדת, ולכן יש גם לברך את שתי הברכות.","ודוחים: \u0003לא, דכולי עלמא חדא יצירה הואי\u0004 \u0005[שלכל הדעות יצירה אחת היתה],\u0006 אלא \u0003מר\u0004 \u0005[חכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 כי \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מחשבה אזלינן\u0004 \u0005[אנו הולכים],\u0006 וכבר לפי המחשבה הראשונה היו צריכים להיות נפרדים האדם ואשתו, \u0003ומר\u0004 \u0005[וחכם\u0006 זה\u0005]\u0006 \u0003סבר\u0004 כי \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003מעשה אזלינן\u0004 \u0005[אנו הולכים],\u0006 ובמעשה נוצרו כיצירה אחת. \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003רב יהודה רמי\u0004 \u0005[הטיל,\u0006 השליך, הראה סתירה\u0005]:\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בפסוק אחד: \u0003\"ויברא אלהים את האדם בצלמו\u0004 בצלם אלהים ברא אותו\u0003\"\u0004 (בראשית א, כז), משמע שנברא יחידי, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר: \u0003\"זכר ונקבה בראם\"\u0004 (בראשית ה, ב), \u0003הא כיצד?\u0004 — \u0003בתחלה עלה במחשבה לבראות\u0004 (לברוא) \u0003שנים, ולבסוף נברא אחד,\u0004 ואחר כך הפרידם הקדוש ברוך הוא לשניים: זכר ונקבה.","מסופר: \u0003רב אשי איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב כהנא\u0004 בזמן חתונה. \u0003יומא קמא בריך כולהו\u0004 \u0005[\u0006ב\u0005יום הראשון ברך\u0006 את \u0005כולן],\u0006 את כל שש הברכות הללו, \u0003מכאן ואילך אי איכא\u0004 \u0005[אם יש,\u0006 היו\u0005]\u0006 שם \u0003פנים חדשות\u0004 אורחים שלא היו קודם לכן — \u0003בריך כולהו\u0004 \u0005[ברך\u0006 את \u0005כולן],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 היו שם פנים חדשות, היה אומר: \u0003אפושי\u0004 \u0005[תוספת]\u0006 \u0003שמחה בעלמא הוא\u0004 \u0005[סתם היא]\u0006 ו\u0003מברך\u0004 רק \u0003\"שהשמחה במעונו\" ו\"אשר ברא\".\u0004","ועוד לענין הלכות ברכות נישואין: \u0003משבעה\u0004 ימים לאחר הנישואין \u0003ועד שלשים,\u0004 כשעושים סעודה ואוכלים בה, \u0003בין אמר להו\u0004 \u0005[להם,\u0006 לאורחים\u0005]\u0006 שהוא מזמין אותם \u0003מחמת הלולא\u0004 \u0005[החתונה],\u0006 \u0003ובין\u0004 ש\u0003לא אמר להו\u0004 \u0005[להם]\u0006 שמזמינם לסעודה \u0003מחמת הלולא\u0004 \u0005[החתונה]\u0006 \u0003— מברך\u0004 בסעודה שהחתן והכלה נמצאים שם \u0003\"שהשמחה במעונו\". מכאן ואילך\u0004 לאחר שלושים יום, \u0003אי\u0004 \u0005[אם]\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 שהוא מזמינם \u0003מחמת הלולא\u0004 \u0005[החתונה] —\u0006 \u0003מברך \"שהשמחה במעונו\", ואי\u0004 \u0005[ואם]\u0006 \u0003לא — לא.\u0004","ושואלים: \u0003וכי אמר להו\u0004 \u0005[וכאשר\u0006 הוא \u0005אומר להם]\u0006 כי \u0003מחמת הלולא\u0004 \u0005[החתונה]\u0006 הוא מזמין אותם, \u0003עד אימת\u0004 \u0005[מתי]\u0006 מברכים \"שהשמחה במעונו\"? \u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: עד תריסר ירחי שתא\u0004 \u0005[שנים עשר חודשי שנה]\u0006 מהחתונה אפשר לומר שהוא עדיין בגדר חתן, ואפשר לברך \"שהשמחה במעונו\". ושואלים: \u0003ומעיקרא מאימת\u0004 \u0005[ומתחילה,\u0006 מלפני הנישואין, \u0005מאימתי]\u0006 מברכים ברכה זו על השמחה? \u0003אמר רב פפא: מכי רמו שערי באסינתא\u0004 \u0005[מאותו\u0006 זמן שבו \u0005מטילים\u0006 את \u0005השעורים במכתשת]\u0006 לעשות מהן שיכר לחתונה. ושואלים: \u0003איני\u0004 \u0005[הכן הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב פפא\u0004 עצמו \u0003איעסק\u0004 \u0005[היה מתעסק]\u0006 בחתונתו של \u0003אבא מר בריה\u0004 \u0005[בנו],\u0006 \u0003ובריך\u0004 \u0005[וברך]\u0006 ברכת נישואין עוד \u0003משעת אירוסין!\u0004 ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003רב פפא דהוה טריח ליה\u0004 \u0005[שהיה\u0006 הכל כבר עשוי ו\u0005טרוח עבורו],\u0006 וכיון שהכל כבר היה מוכן לחתונה והיה כאן רק ענין של המתנה ליום הקבוע, התחילה שמחת החתונה כבר משעת אירוסין.","וכן מסופר: \u0003רבינא איעסק ליה לבריה בי\u0004 \u0005[רבינא עסק לו\u0006 בחתונתו \u0005של בנו בבית]\u0006 \u0003רב חביבא\u0004 שהיה אבי הכלה, \u0003ובריך\u0004 \u0005[וברך]\u0006 \u0003משעת אירוסין אמר: קים\u0004 \u0005[מוחזק]\u0006 \u0003לי בגוייהו\u0004 \u0005[בהם]\u0006 ש\u0003לא הדרי בהו\u0004 \u0005[יחזרו בהם]\u0006 מן האירוסין ואפשר לסמוך על כך שהחתונה תיעשה בזמנה. ומעירים: אף־על־פי־כן \u0003לא אסתייע מילתא\u0004 \u0005[הסתייע הדבר]\u0006 \u0003והדרי בהו\u0004 \u0005[וחזרו בהם]\u0006 לבסוף, ובטלה החתונה. מסופר: \u0003רב תחליפא בר מערבא\u0004 \u0005[בן ארץ ישראל]\u0006 \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003לבבל, בריך שית אריכתא\u0004 \u0005[ברך שש\u0006 ברכות \u0005ארוכות],\u0006 שהוסיף דברים בשש ברכות הנישואין מענין נוסח הברכה. ומעירים: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו],\u0006 שאין עושים כך, אלא שומרים על המטבע הקבוע של הברכה.","ועוד מספרים: \u0003רב חביבא איקלע לבי מהולא\u0004 \u0005[הזדמן לבית\u0006 שהיתה בו ברית \u0005מילה],\u0006 \u0003בריך\u0004 \u0005[ברך]\u0006 \u0003\"שהשמחה במעונו\".\u0004 ומעירים אף בענין זה: \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו],\u0006 ומדוע? — \u0003משום דטרידי\u0004 \u0005[ש\u0006הורי התינוק \u0005טרודים]\u0006 \u0003דאית ליה צערא לינוקא\u0004 \u0005[שיש לו צער לתינוק]\u0006 במילה, ולכן אין לברך שם \"שהשמחה במעונו\".","\u0003אמר רב נחמן אמר רב:\u0004 לענין עשרה שצריך בברכות החתונה — ה\u0003חתנים\u0004 עצמם הרי הם \u0003מן המנין\u0004 ומצטרפים לעשרה, \u0003ו\u0004אולם ברכת אבלים שנוהגים לומר בבית האבל — \u0003אין\u0004 ה\u0003אבלים\u0004 עצמם \u0003מן המנין. מיתיבי\u0004 \u0005[מקשים]:\u0006 והרי שנינו בברייתא כי \u0003חתנים ואבלים מן המנין!\u0004 ודוחים: \u0003מתניתא קא רמית עליה\u0004 \u0005[\u0006וכי מ\u0005ברייתא אתה מטיל,\u0006 מראה סתירה \u0005עליו]\u0006 על \u0003רב? רב\u0004 עצמו \u0003תנא הוא, ופליג\u0004 \u0005[וחולק]\u0006 על התנא של ברייתא זו והוא סבור שהאבלים עצמם אינם מן המנין. \u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003אמר ר' יצחק אמר ר' יוחנן: חתנים מן המנין, ואין אבלים מן המנין. מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו באותה ברייתא שהזכרנו: \u0003חתנים ואבלים מן המנין!\u0004"],["\u0003כי תניא\u0004 \u0005[כאשר שנוייה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 הרי זה \u0003בברכת המזון\u0004 להצטרף לשלושה לזימון, שאף האבל שהוא חייב בזימון כאחר, יכול להיות ממנין השלושה, ואולם \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן\u0004 שאין האבלים מן המנין — הרי זה \u0003בשורה,\u0004 כשעושים שורה לנחם את האבלים, ואין שורה בפחות מעשרה, ועל זה אמר כי אין האבלים נמנים ביניהם.","ומקשים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' יצחק אמר ר' יוחנן: מברכים ברכת חתנים בעשרה, וחתנים מן המנין, וברכת אבלים בעשרה, ואין אבלים\u0004 בה \u0003מן המנין.\u0004 כיון שנזכרת כאן ברכה — \u0003ברכה בשורה מי איכא\u0004 \u0005[האם יש]?\u0006 אלא ודאי ר' יוחנן לא לשורה התכוון! ומשיבים: \u0003אלא כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003ר' יוחנן\u0004 הרי זה \u0003ברחבה,\u0004 בברכה שאומרים ברחבה שליד בית הקברות, כאשר עורכים שם סעודת ההבראה ומברכים ברכות שונות לנחמת האבלים, ושם אין אבלים ממנין עשרה.","ומקשים \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' יצחק אמר ר' יוחנן: מברכין ברכת חתנים בעשרה כל שבעה\u0004 ימים של חתונה, \u0003וחתנים מן המנין, וברכת אבלים בעשרה כל שבעה, ואין אבלים מן המנין.\u0004 ואם נפרש כפי שהסברנו שברכת אבלים היא ברכה ברחבה — \u0003ברכת רחבה כל שבעה מי איכא\u0004 \u0005[האם יש]?\u0006 הלוא עושים אותה רק פעם אחת, כאשר חוזרים מהלוויית המת! ומשיבים: \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003ב\u0004זמן שהיו שם \u0003פנים חדשות,\u0004 כלומר, כשבאו אנשים שלא היו שם בשעת הלווייה, ובשבילם נאמרים מחדש דברי הספד וניחום ובתוך זה גם הברכה הנאמרת ברחבה.","מספרים, \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב חייא בר אבא מקרי בניה\u0004 \u0005[מלמד המקרא לבניו]\u0006 של \u0003ריש לקיש הוה\u0004 \u0005[היה],\u0006 \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003מתני בריה\u0004 \u0005[מלמד המשנה לבניו]\u0006 של \u0003ריש לקיש הוה\u0004 \u0005[היה].\u0006 \u0003שכיב ליה ינוקא\u0004 \u0005[מת לו ילד]\u0006 לרב חייא בר אבא. \u0003יומא קמא\u0004 \u0005[יום ראשון]\u0006 \u0003לא אזל\u0004 \u0005[הלך]\u0006 ריש לקיש \u0003לגביה\u0004 \u0005[אליו]\u0006 לנחמו. \u0003למחר דבריה\u0004 \u0005[למחרתו, לקח אותו]\u0006 את \u0003יהודה בר נחמני מתורגמניה\u0004 \u0005[מתורגמנו]\u0006 לנחם את רב חייא בר אבא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש למתורגמן: \u0003קום אימא מלתא כל קביל ינוקא\u0004 \u0005[עמוד אמור דבר כנגד,\u0006 בענין, \u0005התינוק].\u0006 \u0003פתח ואמר\u0004 פסוק זה, נאמר: \u0003\"וירא ה' וינאץ מכעס בניו ובנתיו\"\u0004 (דברים לב, יט), כלומר, \u0003דור שאבות מנאצים להקדוש ברוך, הוא כועס על בניהם ועל בנותיהם ו\u0004הם \u0003מתים כשהם קטנים.\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שאותו ילד שמת לא תינוק היה אלא \u0003בחור הוה\u0004 \u0005[היה].\u0006 \u0003והכי קאמר ליה\u0004 \u0005[וכך אמר לו],\u0006 פסוק זה: \u0003\"על כן על בחוריו לא ישמח ה' ואת יתמיו ואת אלמנתיו לא ירחם כי כלו חנף ומרע וכל פה דבר נבלה בכל זאת לא שב אפו ועוד ידו נטויה\"\u0004 (ישעיה ט, טז). ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 כוונתו בנאמר\u0005]\u0006 \u0003\"\u0004בכל זאת... \u0003ועוד ידו נטויה\"? אמר רב חנן בר רב: הכל יודעין כלה למה נכנסה לחופה,\u0004 שהיא נכנסת להיבעל, \u0003אלא\u0004 שאין לאדם לדבר בדברים אלה שלא לצורך, ש\u0003כל המנבל פיו, ומוציא דבר נבלה מפיו, אפילו נחתם לו גזר דינו של שבעים שנה לטובה\u0004 בכל זאת \u0003נהפך עליו לרעה.\u0004","לעיקר הדבר בין בנוסח זה ובין בנוסח זה, שואלים: \u0003אתא לנחומי\u0004 \u0005[\u0006הוא \u0005בא לנחם] —\u0006 והרי \u0003צעורי קמצער ליה\u0004 \u0005[מצער הוא\u0006 \u0005אותו]\u0006 בדברים אלה, שאומר לו שמפני חטאיו מת הילד! ומשיבים: המנחם לא רצה לומר שמפני חטאיו שלו מת התינוק, אלא \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]:\u0006 \u0003חשיב את לאתפוסי אדרא\u0004 \u0005[חשוב אתה להיתפס על\u0006 עוון \u0005הדור],\u0006 שדווקא הצדיקים נענשים בעוונות דור חוטא.","לאחר מכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש: \u0003קום אימא מלתא\u0004 \u0005[עמוד אמור דבר]\u0006 \u0003כנגד שבחו של הקדוש ברוך הוא. פתח ואמר\u0004 המספיד: \u0003\"האל הגדול ברוב גדלו, אדיר וחזק ברוב נוראות, מחיה מתים במאמרו, עושה גדולות עד אין חקר ונפלאות עד אין מספר. ברוך אתה ה' מחיה המתים\".\u0004","ועוד \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003קום אימא מלתא\u0004 \u0005[עמוד אמור דבר]\u0006 \u0003כנגד אבלים, פתח ואמר: \"אחינו המיוגעים, המדוכאין באבל הזה, תנו לבבכם לחקור את זאת; זאת היא עומדת לעד, נתיב הוא מששת ימי בראשית\".\u0004 כלומר, המוות הוא דבר הקיים מששת ימי בראשית והכל יודעים שזה גורלו של אדם, \u0003רבים שתו\u0004 את \"כוס התרעלה\" של המוות, ו\u0003רבים ישתו, כמשתה ראשונים כך משתה אחרונים. אחינו, בעל נחמות ינחם אתכם. ברוך מנחם אבלים\".\u0004","\u0003אמר אביי\u0004 כהערה לגבי נוסח זה: \u0003\"רבים שתו\" — לימא\u0004 \u0005[שיאמר],\u0006 \u0003\"רבים ישתו\" — לא לימא\u0004 \u0005[אל יאמר]\u0006 וכן \u0003\"משתה ראשונים\" — לימא\u0004 \u0005[שיאמר],\u0006 \u0003\"משתה אחרונים\" — לא לימא\u0004 \u0005[אל יאמר],\u0006 ומדוע — ש\u0003אמר ר' שמעון בן לקיש, וכן תנא משמיה\u0004 \u0005[שנה\u0006 החכם \u0005משמו]\u0006 של \u0003ר' יוסי: לעולם אל יפתח אדם פיו לשטן\u0004 ואל יפרש אפשרויות של פורענות שבעתיד. \u0003אמר רב יוסף: מאי קרא\u0004 \u0005[מה הכתוב,\u0006 הכתוב\u0005]\u0006 המלמד על כך — שמתחילה אמר הנביא \u0003\"כסדם היינו לעמרה דמינו\"\u0004 (ישעיה א, ט). \u0003מאי אהדר ליה\u0004 \u0005[\u0006ו\u0005מה החזיר,\u0006 השיב \u0005לו\u0006 לנביא\u0005]?\u0006 — \u0003\"שמעו דבר ה' קציני סדם\u0004 האזינו תורת אלהינו עם עמורה\u0003\"\u0004 (ישעיה א, י). כלומר, כיון שרק עשה השוואה לרעה (\"כסדום\"), נפתח הפתח והדבר הזה מגיע אחר כך לידי ממשות (\"קציני סדום\").","ועוד \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש למתורגמן: \u0003קום אימא מלתא\u0004 \u0005[עמוד אמור דבר]\u0006 \u0003כנגד מנחמי אבלים. פתח ואמר: \"אחינו גומלי חסדים בני גומלי חסדים, המחזיקים בבריתו של אברהם אבינו, שנאמר: \"כי ידעתיו למען אשר יצוה את בניו\u0004 ואת ביתו אחריו ושמרו דרך ה' לעשות צדקה ומשפט\u0003\"\u0004 (בראשית יח, יט). \u0003אחינו, בעל הגמול ישלם לכם גמולכם. ברוך אתה משלם הגמול\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 עוד: \u0003קום אימא מלתא\u0004 \u0005[עמוד אמור דבר]\u0006 \u0003כנגד כל ישראל. פתח ואמר: \"רבון העולמים, פדה והצל, מלט, הושע עמך ישראל מן הדבר, ומן החרב, ומן הביזה, ומן השדפון, ומן הירקון, ומכל מיני פורעניות המתרגשות ובאות לעולם, טרם נקרא ואתה תענה. ברוך אתה עוצר המגפה\".\u0004 ולענייננו למדנו שפעמים מברכים כמה ברכות לא רק ביום הקבורה אלא לאחר מכן.","כיון שדובר כאן בנחמת אבלים, מביאים מה ש\u0003אמר עולא ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 כי \u0003במתניתא תנא\u0004 \u0005[בברייתא\u0006 היא \u0005שנוייה]:\u0006 \u0003עשרה כוסות\u0004 של יין \u0003תקנו חכמים\u0004 לשתות \u0003בבית האבל: שלשה\u0004 מהם שותים \u0003קודם אכילה, כדי לפתוח את בני מעיו\u0004 שיהיה לו תיאבון לאכול. \u0003שלשה\u0004 שותים \u0003בתוך\u0004 ה\u0003אכילה, כדי לשרות אכילה שבמעיו\u0004 של האבל, כדי שהאוכל יתעכל היטב. \u0003וארבעה\u0004 שותים \u0003לאחר אכילה: אחד כנגד\u0004 ברכת \u0003\"הזן\"\u0004 שבברכת המזון, \u0003ואחד כנגד ברכת הארץ\u0004 שבה, \u0003ואחד כנגד\u0004 ברכת \u0003\"בונה ירושלים\", ואחד כנגד\u0004 ברכת \u0003\"הטוב והמטיב\".\u0004 שעל כל ברכה שותה את הכוס ומיד מוזגים לו כוס לצורך הברכה שלאחריה.","לאחר זמן \u0003הוסיפו עליהם ארבעה\u0004 כוסות נוספים: \u0003אחד כנגד חזני\u0004 (שמשי) \u0003העיר\u0004 שמתעסקים בהלוויית המת ובשאר צורכי הציבור. \u0003ואחד כנגד פרנסי העיר\u0004 שהיו מסייעים במימון קבורת עניים ובתקנתם. \u0003ואחד כנגד בית המקדש\u0004 כזכרון לבית המקדש שנחרב. \u0003ואחד כנגד רבן גמליאל. התחילו\u0004 באופן זה, בריבוי שתיית יין, ו\u0003היו שותין ומשתכרין,\u0004 כיון ששתו כוסות רבות כל כך. \u0003החזירו הדבר ליושנה,\u0004 שלא ישתו יותר מעשר.","ומסבירים: \u0003מאי\u0004 \u0005[מה]\u0006 ענין זה של \u0003רבן גמליאל\u0004 שהיו מזכירים אותו לטוב בבית האבל? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003בראשונה היתה הוצאת המת\u0004 לקבורה, כלומר, הוצאות הקבורה, \u0003קשה לקרוביו יותר ממיתתו,\u0004 כי היו נוהגים בכל מיני פאר, והיה הדבר גורם להוצאות מרובות מאד והיה הדבר מכביד ביותר, \u0003עד שהיו מניחים אותו ובורחין. עד שבא רבן גמליאל ונהג קלות\u0004 (זלזול) \u0003בעצמו,\u0004 וציווה \u0003והוציאוהו בכלי פשתן\u0004 ולא בבגדים מפוארים ובאופן מפואר. \u0003ונהגו כל העם אחריו להוציא בכלי פשתן,\u0004 ועל ידי כך הוקל העול הרבה, ומשום כך הזכירו אותו לשבח. \u0003אמר רב פפא: והאידנא\u0004 \u0005[ובזמננו,\u0006 בדורנו\u0005]\u0006 \u0003נהוג עלמא\u0004 \u0005[נוהג העולם,\u0006 נוהגים\u0005]\u0006 \u0003אפילו בצרדא בר זוזא\u0004 \u0005[בבד פשוט\u0006 שעולה \u0005זוז אחד]\u0006 לקבור את המת, ואין מקפידים בבגדים.","ושוב אנו חוזרים לענין הראשון, לעצם הבעיות המרכזיות של המסכת. \u0003אמר ר' אלעזר:\u0004"],["\u0003האומר \"פתח פתוח מצאתי\",\u0004 שטוען שבא על אשתו, ונודע לו בשעת ביאה שלא היתה בתולה — הרי זה \u0003נאמן לאוסרה עליו.\u0004 שאף שלא תמיד אפשר להוכיח בעדות שאשתו זנתה בהיותה ארוסה, מכל מקום לגבי עצמו נאמן הוא, והיא אסורה עליו כזונה.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 תיאסר עליו? הלא רק \u0003ספק ספיקא\u0004 \u0005[ספק\u0006 בתוך \u0005ספק]\u0006 \u0003הוא: ספק\u0004 אם נבעלה \u0003תחתיו\u0004 בהיותה ארוסה לו, \u0003ספק אין תחתיו,\u0004 אלא קודם לכן בהיותה פנויה נבעלה, ומותרת לו, \u0003ו\u0004אפילו \u0003אם תמצא\u0004 (תרצה) \u0003לומר\u0004 שזינתה \u0003תחתיו — ספק\u0004 נבעלה \u0003באונס\u0004 ומותרת לו, \u0003ספק ברצון,\u0004 ואם כן, הרי זה ספק־ספיקא אם זנתה, ומדוע תיאסר?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003באשת כהן\u0004 שנאסרת על בעלה בין שנבעלה באונס בין ברצון, ואם כן יש כאן רק ספק אחד. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמדובר פה אפילו \u0003באשת ישראל, וכגון דקביל\u0004 \u0005[שקיבל]\u0006 \u0003בה אבוה\u0004 \u0005[אביה]\u0006 \u0003קידושין\u0004 כשהיתה \u0003פחותה מבת שלש שנים ויום אחד,\u0004 ובא עליה בעלה בהיותה יותר מבת שלוש, שוודאי נבעלה בהיותה ארוסה, שאם נבעלה קודם, עוד בהיותה קטנה, לא היתה מאבדת בכך את בתוליה לצמיתות, שכן כל הפחותה מבת שלוש, בתוליה חוזרים, ולא היה מרגיש בביאתו שאינה בתולה. ויש כאן רק ספק אחד: אם היה הדבר באונס או ברצון, אבל וודאי שנבעלה כשהיתה ארוסה לו.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו\u0006 בזה\u0005]\u0006 שאסורה עליו כשיש רק ספק אחד? הלא \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה במפורש: \u0003האומר לאשה \"קדשתיך\", והיא אומרת \"לא קדשתני\",\u0004 ואין עדים מצויים לפנינו להוכיח מה באמת אירע — \u0003היא מותרת בקרוביו,\u0004 כגון לאחיו, משום שכפי שהיא אומרת אין לה שום קירבה אליו, \u0003והוא אסור בקרובותיה\u0004 שהרי לפי דבריו קידש אותה, ולכן קרובותיה אסורות עליו. ומכאן שאדם אוסר את עצמו, אפילו כשאין עדים בדבר.","ודוחים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הוא ש\u0003ודאי קים ליה\u0004 \u0005[מוחזק לו]\u0006 שקידש אותה, ומשום כך נאסרות עליו קרובותיה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 \u0003מיקם הוא דלא קים ליה\u0004 \u0005[\u0006שמא הוא עצמו \u0005לא ברור לו\u0006 הדבר\u0005]\u0006 שהיתה בעולה, ושמא לא היה בקי וטעה בכך, ויש כאן כמה סיבות להתיר, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ר' אלעזר שבכל זאת הוא נאמן לאוסרה עליו.","ושואלים מצד אחר: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' אלעזר הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אלעזר: אין האשה נאסרת על בעלה\u0004 בזנות \u0003אלא על עסקי קינוי\u0004 (שהזהיר אותה לבל תיסתר עם פלוני) \u0003וסתירה\u0004 (שהעידו עדים שנסתרה עמו אחר הקינוי), כפי שמפורש בפרשת סוטה, שקודם קינא לה שלא תיסתר עם איש אחר ואחר כך נסתרה, \u0003וכמעשה שהיה\u0004 בדוד ובת־שבע?!","ותחילה תוהים: \u0003ותסברא\u0004 \u0005[ו\u0006כי \u0005סבור אתה]\u0006 שה\u0003מעשה שהיה, בקינוי וסתירה הוה\u0004 \u0005[היה]?\u0006 \u0003ועוד, מי אסרוה\u0004 \u0005[האם אסרו אותה]\u0006 את בת־שבע על בעלה? והלא אילו נאסרה על בעלה, היתה נאסרת גם על דוד, שכשם שאסורה על בעלה אסורה גם על בועלה!","ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 כי \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך לפרש את הדברים: \u0003אין האשה נאסרת על בעלה אלא על עסקי קינוי וסתירה,\u0004 ודבר זה אנו למדים \u0003ממעשה שהיה\u0004 בבת־שבע, ש\u0003לא הוה\u0004 \u0005[שלא היה]\u0006 שם \u0003קינוי וסתירה ו\u0004לכן באמת \u0003לא איתסרא\u0004 \u0005[נאסרה].\u0006 \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 לעניינינו על דברי ר' אלעזר, שהרי לשיטתו רק על ידי \u0003קינוי וסתירה אין\u0004 \u0005[כן]\u0006 נאסרת האשה על בעלה, אבל כשאומר \u0003\"פתח פתוח\" — לא!\u0004","ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה רוצה לדייק שדברי ר' אלעזר באו לצמצם ולומר שבכל אופן אחר אינה נאסרת, וכי תדייק ותאמר כמו־כן כי על ידי \u0003קינוי וסתירה אין\u0004 \u0005[כן]\u0006 אוסרים אשה על בעלה, אבל \u0003עדים\u0004 שבאים ומעידים שנבעלה — \u0003לא?!\u0004 והרי אז ודאי זונה היא, ואסורה!","\u0003אלא\u0004 מן ההכרח לפרש כי \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 ר' אלעזר: \u0003אין האשה נאסרת על בעלה בעד אחד, אלא בשני עדים\u0004 שנבעלה, \u0003ו\u0004אם היה \u0003קינוי וסתירה\u0004 — \u0003אפילו בעד אחד\u0004 שבא אחר כך והעיד שזינתה \u0003נמי\u0004 \u0005[גם כן]\u0006 נאסרת. \u0003ו\u0004אפשר לומר לפי זה כי \u0003פתח פתוח כשני עדים דמי\u0004 \u0005[נחשב],\u0006 ואין צריך קינוי וסתירה.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 ב\u0003מעשה שהיה\u0004 בבת־שבע, \u0003מפני מה לא אסרוה?\u0004 הרי ברור היה שדוד בא עליה כשהיא אשת איש! על כך יש להשיב: \u0003התם\u0004 \u0005[שם]\u0006 \u0003אונס הוה\u0004 \u0005[היה]\u0006 זה, ולא מרצונה נבעלה, ומשום כך לא נאסרה על בעלה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 במעשה בת־שבע \u0003כי הא\u0004 ש\u0003אמר\u0004 \u0005[כמו זה שאמר]\u0006 \u0003ר' שמואל בר נחמני אמר ר' יונתן:\u0004"],["\u0003כל היוצא למלחמת בית דוד גט כריתות\u0004 היה \u0003כותב לאשתו.\u0004 כפי שנאמר עוד במלחמת שאול שהיתה לפני מלחמות בית דוד, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואת אחיך תפקד לשלום ואת ערבתם תקח\"\u0004 (שמואל א' יז, יח), \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ואת ערבתם תקח\"? תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: דברים המעורבין בינו לבינה.\u0004 כלומר, שיקח את הקידושין שהם הדבר הגורם לקשר הנישואין שבינו לבינה, ואיך יקח — על ידי מתן גט. מכאן שעוד לפני מלכות דוד נהוג היה לעשות כך, ומכאן שבת־שבע לא היתה בעצם נשואה באותה שעה, אלא היתה גרושה.","בעניין זה שאדם נאמן לומר \"פתח פתוח מצאתי\". \u0003אמר אביי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 הוכחה לדברי ר' אלעזר, ששנינו במשנה: \u0003בתולה נשאת ליום הרביעי.\u0004 ונדייק: \u0003ליום רביעי — אין\u0004 \u0005[כן],\u0006 \u0003ליום חמישי — לא. מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005] —\u0006 \u0003משום\u0004 שאנו סבורים, שאם יצטרך להמתין עוד כמה ימים עד למושב בית דין, בינתיים בגלל \u0003איקרורי דעתא\u0004 \u0005[התקררות הדעת,\u0006 היפג כעסו\u0005]\u0006 לא יבוא לתובעה בדין.","ונברר: \u0003ולמאי\u0004 \u0005[ולמה],\u0006 לאיזה ענין אנחנו חוששים? \u0003אי למיתב\u0004 \u0005[אם לתת]\u0006 \u0003לה כתובה,\u0004 שבגלל התקררות דעתו לא יתבענה בדין ותיחשב כאילו היתה בתולה ובאמת היא בעולה ולא מגיע לה כתובה, \u0003ניתיב\u0004 \u0005[שיתן]\u0006 \u0003לה\u0004 את הכתובה אם רצונו בכך, ומדוע על החכמים להקפיד בענין זה? \u0003אלא\u0004 הכוונה היא שאנחנו חוששים לאיסור מפני שעל ידי טענתו הוא בא \u0003לאוסרה עליו, ודקא טעין\u0004 \u0005[ושהוא\u0006 \u0005טוען]\u0006 כנגדה איזה \u0003טענה.\u0004","\u0003מאי לאו דקטעין\u0004 \u0005[האם לא שהוא\u0006 \u0005טוען]\u0006 \u0003טענת \"פתח פתוח\",\u0004 שבעל ומצא פתח פתוח, והוא נאמן על כך ונאסרת עליו, כדברי ר' אלעזר! ודוחים: \u0003לא,\u0004 מכאן אין ראיה, אפשר לומר \u0003דקטעין\u0004 \u0005[שהוא טוען]\u0006 \u0003טענת דמים,\u0004 שלא מצא לה דם בתולים, וזוהי טענה מבוססת שיש בה כדי לאוסרה עליו, שכן היא אינה תלויה רק בהרגשתו בלבד, שהרי אפשר לברר את אמיתותה.","\u0003אמר רב יהודה אמר שמואל: האומר \"פתח פתוח מצאתי\", נאמן\u0004 בדבריו \u0003להפסידה\u0004 את \u0003כתובתה. אמר רב יוסף: מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]?\u0006 הלא כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במפורש בענין זה: \u0003האוכל אצל חמיו ב\u0004ארץ \u0003יהודה\u0004 בין האירוסין לנישואין \u0003שלא בעדים,\u0004 שאין עדים שיעידו שלא התייחד אתה — שוב \u0003אינו יכול לטעון\u0004 לאחר הנישואין \u0003טענת בתולים, מפני\u0004 שהדבר ברור \u0003שמתייחד עמה,\u0004 ובוודאי הוא זה שבא עליה. ונדייק מכאן: \u0003ביהודה\u0004 ששם היה נהוג מנהג זה \u0003הוא דלא מצי טעין\u0004 \u0005[שאינו יכול לטעון]\u0006 טענת בתולים, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בגליל מצי טעין\u0004 \u0005[יכול\u0006 הוא \u0005לטעון].\u0006","ומעתה נברר: \u0003ולמאי\u0004 \u0005[ולמה],\u0006 לאיזה ענין, \u0003אי\u0004 \u0005[אם]\u0006 כדי \u0003לאוסרה עליו, ביהודה אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא?\u0004 שאם יודע שלא בא עליה, ומצא שהיא בעולה — משמע שנבעלה באיסור, ויכול לאוסרה עליו! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה היא שנאמן בגליל גם \u0003להפסידה כתובתה, ודקא טעין\u0004 \u0005[ושהוא טוען]\u0006 \u0003טענה, מאי לאו\u0004 \u0005[האם לא]\u0006 \u0003דקא טעין\u0004 \u0005[שהוא טוען]\u0006 \u0003טענת \"פתח פתוח\"\u0004 ונאמן על כך! ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דקא טעין\u0004 \u0005[שהוא טוען]\u0006 \u0003טענת דמים.\u0004"],["\u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003אמר רב נחמן אמר שמואל משום ר' שמעון בן אלעזר: חכמים\u0004 הם ש\u0003תקנו להם לבנות ישראל\u0004 כתובה: \u0003לבתולה מאתים\u0004 זוז, \u0003ולאלמנה מנה, ו\u0004לכן \u0003הם\u0004 גם ש\u0003האמינוהו\u0004 לגבי בתולה, \u0003שאם אמר \"פתח פתוח מצאתי\u0004 ואינה בתולה \u0003\"\u0004— \u0003נאמן\u0004 להפסידה את כתובתה. ושואלים: \u0003אם כן,\u0004 כיון שהאמינוהו — \u0003מה הועילו חכמים בתקנתם\u0004 שקבעו לה כתובה מאתיים, אם יכול לטעון שאינה בתולה, וטענתו תתקבל?","\u0003אמר רבא: חזקה, אין אדם טורח בסעודה\u0004 של חתונה \u0003ומפסידה\u0004 לחינם. שודאי לאחר שטרח בסעודת החתונה רוצה הוא לשאתה ולשמוח עמה, ואם בכל זאת טען שפתחה פתוח — ודאי אמת אומר.","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003הואיל וקנס חכמים הוא\u0004 בכתובה — \u0003לא תגבה אלא מן הזיבורית\u0004 (הגרועה) שבקרקעותיו של הבעל. ותוהים: וכי \u0003קנסא\u0004 \u0005[קנס]\u0006 הוא? \u0003מאי קנסא\u0004 \u0005[מה קנס]\u0006 הוא הכתובה? \u0003אלא\u0004 תקן את הלשון ו\u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003הואיל ותקנת חכמים הוא\u0004 ואינה חובה מן התורה — \u0003לא תגבה\u0004 האשה את כתובתה \u0003אלא מן הזיבורית. רבן שמעון בן גמליאל אומר: כתובת אשה מן התורה.\u0004","ומקשים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רבן שמעון בן גמליאל הכי\u0004 \u0005[כך]?\u0006 \u0003והתניא\u0004 \u0005[והרי\u0006 \u0005שנינו בברייתא\u0006\u0005],\u0006 נאמר בענין מפתה: \u0003\"כסף ישקל כמהר הבתולת\"\u0004 (שמות כב, טז), לומר: \u0003שיהא זה,\u0004 תשלום הקנס, \u0003כמוהר הבתולות, ומוהר הבתולות כזה\u0004 (כתשלום הקנס), שהם חמישים כסף, שהם מאתיים זוז. \u0003מכאן סמכו חכמים לכתובת אשה מן התורה. רבן שמעון בן גמליאל אומר: כתובת אשה אינה מדברי תורה אלא מדברי סופרים!\u0004","ומתרצים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות בברייתא הזו. ושואלים: \u0003ומאי חזית דאפכת בתרייתא, איפוך קמייתא\u0004 \u0005[ומה ראית שהפכת\u0006 את \u0005האחרונה, הפוך\u0006 את \u0005הראשונה],\u0006 ושמא רבן שמעון בן גמליאל הוא הסבור שכתובה היא מדברי סופרים?","ומשיבים: \u0003הא שמעינא ליה\u0004 \u0005[הרי שמענו אותו]\u0006 \u0003לרבן שמעון בן גמליאל\u0004 במקום אחר ש\u0003אמר\u0004 ש\u0003כתובת אשה מדאורייתא\u0004 \u0005[מן התורה]\u0006 היא. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר,\u0004 שאם נשא אשה בקפוטקיא, שהכסף של מדינה זו חשוב יותר, והגירושין היו במקום אחר — \u0003נותן לה\u0004 בפרעון כתובתה \u0003ממעות קפוטקיא.\u0004 משמע שההתחייבות שבכתובה היא מדין תורה, ולכן צריך לתת לה בכסף חשוב כפי שהתחייב לה בשעת הנישואין.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר לסתירה שבין הברייתות: שהברייתא האחרונה \u0003כולה\u0004 לפי שיטת \u0003רבן שמעון בן גמליאל היא, ו\u0004אולם, \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 היא הברייתא \u0005וכך\u0006 היא \u0005שנויה]:\u0006 \u0003מכאן סמכו חכמים לכתובת אשה\u0004 (בתולה) \u0003מן התורה.\u0004 אולם \u0003כתובת אלמנה אינה מדברי תורה אלא מדברי סופרים, שרבן שמעון בן גמליאל אומר: כתובת אלמנה אינה מדברי תורה אלא מדברי סופרים.\u0004","מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד בא לפני]\u0006 \u0003רב נחמן, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פתח פתוח מצאתי\u0004 כשבעלתי את אשתי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן: אסבוהו כופרי\u0004 \u0005[הספיגוהו,\u0006 הלקוהו ב\u0005ענפי חריות דקל],\u0006 \u0003מברכתא חביטא ליה\u0004 \u0005[זונות חבוטות,\u0006 מצויות \u0005לו].\u0006 שהיה איש זה רווק, ומניין הוא יודע אם פתח פתוח היה או לא, אם לא שמצוי הוא אצלן?","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב נחמן הוא\u0004 ש\u0003אמר\u0004 כי \u0003מהימן\u0004 \u0005[נאמן]\u0006 אדם בטענת פתח פתוח! ומשיבים: אכן, \u0003מהימן\u0004 \u0005[נאמן]\u0006 הוא, \u0003ומסבינן ליה כופרי\u0004 \u0005[ומספיגים,\u0006 מכים \u0005אותו\u0006 ב\u0005חריות דקל]\u0006 מטעם אחר, אבל לא משום שאין מאמינים לו. \u0003רב אחאי משני\u0004 \u0005[\u0006היה \u0005מתרץ]\u0006 באופן אחר: \u0003כאן — בבחור\u0004 אין מאמינים לו, שאינו בקי כל כך ומלקים אותו, \u0003כאן — בנשוי\u0004 מאמינים לו.","סיפור אחר בנושא זה מסופר על דורות קודמים: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003רבן גמליאל, אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם: \u0003פתח פתוח מצאתי. אמר ליה\u0004 \u0005[לו]\u0006 רבן גמליאל: \u0003שמא הטיתה,\u0004 כלומר, לא בעלת כדרכך אלא בהטיה, ולכן חושב אתה כי פתחה פתוח? \u0003אמשול לך משל: למה הדבר דומה? — לאדם שהיה מהלך באישון לילה ואפילה\u0004 והגיע לפתח הבית, אם \u0003היטה\u0004 את הדבר המעכב פתיחת הדלת — \u0003מצאו פתוח, לא היטה — מצאו נעול.\u0004 ושמא הזדמן לך שהטית ובעלת באופן כזה שלא הבחנת שהפתח היה נעול ועדיין היא בתולה.","\u0003איכא דאמרי, הכי אמר ליה\u0004 \u0005[יש שאומרים\u0006 ש\u0005כך אמר לו]:\u0006 \u0003שמא במזיד הטיתה, ועקרת לדשא ועברא\u0004 \u0005[ועקרת את המפתן והבריח]?\u0006 \u0003אמשול לך משל: למה הדבר דומה? — לאדם שהוא מהלך באישון לילה ואפילה\u0004 והגיע לפתח, \u0003היטה במזיד — מצאו פתוח, לא היטה במזיד — מצאו נעול.\u0004","וסיפור אחר: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003רבן גמליאל בר רבי, אמר ליה\u0004 \u0005[לו]\u0006 אותו אדם: \u0003רבי, בעלתי ולא מצאתי דם. אמרה לו\u0004 האשה הנתבעת: \u0003רבי, בתולה הייתי. אמר להם: הביאו לי אותו סודר,\u0004 כלומר, את המצע שעליו נבעלה האשה. \u0003הביאו לו הסודר, ושראו במים וכבסו, ומצא עליו כמה טיפי דמים\u0004 של דם בתולים. \u0003אמר לו: לך, זכה במקחך,\u0004 שבתולה היתה והכל היה כשורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003הונא מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מפרזקיא לרב אשי: אנן נמי נעביד הכי\u0004 \u0005[אנו גם כן נעשה כך]\u0006 כשיש תביעה כגון זו אצלנו, ונבדוק שמא היו דמים ונתכסו בזרע או בדבר אחר. \u0003אמר ליה\u0004 \u0005[לו]:\u0006"],["\u0003גיהוץ שלנו\u0004 בבבל, שמעבירים אבן רכה על הבגד לשפשפו הוא \u0003ככיבוס שלהם\u0004 בארץ ישראל, שרק אז מגיעים אנו לאותה דרגה של נקיון הבגד. ואין אנו יודעים לכבס בגדים במים כפי שהם עושים. \u0003ואי אמרת ניעבד\u0004 \u0005[ואם אתה אומר\u0006 ש\u0005נעשה אנו]\u0006 \u0003גיהוץ\u0004 ואחר כך נבדוק — \u0003מעברא ליה חומרתא\u0004 \u0005[מעבירה אותו,\u0006 את כתם הדם, \u0005האבן]\u0006 שבה משפשפים בשעת הגיהוץ. ולכן אין אנו יכולים לבדוק בדיקה זו.","ועוד מעשה מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003רבן גמליאל בר רבי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רבי, בעלתי ולא מצאתי דם. אמרה ליה\u0004 \u0005[לו]\u0006 האשה הנתבעת: \u0003רבי, עדיין בתולה אני. אמר להן: הביאו לי שתי שפחות, אחת בתולה ואחת בעולה\u0004 לצורך נסיון. \u0003הביאו לו, והושיבן על פי חבית של יין,\u0004 ומצא שה\u0003בעולה\u0004 — היה \u0003ריחה\u0004 של החבית \u0003נודף\u0004 מפיה, וה\u0003בתולה\u0004 — \u0003אין ריחה נודף.\u0004 לאחר מכן \u0003אף\u0004 את \u0003זו\u0004 האשה שטענה שהיא בתולה \u0003הושיבה ולא היה ריחה נודף. אמר לו\u0004 לבעל: מסתבר שצודקת היא ובתולה היא — \u0003לך, זכה במקחך.\u0004","ושואלים: מאחר שידע רבן גמליאל דרך זו של בדיקה, \u0003ונבדוק מעיקרא בגווה\u0004 \u0005[ושיבדוק מתחילה בה]\u0006 ומדוע לא בדק מיד את האשה, וניסה תחילה בשתי השפחות? ומסבירים: \u0003גמרא הוה שמיע ליה\u0004 \u0005[מסורת היה לו משמיעה],\u0006 ואולם \u0003מעשה לא הוה חזי\u0004 \u0005[ראה]\u0006 שהדבר אמנם כן הוא, \u0003וסבר דלמא\u0004 \u0005[שמא]\u0006 \u0003לא קים ליה\u0004 \u0005[ברור לו]\u0006 \u0003בגווה דמלתא שפיר\u0004 \u0005[בתוך,\u0006 בפרטי, \u0005הדבר יפה],\u0006 שאי אפשר להבחין היטב בבדיקה זו, \u0003ולאו אורח ארעא לזלזולי\u0004 \u0005[ואין\u0006 זו \u0005דרך ארץ לזלזל]\u0006 \u0003בבנות ישראל\u0004 ולהושיבן כך, וכיון שניסה וראה שהבדיקה עולה יפה — בדק באופן זה אף את האשה ההיא.","ועוד מסופר: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003רבן גמליאל הזקן, אמר לו: רבי, בעלתי ולא מצאתי דם, אמרה לו\u0004 האשה הנתבעת: \u0003רבי, ממשפחת דורקטי אני, שאין להן לא דם נדה ולא דם בתולים. בדק רבן גמליאל בקרובותיה\u0004 אם אמנם נכון הדבר לגבי המשפחה, \u0003ומצא כדבריה. אמר לו: לך, זכה במקחך, אשריך שזכית למשפחת דורקטי,\u0004 שאין לך בעיות עם דמים אלה.","ומסבירים: \u0003מאי\u0004 \u0005[\u0006ו\u0005מה\u0006 היא לשון\u0005]\u0006 \u0003\"דורקטי\"\u0004 — כעין קיצור של המלים: \u0003דור קטוע.\u0004 ומעירים: \u0003אמר ר' חנינא: תנחומים של הבל ניחמו רבן גמליאל לאותו האיש.\u0004 כלומר, דברי תנחומים אלה אין בהם ממש, משום שבאמת יש חסרון באשה זו. \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' חייא: כשם שהשאור יפה לעיסה, כך דמים יפים לאשה. ותנא\u0004 \u0005[ושנה\u0006 החכם\u0005]\u0006 \u0003משום\u0004 (משמו של) \u0003ר' מאיר: כל אשה שדמיה מרובין — בניה מרובים.\u0004 ואשה זו שאין לה דמים — מן הסתם גם לא יהיו לה בנים מרובים.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בגירסת הדברים. \u0003ר' ירמיה בר אבא אמר: \"זכה במקחך\" אמר ליה\u0004 \u0005[לו],\u0006 \u0003ור' יוסי בר אבין אמר: \"נתחייב במקחך\" אמר ליה\u0004 \u0005[לו]:\u0006 ומבררים: \u0003בשלמא למאן\u0004 ש\u0003אמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003\"נתחייב\" — היינו\u0004 \u0005[זהו]\u0006 שאמר \u0003ר' חנינא\u0004 שתנחומים של הבל הם, משום שאשה זו שדמיה מעטים יש פגם בפריון שלה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003\"זכה\", מאי זכותא\u0004 \u0005[מה\u0006 ה\u0005זכות\u0006 שבכך\u0005]?\u0006 ומשיבים: יש בכך זכות מצד אחר, \u0003דלא אתי\u0004 \u0005[שאינו בא]\u0006 על ידה \u0003לידי ספק נדה,\u0004 שהרי אין לה דם נידה.","ועוד מסופר מעין אלה: \u0003ההוא דאתא לקמיה\u0004 \u0005[\u0006אדם \u0005אחד שבא לפני]\u0006 \u0003רבי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רבי בעלתי ולא מצאתי דם, אמרה לו\u0004 האשה הנתבעת: \u0003רבי עדיין בתולה הייתי. ו\u0004מעירים: שבזמן מעשה זה \u0003שני\u0004 \u0005[שנות]\u0006 \u0003בצורת הוה\u0004 \u0005[היו]\u0006 השנים ההן, \u0003ראה רבי שפניהם שחורים\u0004 מפני הרעב. \u0003צוה עליהן והכניסום למרחץ, והאכילום והשקום, והכניסום לחדר\u0004 ושם בחדר \u0003בעל\u0004 האיש \u0003ומצא דם. אמר לו: לך, זכה במקחך.\u0004 שלא מצא עד אז דם משום ששניהם היו חלושים מאד. \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רבי עליהם\u0004 מקרא זה: \u0003\"צפד עורם על עצמם יבש היה כעץ\"\u0004 (איכה ד, ח), עד שאין הדם יצא מהם.","\u0003בתולה\u0004 — \u0003כתובתה מאתים\u0004 זוז, \u0003ואלמנה\u0004 — כתובתה \u0003מנה\u0004 (מאה זוז). \u0003בתולה אלמנה גרושה וחלוצה מן האירוסין,\u0004 כל עוד היא בתולה — \u0003כתובתן מאתים ויש להן טענת בתולים,\u0004 שהרי לא נישאו, והן עדיין בחזקת בתולות.","מסבירים: \u0003מאי\u0004 \u0005[מה\u0006 הוא לשון\u0005]\u0006 \u0003\"אלמנה\" — אמר רב חנא בגדתאה\u0004 \u0005[מבגדד]:\u0006 \u0003\"אלמנה\" — על שם מנה.\u0004 שהוא כעין נוטריקון \"אל מנה\" — שמקבלת רק מנה. ושואלים: אם כן, \u0003אלמנה מן האירוסין\u0004 שכתובתה כאמור מאתים, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 מדוע נקראת אף היא אלמנה! ומשיבים: \u0003איידי דהא קרי לה\u0004 \u0005[כיון שזו,\u0006 מן הנישואין, \u0005קוראים אותה]\u0006 \u0003אלמנה, הא נמי קרי לה\u0004 \u0005[זו,\u0006 מן האירוסין, \u0005גם כן קוראים אותה]\u0006 \u0003אלמנה.\u0004","ושואלים: זה הסבר למנהג דורות אחרונים, אבל \u0003אלמנה דכתיבא באורייתא\u0004 \u0005[שנאמרה בתורה],\u0006 \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הרי אז לא היתה תקנה זו של כתובת אלמנה! ומשיבים: אף בתורה קראו לה כך, על שם ש\u0003עתידין רבנן דמתקני\u0004 \u0005[חכמים שיתקנו]\u0006 \u0003לה\u0004 כתובה של \u0003מנה.\u0004 ותוהים: \u0003ומי כתב קרא\u0004 \u0005[והאם נאמר מקרא]\u0006 על שם ה\u0003עתיד?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושם הנהר השלישי חדקל הוא ההלך קדמת אשור\"\u0004 (בראשית ב, יד), \u0003ותנא\u0004 \u0005[ושנה]\u0006 \u0003רב יוסף: אשור זו\u0004 העיר \u0003סליקא.\u0004 ויש לשאול \u0003ומי הואי\u0004 \u0005[והאם היתה]\u0006 עיר זו בזמן התורה? \u0003אלא\u0004 נאמר כן בתורה משום ש\u0003עתידה\u0004 להיות עיר זו. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 נקראה \"אלמנה\" משום ש\u0003עתידה\u0004 אשה כזו לקבל כתובה בשווי של מנה.","כיון שהזכרנו את דברי רב חנא בגדתאה, מזכירים דרשה אחרת משמו, \u0003ואמר רב חנא בגדתאה\u0004 \u0005[מבגדד]:\u0006 \u0003מטר — משקה, מרוה, ומזבל, ומעדן\u0004 את הפירות, \u0003וממשיך\u0004 (מוסיף, מרבה אותם). \u0003אמר רבא בר ר' ישמעאל, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב יימר בר שלמיא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 שממנו למדים דבר זה — שנאמר: \u0003\"תלמיה רוה נחת גדודה ברביבים תמגגנה צמחה תברך\"\u0004 (תהלים סה, יא). \"תלמיה רוה\" — משקה ומרוה, \"ברביבים תמוגגנה\" — מזבל, \"צמחה תברך\" — מעדן, וממשיך.","\u0003אמר ר' אלעזר\u0004 מדרש בדרך דומה: \u0003מזבח\u0004 הוא כעין נוטריקון של \u0003מזיח\u0004 (מזיז) את החטאים, \u0003ומזין,\u0004 שבזכותו ניזונים הכל, \u0003מחבב\u0004 את ישראל על אביהם שבשמים, ו\u0003מכפר.\u0004 ושואלים: \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003מכפר היינו\u0004 \u0005[זהו]\u0006 \u0003מזיח,\u0004 שהרי לשניהם אותה משמעות! ומסבירים: אין הדבר כן, \u0003מזיח\u0004 פירושו שהוא מזיז ומסלק את ה\u0003גזירות, ומכפר\u0004 הוא ל\u0003עונות.\u0004","\u0003ו\u0004עוד מביאים מה ש\u0003אמר רב חנא בגדתאה\u0004 \u0005[מבגדד]:\u0006 \u0003תמרי\u0004 \u0005[תמרים]\u0006 יש בהן כמה מעלות, שהן: \u0003משחנן\u0004 \u0005[מחממות],\u0006 \u0003משבען\u0004 \u0005[משביעות],\u0006 \u0003משלשלן\u0004 \u0005[משלשלות],\u0006 \u0003מאשרן ולא מפנקן\u0004 \u0005[מחזקות ואינן מפנקות].\u0006 \u0003אמר רב: אכל תמרים — אל יורה\u0004 הלכה, משום שהתמרים יש בהן כדי לשכר. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003תמרים, שחרית וערבית — יפות\u0004 לאוכל אותן, \u0003במנחה — רעות\u0004 לאוכל אותן, \u0003בצהרים\u0004 — \u0003אין כמותן\u0004 לטוב, \u0003ומבטלות שלשה דברים: מחשבה רעה\u0004 (דאגה), \u0003וחולי מעים, ו\u0004מחלת ה\u0003תחתוניות\u0004 (טחורים). הרי שתמרים בדרך כלל טובים הם!","ומשיבים: זו איננה סתירה, \u0003מי אמרינן דלא מעלו\u0004 \u0005[האם אמרנו שאינן מעולות]?\u0006 \u0003עלויי מעלו, ולפי שעתא טרדא\u0004 \u0005[מעולות\u0006 הן, \u0005ולפי שעה\u0006 גורמות הן \u0005טירדה\u0006 ושכרות\u0005].\u0006 \u0003מידי דהוה אחמרא\u0004 \u0005[כשם שהוא\u0006 הדבר \u0005לגבי יין].\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003השותה רביעית יין — אל יורה,\u0004 למרות שהוא משקה טוב. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 תירוץ אחר: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה] —\u0006 כשאוכל אותן \u0003מקמי נהמא\u0004 \u0005[לפני הלחם],\u0006 יכולות הן להזיק והן משכרות. \u0003הא\u0004 \u0005[זה] —\u0006 כשאוכל אותן \u0003לבתר נהמא\u0004 \u0005[אחרי הלחם],\u0006 ואז מעולות הן. ש\u0003אמר אביי, אמרה לי אם\u0004 (אומנתי): \u0003תמרי מקמי נהמא\u0004 \u0005[התמרים\u0006 שאוכלים \u0005לפני הלחם] —\u0006 הן \u0003כי נרגא לדיקולא\u0004 \u0005[כמו גרזן לדקל],\u0006 כלומר, מזיקות ביותר. אבל האוכלם \u0003בתר נהמא\u0004 \u0005[אחרי הלחם] —\u0006 הרי הן \u0003כי עברא לדשא\u0004 \u0005[כמו בריח לדלת]\u0006 שמחזקות ומועילות.","כיון שהוזכרה המלה דשא, ועסקנו בדרשות של מילים, מביאים דרשה על המלה \u0003דשא\u0004 \u0005[דלת],\u0006 \u0003אמר רבא,\u0004 הוא נוטריקון של המילים: \u0003דרך שם,\u0004 כלומר, דרך שם נכנסים. \u0003דרגא\u0004 \u0005[סולם,\u0006 מדרגה\u0005]\u0006 — \u0003אמר רבא,\u0004 נוטריקון: \u0003דרך גג. פוריא\u0004 \u0005[מיטה]\u0006 — \u0003אמר רב פפא:\u0004 אף זו כלשון קיצור, מפני \u0003שפרין ורבין עליה. אמר רב נחמן בר יצחק:\u0004"],["\u0003אף אנו נאמר\u0004 דרשת מילים: \u0003איילונית\u0004 שהיא אשה שאינה מסוגלת ללדת, נקראת כך משום שהיא \u0003דוכרנית\u0004 (דומה לאיל, זכר) ואיילונית היא כזכר, \u0003דלא ילדה\u0004 \u0005[שאינה יולדת].\u0006","\u0003הגיורת והשבויה והשפחה שנפדו,\u0004 או \u0003שנתגיירו,\u0004 או \u0003שנשתחררו\u0004 כשהן \u0003פחותות מבנות שלש שנים ויום אחד\u0004 ואחר כך נישאו — \u0003כתובתן מאתים.\u0004 שאנו אומרים שמאז בתוליהן נשמרים, ואף אם נבעלה בהיותה פחות מגיל שלוש שנים ויום אחד, אין זה פוגם את הבתולים. \u0003ויש להן טענת בתולין,\u0004 כלומר, יש מקום לטעון כנגדן כשאינן בתולות.","\u0003אמר רב הונא: גר קטן\u0004 שאין לו אב, ואמו מביאה אותו להתגייר — \u0003מטבילין אותו על דעת בית דין.\u0004 שאף שהוא עצמו אין בו דעת, רשאים בית דין להטבילו ולגיירו.","ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך — ש\u0003זכות הוא לו\u0004 שהוא מתגייר, \u0003וזכין לאדם שלא בפניו,\u0004 ואין צורך בדעתו, אולם הלא דבר זה כבר \u0003תנינא\u0004 \u0005[שנינו]\u0006 במפורש: \u0003זכין לאדם שלא בפניו\u0004 ושלא מדעתו, \u0003ואין חבין\u0004 (מחייבים) \u0003לאדם שלא בפניו!\u0004","ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003גוי בהפקירא ניחא ליה\u0004 \u0005[ב\u0006חיי \u0005הפקר נוח לו],\u0006 שטוב בעיניו להשאר גוי, ואין זו זכות בשבילו שמייהדים אותו, \u0003דהא קיימא לן\u0004 \u0005[שהרי מוחזק בידינו]\u0006 ש\u0003עבד ודאי בהפקירא ניחא ליה\u0004 \u0005[ב\u0006חיי \u0005הפקר נוח לו]\u0006 ואינו רוצה לא זכויות ולא חובות של בן חורין, וכן יש לומר גם לגבי גוי,","על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגרות זכות היא לו ורוצה בה. ומסבירים את ההבדל: \u0003דהני מילי\u0004 \u0005[שדברים אלה]\u0006 שאמרנו, שהעבד נוח לו בחיי הפקר, מדובר ב\u0003גדול,\u0004 ש\u0003טעם\u0004 כבר \u0003טעם דאיסורא\u0004 \u0005[של איסור]\u0006 ולכן אינו מוכן לוותר על האיסורים שנהנה מהם, \u0003אבל קטן\u0004 שמגיירים אותו לפני שהספיק ללמוד ליהנות מן האיסורים — \u0003זכות הוא לו.\u0004","ומציעים: \u0003לימא מסייע ליה\u0004 \u0005[\u0006האם \u0005לומר\u0006 שאפשר \u0005לסייע לו]\u0006 ממשנתנו, שהרי שנינו: \u0003הגיורת והשבויה והשפחה שנפדו\u0004 או \u0003שנתגיירו\u0004 או \u0003שנשתחררו\u0004 כשהן \u0003פחותות מבנות שלש שנים ויום אחד. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003דאטבלינהו\u0004 \u0005[שהטבילו אותן]\u0006 את הגיורת והשפחה \u0003על דעת בית דין,\u0004 שהרי הן קטנות, ואם כן הוכחה היא שגיור באופן כזה תופס.","ודוחים: \u0003לא, הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בגר שנתגיירו בניו ובנותיו\u0004 הקטנים \u0003עמו,\u0004 וכאן יש סברה אחרת: \u0003דניחא להו במאי דעביד אבוהון\u0004 \u0005[שנוח להם במה שעושה אביהם],\u0006 אבל בגר קטן שלא אביו הוא שמגייר אותו — אין לומר כך.","\u0003אמר רב יוסף:\u0004 בכל מקרה שגיירו את הקטנים, אפילו אם נתגיירו עם אביהם, כאשר \u0003הגדילו\u0004 קטנים אלה — \u0003יכולין\u0004 הם \u0003למחות\u0004 ולומר שאינם מרוצים בגירותם, והריהם חוזרים להיות גויים, ואין דינם כישראל מומר. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי,\u0004 הרי שנינו: \u0003הגיורת והשבויה והשפחה שנפדו,\u0004 או \u0003שנתגיירו,\u0004 או \u0003שנשתחררו\u0004 כשהן \u0003פחותות מבנות שלש שנים ויום אחד\u0004 — \u0003כתובתן מאתים\u0004 זוז. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה\u0006 על \u0005דעתך]\u0006 לומר שאם \u0003הגדילו יכולין למחות\u0004 — וכי \u0003יהבינן\u0004 \u0005[נותנים אנו]\u0006 \u0003לה כתובה דאזלה ואכלה\u0004 \u0005[שהולכת ואוכלת,\u0006 נהנית ממנה\u0005]\u0006 \u0003בגיותה\u0004 (בהיותה גויה)? שהרי יכולה היא למחות כשתגדל, ותחזור להיות גויה!","ומשיבים: \u0003לכי גדלה\u0004 \u0005[כאשר\u0006 היא \u0005תגדל]\u0006 ולא תימחה נותנים לה כתובה, ולא קודם לכן. והקשה אביי: \u0003לכי גדלה נמי ממחייא ונפקא\u0004 \u0005[כאשר תגדל גם כן\u0006 ולא תקבל, שמא \u0005תמחה\u0006 לאחר זמן \u0005ותצא]\u0006 לגויות! ומשיבים: \u0003כיון שהגדילה שעה אחת ולא מיחתה — שוב אינה יכולה למחות.\u0004 ואם כן, אין מכאן ראיה כנגד דברי רב יוסף.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 מצד אחר, שנינו: \u0003אלו נערות שיש להן קנס,\u0004 שאם נאנסו חייב האונס לשלם קנס: \u0003הבא על הממזרת,\u0004 או \u0003על הנתינה,\u0004 או \u0003על הכותית,\u0004 או \u0003על הגיורת,\u0004 או \u0003על השבויה,\u0004 או \u0003על השפחה שנפדו\u0004 או \u0003שנתגיירו,\u0004 או \u0003שנשתחררו\u0004 כשהן \u0003פחותות מבנות שלש שנים ויום אחד,\u0004 כל אלו \u0003יש להן קנס. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שאם \u0003הגדילו יכולין למחות\u0004 — וכי \u0003יהבינן\u0004 \u0005[נותנים אנו]\u0006 \u0003לה\u0004 לגיורת הקטנה \u0003קנס דאזלה ואכלה\u0004 \u0005[שתלך ותאכל\u0006 אותו\u0005]\u0006 \u0003בגיותה\u0004 \u0005[בגויותה]?\u0006","ומשיבים: \u0003לכי גדלה\u0004 \u0005[כאשר\u0006 היא \u0005תגדל]\u0006 ותגיע לבגרות ולא תמחה — אז יתנו לה את הקנס. ומקשים: \u0003כי גדלה נמי ממחייא ונפקא\u0004 \u0005[כאשר תגדל גם כן\u0006 שמא \u0005תמחה\u0006 לאחר זמן \u0005ותצא\u0006 לגויות\u0005]!\u0006 ומשיבים באותו אופן: \u0003כיון שהגדילה שעה אחת ולא מיחתה — שוב אינה יכולה למחות.\u0004","ומעירים: \u0003אביי לא אמר כרבא,\u0004 לא הקשה מאותו מקור, כי \u0003התם קנסא\u0004 \u0005[שם\u0006 מדובר ב\u0005קנס],\u0006 ו\u0003היינו טעמא\u0004 \u0005[\u0006ו\u0005זה הטעם]\u0006 שהוא מחוייב — \u0003שלא יהא חוטא נשכר,\u0004 ולא יפטר מן הקנס על עבירה שעשה רק מפני שיש חשש לגבי אשה זו בעתיד שמא תמחה.","ומצד אחר \u0003רבא לא אמר כאביי\u0004 ולא הקשה מהמקור שהקשה אביי — משום ש\u0003כתובה היינו טעמא\u0004 \u0005[זה הטעם]\u0006 שתיקנו אותה חכמים לכל אשה — כדי \u0003שלא תהא\u0004 אשתו \u0003קלה בעיניו להוציאה\u0004 בכל עת שירצה. וזו, כל עוד אינה מוחה, הלוא ישראלית היא, וצריך לדאוג לתקנתה.","\u0003הגדול שבא על הקטנה\u0004 הפחותה מבת שלוש שנים, או \u0003קטן\u0004 (פחות מבן תשע שנים) \u0003שבא על הגדולה, ומוכת עץ,\u0004 כלומר, זו שנקרע קרום בתוליה על ידי חבלה, כגון על ידי עץ — כל אלה \u0003כתובתן מאתים\u0004 זוז, כשנישאו, אלו \u0003דברי ר' מאיר.\u0004 שלדעתו לענין הלכה הן נחשבות כבתולות גמורות. \u0003וחכמים אומרים: מוכת עץ כתובתה מנה,\u0004 שהרי בפועל אינה בתולה עוד.","\u0003בתולה\u0004 שהיא \u0003אלמנה\u0004 או \u0003גרושה\u0004 או \u0003חלוצה מן הנישואין — כתובתן מנה.\u0004 שכיון שנישאו, אף שעדיין לא בא עליהן הבעל ונשארו בתולות — הריהן נחשבות כבעולות,"],["\u0003ואין להן טענת בתולים.\u0004 כלומר, אין הבעל יכול לטעון כנגדן שהוטעה ושנשאן בחזקת בתולות.","וכן \u0003הגיורת והשבויה והשפחה שנפדו ושנתגיירו ושנשתחררו יתירות על בנות שלש שנים ויום אחד — כתובתן מנה\u0004 בלבד, \u0003ואין להן\u0004 (עליהן) \u0003טענת בתולין\u0004 כדי להפסידן כתובת־המנה, מפני שכשנשא אותן היו בחזקת בעולות.","\u0003אמר רב יהודה אמר רב: קטן הבא על הגדולה\u0004 — \u0003עשאה מוכת עץ,\u0004 למרות שאין ביאת קטן נחשבת לביאה גמורה. וסיפר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי\u0006 את הדבר הזה \u0005לפני]\u0006 \u0003שמואל, אמר\u0004 לי: \u0003אין מוכת עץ בבשר,\u0004 כלומר, על ידי בשר, על ידי ביאה, אין האשה נקראת מוכת עץ.","ומעירים: \u0003איכא דמתני לה להא שמעתא באפי נפשה\u0004 \u0005[יש ששונים את המימרה הזו בפני עצמה],\u0006 ובאופן זה: \u0003קטן הבא על הגדולה, רב אמר: עשאה מוכת עץ, ושמואל אמר: אין מוכת עץ בבשר.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אושעיא,\u0004 שנינו במשנתנו: \u0003גדול שבא על הקטנה, וקטן הבא על הגדולה, ומוכת עץ — כתובתן מאתים,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: מוכת עץ כתובתה מנה.\u0004 וכיון שמבדילים בין ביאת קטן ומוכת עץ משמע שלדעת חכמים קטן הבא על הגדולה, אינה נעשית בכך מוכת עץ!","\u0003אמר רבא\u0004 לתרץ את שיטת רב: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את המשנה: \u0003גדול הבא על הקטנה — ולא כלום\u0004 אין זו נחשבת ביאה כלל, מכיון שב\u0003פחות מכאן,\u0004 בפחות מגיל שלוש, הרי זה \u0003כנותן אצבע בעין דמי\u0004 \u0005[נחשב],\u0006 שכשם שכשדמעה יוצאת בשל כך מן העין, דמעה אחרת חדשה באה תחתיה, כך גם הבתולים נקרעים וחוזרים. \u0003וקטן הבא על הגדולה — עשאה מוכת עץ. ו\u0004בדין \u0003מוכת עץ גופא\u0004 \u0005[עצמה]\u0006 \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 היא בין \u0003ר' מאיר ורבנן\u0004 \u0005[וחכמים],\u0006 שלר' מאיר — כתובתה מאתים, ולחכמים — כתובתה מנה.","\u0003אמר רמי בר חמא: מחלוקת\u0004 זו, היא דווקא \u0003כשהכיר בה,\u0004 כלומר, שידע קודם לכן שהיא מוכת עץ, ש\u0003ר' מאיר מדמי לה\u0004 \u0005[מדמה אותה]\u0006 \u0003לבוגרת,\u0004 שגם היא בתוליה מתמעטים עם הגיל, ואינה עוד בתולה בשלימות, ובכל זאת כתובתה מאתיים. \u0003ורבנן מדמו לה\u0004 \u0005[וחכמים מדמים אותה]\u0006 \u0003לבעולה,\u0004 וכתובתה מנה, \u0003אבל\u0004 אם \u0003לא הכיר בה\u0004 וחשב שהיא בתולה גמורה — \u0003דברי הכל\u0004 לא מגיע לה \u0003ולא כלום.\u0004 שכאשר הדבר מתגלה, אין לה כתובה כלל, לפי שהיה זה מקח טעות.","ושואלים: \u0003ור' מאיר, אמאי מדמי לה\u0004 \u0005[מדוע מדמה אותה]\u0006 \u0003לבוגרת, נדמייה\u0004 \u0005[שידמה אותה]\u0006 \u0003לבעולה!\u0004 ומשיבים: יש הבדל, והוא: שה\u0003בעולה — איתעביד\u0004 \u0005[נעשה]\u0006 \u0003בה מעשה בידי אדם,\u0004 ואילו \u0003הא\u0004 \u0005[זו],\u0006 מוכת עץ — \u0003לא איתעביד\u0004 \u0005[נעשה]\u0006 \u0003בה מעשה בידי אדם.\u0004 ומצד שני אפשר לשאול: \u0003ורבנן, אדמדמו לה\u0004 \u0005[וחכמים, עד ש\u0006הם \u0005מדמים אותה]\u0006 \u0003לבעולה, נדמייה\u0004 \u0005[נדמה אותה]\u0006 \u0003לבוגרת?\u0004 ומשיבים: \u0003בוגרת לא איתעביד\u0004 \u0005[נעשה]\u0006 \u0003בה מעשה כלל,\u0004 אלא בדרך הטבע השתנה גופה, \u0003הא\u0004 \u0005[זו,\u0006 מוכת עץ\u0005] —\u0006 \u0003איתעביד\u0004 \u0005[נעשה]\u0006 \u0003בה מעשה.\u0004","וכל זה לענין הגדרתה, \u0003אבל\u0004 לדעת רמי בר חמא אם \u0003לא הכיר בה\u0004 והיא הטעתה אותו שהיא בתולה גמורה — \u0003לדברי הכל\u0004 לא מגיע לה \u0003ולא כלום. מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב נחמן,\u0004 ממה ששנינו, \u0003היא\u0004 האשה \u0003אומרת: מוכת עץ אני,\u0004 שמודה שאינה בתולה, אבל טוענת שהסיבה היא משום שהיא מוכת עץ, \u0003והוא אומר: לא כי, אלא דרוסת איש את,\u0004 כלומר, נבעלת על ידי איש — \u0003רבן גמליאל ור' אליעזר אומרים: נאמנת.\u0004 והרי כאן מדובר במקרה שלא הכיר בה, ובכל זאת סבורים רבן גמליאל ור' אליעזר שנאמנת על כל פנים לקבל מנה, שהרי בוודאי היא טוענת שמגיעה לה כתובה. ואם כן מוכח מכאן שאין הכל מודים שאינה מקבלת ולא כלום כאשר לא הכיר בה.","\u0003אלא אמר רבא,\u0004 כך יש לפרש: \u0003בין הכיר בה ובין לא הכיר בה\u0004 — \u0003ל\u0004דעת \u0003ר' מאיר\u0004 כתובתה \u0003מאתים,\u0004 ואין זה נחשב כמקח טעות כלל. ו\u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 אם \u0003הכיר בה\u0004 — מקבלת \u0003מנה\u0004 כבעולה, \u0003לא הכיר בה — ולא כלום,\u0004 שמקח טעות הוא, שהרי נשאה בתורת בתולה. והמשנה שדנה במקרה שהאשה אומרת שהיא מוכת עץ, הריהי כדעת ר' מאיר.","ומעירים: \u0003והדר ביה\u0004 \u0005[וחזר בו]\u0006 \u0003רבא\u0004 מדבריו אלה, ואף לדעתו לשיטת חכמים, בין הכיר בה, בין לא הכיר — כתובתה מנה, ולשיטת ר' מאיר — מאתים. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו בברייתא\u0006\u0005]:\u0006 \u0003כיצד הוצאת שם רע\u0004 האמורה בתורה? \u0003בא\u0004 הבעל \u0003לבית דין, ואמר\u0004 לאבי האשה: \u0003פלוני, לא מצאתי לבתך בתולים. אם יש עדים שזינתה תחתיו — יש לה כתובה מנה.\u0004 ומיד תוהים על הברייתא: \u0003אם יש עדים שזינתה תחתיו,\u0004 בין זמן האירוסין לנישואין — הלא \u0003בת\u0004 (כלומר, חייבת) \u0003סקילה היא,\u0004 כדין אשה שנבעלה לאחר מרצונה בהיותה ארוסה, ואין איפוא מקום כלל לדבר על כתובה המגיעה לה! אלא יש לתקן, ו\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אם יש עדים שזינתה תחתיו,\u0004 כאשר היתה כבר ארוסה — הרי דינה \u0003בסקילה.\u0004 אם \u0003זינתה מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני האירוסין — \u0003יש לה כתובה מנה,\u0004 כדין בעולה.","\u0003ואמר רב חייא בר אבין אמר רב ששת: זאת אומרת\u0004 שאשה ש\u0003כנסה\u0004 כשהיא \u0003בחזקת בתולה ונמצאת בעולה — יש לה\u0004 על כל פנים \u0003כתובה מנה. ומתיב\u0004 \u0005[ומקשה]\u0006 \u0003רב נחמן\u0004 על דברי רב ששת ממה ששנינו: \u0003הנושא את האשה ולא מצא לה בתולים, היא אומרת: משארסתני,\u0004 כלומר, לאחר האירוסין \u0003נאנסתי ונסתחפה שדהו.\u0004 שכיון שהדבר אירע כאשר היתה ארוסה לו, הרי הוא כאדם שקרה לו אסון משמים, כגון זה שבא שטפון וסחף את שדהו ונמצא מפסיד, ואינו יכול להאשים אדם בכך, \u0003והוא אומר: לא כי, אלא עד שלא אירסתיך\u0004 נאנסת \u0003והיה מקחי מקח טעות,\u0004 שהתכוונתי לשאת בתולה דווקא. \u0003ו\u0004כיון שנמצאה בעולה \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 כתובה \u0003כלל?\u0004","\u0003ואמר להו\u0004 \u0005[להם]\u0006 \u0003רב חייא בר אבין: אפשר רב עמרם וכל גדולי הדור יתבי\u0004 \u0005[יושבים]\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר רב ששת להא שמעתא\u0004 \u0005[את המימרה הזו]\u0006 \u0003וקשיא להו\u0004 \u0005[והיה קשה להם]\u0006 קושיית רב נחמן, \u0003ושני\u0004 \u0005[ותירצו]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מקח טעות\" — נמי\u0004 \u0005[גם כן]\u0006 הכוונה היא \u0003ממאתים,\u0004 שכיון שאינה בתולה לא מגיע לה סכום זה. \u0003אבל מנה\u0004 על כל פנים \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה, ואת אמרת לית\u0004 \u0005[ואתה אומר\u0006 ש\u0005אין]\u0006 \u0003לה\u0004 כתובה \u0003כלל\u0004 ואין מקום כלל לדברי רב ששת.","\u0003ואמר רבא: מאן דקא מותיב, שפיר קא מותיב\u0004 \u0005[מי שמקשה,\u0006 רב נחמן שהקשה קושיה זו, \u0005יפה\u0006 הוא \u0005מקשה],\u0006 כי טענת \u0003מקח טעות — לגמרי משמע,\u0004 שרוצה לבטל את הקידושין מעיקרם. ושואלים: אם כן, \u0003אלא קשיא הך\u0004 \u0005[קשה זו]\u0006 ששנינו בברייתא המדברת על מוציא שם רע, שאם נשאה בחזקת שהיא בתולה ונמצאה בעולה, יש לה על כל פנים מנה? על כן \u0003תריץ, ואימא הכי\u0004 \u0005[תרץ,\u0006 ישב את הדבר \u0005ואמור כך]\u0006 את לשון הברייתא: \u0003אם יש עדים שזינתה תחתיו\u0004 — הרי זו \u0003בסקילה. זינתה מעיקרא\u0004 \u0005[מתחילה] —\u0006 \u0003ולא כלום,\u0004 לא מגיע לה דבר, שהיה זה מקח טעות. ואם לא הכיר בה ו\u0003נמצאת מוכת עץ — יש לה כתובה מנה.\u0004 זה היה תירוצו של רבא לאותו ענין.","ויש לשאול לענייננו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר\u0004 ש\u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 מוכת עץ אם \u0003לא הכיר בה\u0004 שלא היתה בתולה — לא מגיע לה \u0003ולא כלום! אלא שמע מינה הדר ביה\u0004 \u0005[למד מכאן\u0006 ש\u0005חזר בו]\u0006 \u0003רבא מ\u0004הסברה \u0003ההיא\u0004 וגם הוא סבור, שאף לחכמים אם לא הכיר בה, על כל פנים מגיע לה מנה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כנסה\u0004 בעלה ה\u0003ראשון לשום\u0004 (לשם) \u0003נישואין,\u0004 אפילו אם \u0003יש לה עדים\u0004 המעידים \u0003שלא נסתרה\u0004 (נתייחדה עמו), \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 מעידים הם ש\u0003נסתרה,\u0004 אולם אף לדבריהם \u0003לא שהתה\u0004 עמו \u0003כדי ביאה,\u0004 ואחר כך מת בעלה הראשון, או שגירשה, וחזרה ונשאה לאחר — מכל מקום \u0003אין השני יכול לטעון טענת בתולים,\u0004 כלומר, אינו יכול לומר שחשב שבתולה היא ונתברר לו שאינו כן, ורוצה להפסידה את כתובתה. \u0003שהרי כנסה ראשון\u0004 והוא צריך להביא בחשבון שאשה לאחר כניסה בעולה היא."],["\u0003אמר רבה: זאת אומרת,\u0004 אפשר להסיק מהלכה זו כי אשה ש\u0003כנסה\u0004 בעלה \u0003בחזקת\u0004 שהיא \u0003בתולה\u0004 (שהרי היו לה עדים שלא נסתרה), \u0003ונמצאת בעולה — יש לה\u0004 על כל פנים \u0003כתובה מנה. רב אשי אמר:\u0004 לא כן, \u0003בעלמא\u0004 \u0005[כרגיל]\u0006 \u0003לעולם, אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003לית\u0004 \u0005[\u0006ש\u0005אין]\u0006 \u0003לה\u0004 כתובה \u0003כלל,\u0004 שכן היה זה מקח טעות, \u0003ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 שאינו יכול להפקיעה מכתובה לגמרי, \u0003שהרי כנסה ראשון,\u0004 והיה צריך בעלה השני להניח שבא עליה בעלה הראשון, אף שהעדים אמרו שלא נסתרה.","ושואלים לגוף ההלכה: \u0003ו\u0004כיון שמעידים עליה שלא נבעלה לראשון, ומצאה השני שהיא בעולה, \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 אם כן \u0003שמא תחתיו,\u0004 לאחר שקידש אותה השני, \u0003זינתה,\u0004 והרי היא אסורה עליו משום סוטה! \u0003אמר רב שרביא:\u0004 כאן מדובר \u0003כגון שקידש ובעל לאלתר\u0004 \u0005[מיד],\u0006 שהקידושין והנישואין היו סמוכים זה לזה, ולא ייתכן שזינתה בעודה ארוסה לו, אלא ודאי שאבדה בתוליה לפני שאירס אותה השני.","\u0003ואיכא דמתני לה אמתניתין\u0004 \u0005[ויש ששנו אותה,\u0006 את הדברים הללו, \u0005על משנתנו]\u0006 שלנו, ששנינו בה: \u0003בתולה אלמנה\u0004 או \u0003גרושה\u0004 או \u0003חלוצה מן הנישואין — כתובתן מנה ואין להן\u0004 (עליהן) \u0003טענת בתולין.\u0004 ונברר: \u0003בתולה מן הנישואין היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]?\u0006 — \u0003כגון שנכנסה לחופה ולא נבעלה\u0004 עדיין.","ועל כך \u0003אמר רבה: זאת אומרת, כנסה בחזקת בתולה ונמצאת בעולה — כתובתה מנה. רב אשי אמר: לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003בעלמא לית\u0004 \u0005[כרגיל אין]\u0006 \u0003לה\u0004 כתובה \u0003כלל\u0004 אם נמצאה בעולה, \u0003ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 \u0003שהרי נכנסה\u0004 כבר \u0003לחופה\u0004 ועליו להניח שבעולה היא.","ושאלו: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא תחתיו זינתה\u0004 ואסורה עליו! על כך \u0003אמר רב שרביא: כגון שקידש ובעל לאלתר\u0004 \u0005[מיד].\u0006","ומעירים: \u0003מאן דמתני לה\u0004 \u0005[מי ששונה אותה,\u0006 את דברי רבה\u0005]\u0006 על דברי ה\u0003ברייתא\u0004 שמפורש בה שהעידו שלא נבעלה, \u0003כל שכן\u0004 שהוא יכול לייחס את הדברים \u0003אמתניתין\u0004 \u0005[על משנתנו],\u0006 \u0003ומאן דמתני לה אמתניתין\u0004 \u0005[ומי ששונה אותה על משנתנו],\u0006 \u0003אבל\u0004 על ה\u0003ברייתא לא\u0004 שונה הוא אותה. \u0003משום דמצי אמר\u0004 \u0005[שיכול\u0006 הבעל \u0005לומר]\u0006 \u0003לה\u0004 לאשה: \u0003אנא\u0004 \u0005[אני]\u0006 על ה\u0003עדים סמכי\u0004 \u0005[סמכתי]\u0006 שאמרו שלא נסתרה, ומשום כך הניח שבתולה היתה, והיה זה מקח טעות, ולא היה רב אשי חולק על כך.","\u0003האוכל אצל חמיו ב\u0004ארץ \u0003יהודה שלא בעדים,\u0004 כלומר, אם החתן והכלה מתייחדים לפני הנישואין, כדרך שהיו עושים בארץ יהודה שהיו הארוס והארוסה מצויים יחד לפני הנישואין — \u0003אינו יכול לטעון טענת בתולים, מפני שמתייחד עמה\u0004 ויש לחשוש שבא עליה.","\u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 ופירש דין זה בלשון \u0003\"האוכל\", מכלל\u0004 הדברים אתה למד \u0003דאיכא דוכתא\u0004 \u0005[שיש מקום]\u0006 \u0003ב\u0004ארץ \u0003יהודה נמי\u0004 \u0005[גם כן]\u0006 \u0003דלא אכיל\u0004 \u0005[ש\u0006החתן \u0005אינו אוכל]\u0006 אצל חמיו, ואינו נפגש ביחידות עם הכלה. \u0003אמר אביי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003ביהודה נמי\u0004 \u0005[גם כן]\u0006 \u0003מקומות מקומות יש,\u0004 שאין מנהג אחיד לכל ארץ יהודה, אלא מנהגים שונים. ומביאים ראיה לדבר, \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה: ביהודה, בראשונה היו מייחדין את החתן ואת הכלה שעה אחת\u0004 (זמן מה) \u0003קודם כניסתן לחופה, כדי שיהא לבו גס\u0004 (רגיל) \u0003בה\u0004 ולא יתבייש ממנה בשעת בעילה, \u0003ובגליל לא היו עושין כן.\u0004","ועוד מנהג \u0003ביהודה: בראשונה היו מעמידין להם שני שושבינין, אחד לו ואחד לה, כדי למשמש\u0004 (לבדוק) \u0003את\u0004 מעשי \u0003החתן ואת\u0004 מעשי \u0003הכלה בשעת כניסתן לחופה\u0004 ולאחריה כדי לוודא שאינם מרמים בצורה זו או אחרת לגבי דם הבתולים, \u0003ובגליל לא היו עושין כן,\u0004 וברור כי מנהג זה של שושבינין אין לו מקום אלא כאשר החתן והכלה לא התייחדו קודם לכן. הרי שיש כאן מנהג יהודה אחר, שלא כמנהג הנראה מתוך דברי המשנה.","\u0003ביהודה, בראשונה היו שושבינין ישנים בבית שחתן וכלה ישנים בה,\u0004 כדי לבדוק מיד לאחר מעשה את הסדין שנבעלה עליו, שבמקרה ואכן ניכרים בו טיפות דם, לא יעלים אותו הבעל ויטען טענת בתולים, וכן אם אין טיפות דם ניכרים בו, שלא תעלימנו האשה ותטען שבתולה היתה. \u0003ובגליל לא היו עושין כן.\u0004","\u0003ו\u0004סיכום הדברים: \u0003כל שלא נהג כמנהג הזה אינו יכול לטעון טענת בתולים.\u0004 ושואלים על המשפט האחרון \u0003אהייא\u0004 \u0005[על איזו,\u0006 למה הוא מתייחס\u0005]?\u0006 \u0003אילימא ארישא\u0004 \u0005[אם תאמר על ראשה\u0006 של הברייתא\u0005],\u0006 ביחס למנהג שהיו מייחדים את החתן והכלה, אם כן \u0003\"כל שנהג\"\u0004 כמנהג הזה והתייחד עם הכלה \u0003מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר, שהרי אז אינו יכול לטעון טענת בתולים, שמא בא עליה קודם לכן.","\u0003אלא\u0004 נאמר שמדובר \u0003אסיפא\u0004 \u0005[על הסוף,\u0006 על הקטע השני\u0005],\u0006 במנהג שהיו השושבינים ממשמשים אותם, אם כן \u0003\"כל שלא מושמש\",\u0004 כלומר, שלא נבדק על ידי השושבינים \u0003מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 ולמה נאמר בלשון \"כל שלא נהג\"? שהלא אין הדבר תלוי בבעל אלא בבני משפחת הכלה, שהם המביאים את העדים לבדוק אותו.","\u0003אמר אביי: לעולם\u0004 תפרש שהמשפט הזה מתייחס \u0003ארישא\u0004 \u0005[על ראשה]\u0006 \u0003ותני\u0004 \u0005[ושנה,\u0006 תקן\u0005]:\u0006 \u0003\"כל שנהג\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: והא\u0004 \u0005[והרי]\u0006 \u0003\"כל שלא נהג\" קתני\u0004 \u0005[שנה]\u0006 במפורש, וקשה להפוך את המשמעות רק בגלל הקושי בהבנת הענין. \u0003אלא אמר רבא: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לפרש: \u0003כל שלא נהג מנהג גליל בגליל, אלא מנהג יהודה בגליל — אינו יכול לטעון טענת בתולים. רב אשי אמר: לעולם\u0004 תשנה את המשפט הזה \u0003אסיפא\u0004 \u0005[על הסוף],\u0006 \u0003ותני\u0004 \u0005[ושנה]:\u0006 \u0003\"כל שלא מושמש\".\u0004 כלומר, מה שאמר \"כל שלא נהג\" כוונתו שלא נהגו בו במנהג זה של בדיקה ומשמוש.","\u0003אחת אלמנת ישראל ואחת אלמנת כהנים\u0004 (אלמנה שהיא בת כהנים) — \u0003כתובתה מנה. בית דין של כהנים היו גובין לבתולה\u0004 בת כהן \u0003ארבע מאות זוז\u0004 (כפליים מבתולה אחרת) \u0003ולא מיחו בידם חכמים.\u0004","\u0003תנא\u0004 \u0005[שנה]\u0006 החכם בתוספתא: \u0003ואלמנת כהנים\u0004 — \u0003כתובתה מאתים.\u0004 ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו]\u0006 במשנתנו: \u0003אחת אלמנת ישראל ואחת אלמנת כהנים כתובתן מנה!\u0004","\u0003אמר רב אשי: שתי תקנות הוו\u0004 \u0005[היו],\u0006 כלומר, תקנות אלה עברו שני שלבים שונים, \u0003מעיקרא תקינו\u0004 \u0005[מתחילה תיקנו]\u0006 בית דין של כהנים \u0003לבתולה\u0004 בת כהן \u0003ארבע מאות זוז, ולאלמנה מנה\u0004 כמו לאלמנת ישראל."],["\u0003כיון דחזו דמזלזלי בהו\u0004 \u0005[שראו שמזלזלים\u0006 הכהנים \u0005בהן,\u0006 באלמנות\u0005]\u0006 \u0003תקינו להו מאתן\u0004 \u0005[תיקנו להן מאתים]\u0006 זוז בכתובתן, כדי להחשיבן. \u0003כיון דחזו דקא פרשין מינייהו\u0004 \u0005[שראו ש\u0006היו החתנים \u0005פורשים מהן]\u0006 מלשאת אלמנות הכהנים, \u0003דאמרי\u0004 \u0005[ש\u0006היו \u0005אומרים]:\u0006 \u0003עד דנסבינן\u0004 \u0005[שאנו נושאים]\u0006 \u0003אלמנת כהנים\u0004 ומתחייבים בכתובה מאתים — \u0003ניזיל ניסיב\u0004 \u0005[נלך\u0006 ו\u0005נישא]\u0006 \u0003בתולה בת ישראל,\u0004 באותו סכום של כתובה, ולא היו נושאים את אלמנות הכהנים. על כן \u0003אהדרינהו למלתייהו\u0004 \u0005[החזירון לדבריהן,\u0006 לדינן\u0005]\u0006 כמקודם. ואם כן, המשנה והתוספתא מדברות על זמנים שונים, ותקנות שונות באותו נושא.","שנינו ש\u0003בית דין של כהנים\u0004 תיקנו כתובה כפולה לבתולות כהנים. \u0003אמר רב יהודה אמר שמואל: לא בית דין של כהנים בלבד אמרו, אלא אפילו משפחות המיוחסות בישראל, אם רצו לעשות כדרך שהכהנים עושין — עושין,\u0004 והרשות בידם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003הרוצה לעשות כדרך שהכהנים עושין, כגון בת ישראל לכהן, ובת כהן לישראל — עושין.\u0004 ונדייק: כאן מדובר דווקא ב\u0003בת ישראל לכהן, ובת כהן לישראל הוא דאיכא\u0004 \u0005[שיש]\u0006 \u0003צד כהונה\u0004 במשפחת החתן או הכלה. \u0003אבל\u0004 לכאורה \u0003בת ישראל לישראל — לא!\u0004","ומשיבים: בלשון \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 \u0003קאמר\u0004 \u0005[אמר],\u0006 וכך יש להבין: \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003בת ישראל לישראל, דלא מצי אמר\u0004 \u0005[שאין\u0006 הוא, החתן, \u0005יכול לומר]\u0006 \u0003לה: עלויי קא מעלינן ליך\u0004 \u0005[מעלה אני אותך\u0006 במעלות הייחוס\u0005]\u0006 על ידי שאני נושא אותך, ולכן מובן שבנות משפחה מיוחסת תרצנה כתובה גדולה יותר, \u0003אבל בת ישראל לכהן, דמצי אמר\u0004 \u0005[שיכול\u0006 הכהן \u0005לומר]\u0006 \u0003לה: עלויי קא מעלינן ליך\u0004 \u0005[מעלה אני אותך\u0006 בייחוס\u0005],\u0006 שהרי את נעשית אשת כהן בנישואיך לי, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יוכלו בנות משפחות מיוחסות לגבות מהבעל כתובה מרובה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאפילו בת ישראל לכהן ממשפחה מיוחסת יכולה לעשות כן, וכל שכן בת ישראל לישראל.","\u0003הנושא את האשה ולא מצא לה בתולים. היא אומרת: משארסתני\u0004 (לאחר שארסתני) \u0003נאנסתי, ונסתחפה שדהו.\u0004 כלומר, ההפסד הוא שלך, כי ברשותך אירע לי הדבר, והרי זה כאילו שטפון סחף את שדך. \u0003והוא אומר: לא כי,\u0004 לא כך היה המעשה, \u0003אלא עד שלא ארסתיך\u0004 נאנסת, \u0003והיה מקחי מקח טעות,\u0004 שרציתי לשאת בתולה — \u0003רבן גמליאל ור' אליעזר אומרים: נאמנת\u0004 היא. \u0003ר' יהושע אומר: לא מפיה אנו חיין,\u0004 כלומר, אין סומכים על דבריה, \u0003אלא הרי זו בחזקת בעולה עד שלא תתארס\u0004 (לפני שהתארסה), \u0003ו\u0004אנו מניחים ש\u0003הטעתו\u0004 בזה, \u0003עד שתביא ראיה לדבריה\u0004 שהדבר אירע לאחר האירוסין.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: הבא לחבירו ואומר: \u0003\"מנה לי בידך\",\u0004 כלומר, אתה חייב לי מנה, \u0003והלה\u0004 (הנתבע) \u0003אומר: איני יודע. רב יהודה ורב הונא אמרי\u0004 \u0005[אומרים]:\u0006 במקרה כזה \u0003חייב\u0004 הנתבע, שכיון שאינו מכחיש — חייב לשלם. \u0003ורב נחמן ור' יוחנן אמרי\u0004 \u0005[אומרים]:\u0006 \u0003פטור.\u0004 ומסבירים את טעמיהם: \u0003רב הונא ורב יהודה אמרי\u0004 \u0005[אומרים]:\u0006 \u0003חייב,\u0004 וטעמם: \u0003ברי\u0004 (ודאי) \u0003ושמא — ברי עדיף,\u0004 ומכיון שהתובע טוען טענת ודאי והנתבע אינו טוען טענת ודאי, אלא טענת שמא — טענת ברי עדיפה. \u0003רב נחמן ור' יוחנן אמרי\u0004 \u0005[אומרים]:\u0006 \u0003פטור,\u0004 ומדוע — \u0003אוקי ממונא\u0004 \u0005[העמד\u0006 את \u0005הממון]\u0006 \u0003בחזקת מריה\u0004 \u0005[בעליו],\u0006 וכיון שהממון נמצא אצל הנתבע, והתובע אינו יכול להביא ראיה, והוא בא רק בטענה בלבד — אין מוציאים ממון בלא ראיה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 של \u0003רב הונא ורב יהודה —\u0004 מקורה בדברי \u0003שמואל היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 אשה פנוייה ש\u0003היתה מעוברת, ואמרו לה: מה טיבו של עובר זה,\u0004 כלומר, ממי נתעברת? והיא אומרת: עובר זה \u0003מאיש פלוני, וכהן הוא\u0004 ובודאי כשר הוא ביחוסו — \u0003רבן גמליאל ור' אליעזר אומרים: נאמנת\u0004 לומר שהעובר כשר. \u0003ואמר רב יהודה אמר שמואל: הלכה כרבן גמליאל.\u0004","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב שמואל בר יהודה לרב יהודה: שיננא\u0004 \u0005[גדול השיניים]\u0006 \u0003אמרת לן משמיה\u0004 \u0005[אמרת לנו משמו]\u0006 של \u0003שמואל: הלכה כרבן גמליאל אף בראשונה.\u0004 שאף במחלוקת במשנתנו, שהיא הראשונה בסדרת מחלוקות לענין טענות שונות, הלכה כדבריו. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 החידוש\u0005]\u0006 \u0003אף בראשונה?\u0004 במה שונה הלכה זו? ומסבירים: \u0003אף על גב דאיכא למימר\u0004 \u0005[אף על פי שיש\u0006 מקום \u0005לומר]\u0006 במשנתנו \u0003אוקי ממונא\u0004 \u0005[העמד\u0006 את \u0005הממון]\u0006 \u0003בחזקת מריה\u0004 \u0005[בעליו],\u0006 וכיון שהממון של הכתובה הוא בחזקת הבעל, והאשה היא הבאה להוציא ממנו — בכל זאת \u0003אמר רבן גמליאל\u0004 כי טענת \u0003ברי\u0004 של האשה \u0003עדיף\u0004 מטענת שמא של הבעל. שהרי הוא אינו יודע בוודאות מתי נאנסה ואין טענתו אלא טענת שמא.","ושואלים: \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 כי \u0003רב יהודה ורב הונא דאמרי\u0004 \u0005[שאומרים,\u0006 סבורים הם\u0005]\u0006 \u0003כ\u0004דעת \u0003רבן גמליאל,\u0004 שטענת ודאי עדיפה מטענת שמא אפילו להוציא ממון מחזקתו, והדין עם התובע. \u0003ו\u0004אילו \u0003רב נחמן ור' יוחנן דאמרי\u0004 \u0005[שאומרים]\u0006 \u0003כ\u0004דעת \u0003ר' יהושע\u0004 שאין מוציאים ממון בטענה בלבד?","ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003רב נחמן: אנא דאמרי\u0004 \u0005[אני,\u0006 מה \u0005שאמרתי],\u0006 זה \u0003אפילו כ\u0004דעת \u0003רבן גמליאל.\u0004 שכן \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבן גמליאל התם\u0004 \u0005[שם]\u0006 בטענות שבין האיש והאשה, \u0003אלא\u0004 משום \u0003דאיכא\u0004 \u0005[שיש]\u0006 טענת \u0003מגו\u0004 \u0005[מתוך],\u0006 שיש חיזוק לדברי האשה על ידי טענת \"מיגו\", שמתוך שהיתה האשה יכולה לטעון שלא נאנסה כלל, אלא שהיא מוכת עץ, ולא היתה מגנה את עצמה בכך לפני בעלה, ומתוך שלא טענה כך, אלא הודתה שנאנסה, ודאי אמת בפיה ועלינו להאמין לדבריה. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 כשתובע ממון מחבירו \u0003מאי\u0004 \u0005[מה,\u0006 איזה\u0005]\u0006 \u0003מגו איכא\u0004 \u0005[יש]\u0006 שנבוא להאמינו על פי דבריו בלבד? ולכן יודה אף רבן גמליאל שבתביעה זו אין להאמין לטענת הודאי להוציא ממון המוחזק.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר לחלק בדרך אחרת: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003רבן גמליאל התם\u0004 \u0005[שם]\u0006 במשנתנו \u0003אלא דאמרינן אוקמה אחזקה\u0004 \u0005[שאומרים אנו העמד אותה,\u0006 את האשה, \u0005על חזקתה]\u0006 וחזקתה שהיא מתחילתה בתולה, והבעל שטוען שלא היתה בתולה עוד לפני הנישואין הוא המנסה להוציא אותה מחזקת הבתולים שלה, \u0003אבל הכא, מאי\u0004 \u0005[כאן, מה,\u0006 איזו\u0005]\u0006 \u0003חזקה אית ליה להאי\u0004 \u0005[יש לו לזה]\u0006 שתובע ממון חבירו? ולכן אף רבן גמליאל יודה שאין טענת הוודאי שלו מועילה.","ומעירים: \u0003הכי נמי מסתברא כדקא משנינן\u0004 \u0005[כך גם כן מסתבר\u0006 לומר \u0005כפי שאנו מתרצים]\u0006 שגם \u0003רב נחמן הוא\u0004 ש\u0003אמר כ\u0004שיטת \u0003רבן גמליאל,\u0004"],["\u0003אם כן,\u0004 כלומר, אם לא תאמר כך, \u0003קשיא הלכתא אהלכתא\u0004 \u0005[\u0006יהיה \u0005קשה\u0006 מ\u0005הלכה על הלכה],\u0006 \u0003דקיימא לן\u0004 \u0005[שמוחזק בידינו]\u0006 בכלל \u0003הלכתא\u0004 \u0005[הלכה]\u0006 \u0003כרב נחמן בדיני\u0004 ממונות, \u0003ובהא\u0004 \u0005[וב\u0006ענין \u0005זה]\u0006 \u0003אמר רב יהודה אמר שמואל: הלכה כרבן גמליאל.\u0004 ואם היינו אומרים שהשיטות הללו חולקות זו על זו — היתה נוצרת סתירה. \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003שמע מינה כדמשנינן\u0004 \u0005[למד מכאן כפי שתירצנו],\u0006 שדברי רב נחמן מתיישבים אף לשיטת רבן גמליאל. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003היא,\u0004 האשה, \u0003אומרת: מוכת עץ אני,\u0004 כלומר, מודה היא שאינה בתולה, אבל טוענת שאיבדה את הבתולים על ידי תאונה. \u0003והוא אומר: לא כי\u0004 \u0005[כך],\u0006 \u0003אלא דרוסת איש את,\u0004 כלומר, נבעלת על ידי איש. \u0003רבן גמליאל ור' אליעזר אומרים:\u0004 היא \u0003נאמנת\u0004 בטענתה, שהרי היא יודעת בודאי מה שעבר עליה. \u0003ור' יהושע אומר: לא מפיה אנו חיין, אלא הרי זו בחזקת דרוסת איש, עד שתביא ראיה לדבריה\u0004 שהיתה מוכת עץ.","ושואלים: \u0003טענתייהו במאי\u0004 \u0005[טענתם במה],\u0006 כלומר, מה הן הטענות הממוניות של האיש והאשה? \u0003ר' יוחנן אמר: במאתים ומנה.\u0004 כלומר, האשה טוענת שכיון שהיא רק מוכת עץ דינה כבתולה, וכתובתה מאתים. והוא טוען שהיתה בעולה בנישואיה, ואין כתובתה אלא מנה. \u0003ר' אלעזר אמר: במנה ולא כלום.\u0004 שהיא טוענת שכתובתה היא על כל פנים מנה, שאם כי אינה בתולה, אבל גם אין היא כבעולה, ואין לומר שרימתה אותו לגמרי, וכתובתה היא על כל פנים מנה. והוא טוען שכיון שהיא בעולה — היה זה מקח טעות, ולא מגיעה לה כתובה כלל.","ומבארים את השיטות: \u0003ר' יוחנן אמר: במאתים ומנה\u0004 הבעל והאשה מתדיינים, משום שהתנא במשנתנו \u0003סבר לה\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר\u0004 ש\u0003אמר\u0004 ש\u0003בין\u0004 אם \u0003הכיר בה\u0004 הבעל לפני שאירסה שהיא מוכת עץ \u0003ובין לא הכיר בה\u0004 — כתובתה \u0003מאתים. ור' אלעזר\u0004 ש\u0003אומר\u0004 שהמחלוקת בין האיש והאשה היא לגבי \u0003מנה ולא כלום\u0004 — \u0003סבר לה\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003כרבנן, דאמרי\u0004 \u0005[כ\u0006שיטת \u0005חכמים, שאומרים]\u0006 לגבי מוכת עץ, \u0003בין הכיר בה, בין לא הכיר בה\u0004 — כתובתה \u0003מנה\u0004 ולא יותר.","ומסבירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' אלעזר לא קאמר\u0004 \u0005[אמר]\u0006 \u0003כר' יוחנן,\u0004 משום שיש לו טעם לדבריו — \u0003דקא מוקי לה כרבנן\u0004 \u0005[ש\u0006הוא \u0005מעמיד\u0006 את המשנה \u0005כ\u0006שיטת \u0005חכמים,\u0006 וכהלכה\u0005],\u0006 ולא כר' יוחנן שהסביר לשיטת ר' מאיר. \u0003אלא ר' יוחנן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' אלעזר?\u0004","ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 שאם \u0003כנסה\u0004 לאשה \u0003בחזקת\u0004 שהיא \u0003בתולה, ונמצאת בעולה — יש לה\u0004 מכל מקום \u0003כתובה מנה.\u0004 ולפי זה \u0003הכא\u0004 \u0005[כאן],\u0006 אם נפרש כר' אלעזר וכדברי חכמים שהיא טוענת שמוכת עץ היא וכתובתה מנה, \u0003הוא קאמר\u0004 \u0005[אומר]\u0006 שמגיע לה \u0003מנה\u0004 משום שהיא בעולה, \u0003והיא קאמרה\u0004 \u0005[אומרת]\u0006 שמגיע לה \u0003מנה\u0004 משום שמוכת עץ היא, אם כן \u0003מאי איכא\u0004 \u0005[מה\u0006 הבדל \u0005יש]\u0006 \u0003בין\u0004 ה\u0003טענה דידיה\u0004 \u0005[שלו]\u0006 \u0003לטענה דידה\u0004 \u0005[שלה]?\u0006 אלא ודאי על מאתים ומנה הם נידונים, וכר' מאיר.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' אלעזר\u0004 שמפרש שהם מתדיינים לגבי מנה שצריכה היא לקבל לפי דבריה ולא כלום לדברי בעלה — \u0003היינו דקתני תרתי\u0004 \u0005[זו\u0006 הסיבה \u0005ששנה שתים],\u0006 שתי מחלוקות נבדלות, במשנה הקודמת ובמשנה זו: \u0003חדא לאפוקי\u0004 \u0005[אחת\u0006 מהן, משנתנו, באה \u0005להוציא]\u0006 \u0003מ\u0004דברי \u0003רמי בר חמא\u0004 שאמר שמוכת עץ שלא הכיר בה לכל הדעות לא מגיע לה כלום, מפני שזה מקח טעות. ואילו מן המשנה שלנו מוכח שמגיע לה לפחות מנה, שהרי משום כך היא טוענת שמוכת עץ היתה.","\u0003וחדא לאפוקי\u0004 \u0005[ואחת\u0006 כדי \u0005להוציא]\u0006 \u0003מ\u0004דברי \u0003רב חייא בר אבין אמר רב ששת,\u0004 שהכונס אשה בחזקת בתולה ונמצאת בעולה, יש לה כתובה מנה. ולשם כך נאמרו הדברים במשנה הקודמת שהוא טוען \"מקח טעות\" ורוצה להוציאה בלא כתובה כלל. \u0003אלא לר' יוחנן תרתי\u0004 \u0005[שתי]\u0006 משניות העוסקות באותה בעיה עצמה \u0003למה לי?\u0004 שהרי אי אפשר לומר שבאה המשנה להוציא מדברי ר' חייא, שהרי כבר הוכחנו למעלה שלדעת ר' יוחנן כנסה בחזקת בתולה ונמצאת בעולה יש לה מנה!","ומסבירים: \u0003חדא\u0004 \u0005[אחת\u0006 מהן\u0005]\u0006 באה \u0003להודיעך כחו\u0004 של \u0003רבן גמליאל\u0004 עד כמה הוא סומך על טענתה, \u0003וחדא\u0004 \u0005[ואחת]\u0006 \u0003להודיעך כחו\u0004 של \u0003ר' יהושע,\u0004 עד כמה אין סומכים עליה. ומסבירים: \u0003קמייתא\u0004 \u0005[הראשונה]\u0006 שהיא מודה שנאנסה, אלא שטוענת שנאנסה כאשר היתה ארוסתו — הרי זה \u0003להודיעך כחו\u0004 של \u0003ר' יהושע, דאף על גב דאיכא למימר\u0004 \u0005[שאף על פי שיש\u0006 מקום \u0005לומר]\u0006 \u0003מיגו\u0004 לסייע לאשה, שאילו היתה רוצה לשקר, היתה יכולה לומר שהיא מוכת עץ, ואף שלא עשתה כן, אלא טענה טענה כזו שיש בה גנאי לגביה — למרות זאת \u0003לא מהימנא\u0004 \u0005[אינה נאמנת].\u0006 ולהיפך, \u0003בתרייתא\u0004 \u0005[\u0006המשנה \u0005האחרונה] —\u0006 \u0003להודיעך כחו\u0004 של \u0003רבן גמליאל, דאף על גב דליכא למימר\u0004 \u0005[שאף על פי שאין\u0006 כאן מקום \u0005לומר]\u0006 \u0003מיגו,\u0004 בכל זאת לדעתו \u0003מהימנא\u0004 \u0005[נאמנת].\u0006","\u0003ראוה\u0004 שהיא \u0003מדברת עם אחד\u0004 ולא ראו את האיש, \u0003ואמרו לה: מה טיבו של איש זה?\u0004 אמרה להם: \u0003איש פלוני, וכהן הוא. רבן גמליאל ור' אליעזר אומרים: נאמנת, ור' יהושע אומר: לא מפיה אנו חיין, אלא הרי זו בחזקת בעולה לנתין\u0004 (לאחד מן הגבעונים, שדינו למעשה כממזר) או \u0003לממזר\u0004 — ופסולה לכהן, \u0003עד שתביא ראיה לדבריה\u0004 מיהו האיש.","כיוצא בדבר: רווקה ש\u0003היתה מעוברת, ואמרו לה: מה טיבו של עובר זה?\u0004 אמרה להם: \u0003מאיש פלוני, וכהן הוא. רבן גמליאל ור' אליעזר אומרים: נאמנת, ור' יהושע אומר: לא מפיה אנו חיין, אלא הרי זו בחזקת מעוברת לנתין ולממזר, עד שתביא ראיה לדבריה.\u0004","תחילה מבררים בעיה לשונית ועניינית: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מדברת\"\u0004 האמור במשנה? \u0003זעירי אמר:\u0004 הכוונה היא \u0003נסתרה,\u0004 כלומר, נתייחדה במקום סתר עם איש ואין אנו יודעים בודאות שנבעלה. \u0003רב אסי אמר:\u0004 הכוונה היא \u0003נבעלה.\u0004 כלומר, שידעו בה בבירור שנבעלה לו. ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דברי \u0003זעירי — היינו דקתני\u0004 \u0005[זהו ששנה]\u0006 לשון \u0003\"מדברת\",\u0004 שכוונתו — נכנסה למקום סתר, ושמא היא רק מדברת עמו. \u0003אלא לרב אסי, מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 לשון \u0003\"מדברת\",\u0004 אם הכוונה היא לבעילה? ומשיבים: הרי זו \u0003לישנא מעליא\u0004 \u0005[לשון מעולה,\u0006 נקייה\u0005],\u0006 \u0003כדכתיב\u0004 \u0005[\u0006ו\u0005כפי שנאמר]\u0006 על אשה זונה: \u0003\"\u0004כן דרך אשה מנאפת \u0003אכלה ומחתה פיה ואמרה לא פעלתי און\"\u0004 (משלי ל, כ). שבלשון נקיה מייחסים את המעשה לפה, ולא לאיבר הראוי.","ומצד אחר שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003זעירי\u0004 שהכוונה היא שנסתרה — \u0003היינו דקתני תרתי\u0004 \u0005[זהו\u0006 הטעם \u0005ששנה שני\u0006 חלקים במשנה\u0005]:\u0006 \u0003\"מדברת\", ו\"מעוברת\". אלא לרב אסי\u0004 שלדעתו מדובר בבעולה ודאי — \u0003תרתי\u0004 \u0005[שתי]\u0006 הלכות נבדלות \u0003למה לי\u0004 הרי היא אותה בעיה עצמה?","ומשיבים: \u0003חדא, להכשיר בה\u0004 \u0005[אחת\u0006 מהן נאמרה, \u0005להכשיר אותה],\u0006 שאף שנבעלה, סבורים ר' אליעזר ורבן גמליאל שיש להאמין לה ולא תיחשב כמי שנבעלה לפסול ותיפסל מלהינשא לכהן. \u0003וחדא\u0004 \u0005[ואחת],\u0006 לענין מעוברת, באה \u0003להכשיר בבתה\u0004 שאם תוולד לה בת מהריון זה, אפשר לסמוך על דברי האם, ותיחשב הבת כשירה וראויה לבוא בקהל.","ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003לדברי\u0004 החכם \u0003המכשיר בה\u0004 ואיננו מחשיב אותה כבעולה לפסול — \u0003מכשיר\u0004 אף \u0003בבתה. אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]:\u0006 \u0003לדברי המכשיר בה,\u0004 מכל מקום \u0003פוסל בבתה — מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 שהרי לפי ההסבר הקודם, דין אחד יש לאם ולבת! ומשיבים: \u0003רב אסי סבר כמאן דאמר\u0004 \u0005[כמי שאומר]\u0006 \u0003לדברי המכשיר בה — מכשיר בבתה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ל\u0004דעת \u0003זעירי\u0004 ש\u0003אמר\u0004 כי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מדברת\" — נסתרה, ואמר ר' יהושע\u0004 כי בענין זה \u0003לא מהימנא\u0004 \u0005[אינה נאמנת]\u0006 לומר שלכשר נבעלה, אלא מניחים שנבעלה לפסול, \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב: מלקין על היחוד,\u0004 שאם רואים אשה פנויה המתייחדת עם אדם זר — מלקים אותם על שעברו על דברי חכמים, \u0003ו\u0004אולם, \u0003אין אוסרין על היחוד,\u0004 שאין אנו אוסרים אשת איש על בעלה משום ייחוד עם גבר זר, עד שיוודע בבירור שנבעלה,","ואם כן \u0003לימא\u0004 \u0005[\u0006האם \u0005לומר]\u0006 שדברי רב הם ש\u0003לא כ\u0004דעת \u0003ר' יהושע,\u0004 שהרי ר' יהושע סבור שאין מאמינים לה, ומניחים שנבעלה לנתין או לממזר ואוסרים אותה לכהן אפילו רק נסתרה! ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שדברי רב הם כשיטת \u0003ר' יהושע,\u0004 אלא \u0003מעלה עשו ביוחסין,\u0004 שלענין יוחסין, שתהא אשה מותרת להינשא לכהן, אמרו חכמים שאפילו אם נסתרה בלבד אוסרים אותה לכהן כאילו נבעלה, אבל אין זו נחשבת ודאות לאוסרה לכל ענין.","\u0003מיתיבי\u0004 \u0005[מקשים]:\u0006 \u0003ראוה\u0004 לאשה \u0003שנכנסה עם אחד לסתר\u0004 (מקום נסתר, ובו יכולים להתייחד),"],["\u0003או לחורבה\u0004 שהיא כרגיל מרוחקת מן העיר, ואם איש ואשה נפגשים שם — מן הסתם לשם ביאה נפגשים, \u0003ואמרו לה: מה טיבו של איש זה\u0004 שהתייחדת עמו? ואמרה להם: \u0003כהן הוא, ובן אחי אבא הוא,\u0004 והוא מיוחס והגון. \u0003רבן גמליאל ור' אליעזר אומרים: נאמנת, ר' יהושע אומר: לא מפיה אנו חיין, אלא הרי זו בחזקת בעולה לנתין ולממזר, עד שתביא ראיה לדבריה\u0004 למי נבעלה.","מעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004פי דברי \u0003זעירי,\u0004 הסבור ש\"מדברת\" משמעה נסתרה בלבד — \u0003היינו דקתני תרתי\u0004 \u0005[זהו\u0006 הטעם \u0005ששנה שני\u0006 מקרים\u0005]:\u0006 \u0003לסתר או לחורבה,\u0004 כלומר, מקום סתר שיש בו חשש קטן יותר של בעילה או לחורבה שיש בה חשש גדול יותר של בעילה, ובשניהם מדובר בחשש בלבד. \u0003אלא ל\u0004דעת \u0003רב אסי\u0004 ש\u0003אמר\u0004 ש\"מדברת\" פירושה \u0003נבעלה,\u0004 ורק במקרה זה אינה נאמנת לר' יהושע, אם כן \u0003תרתי\u0004 \u0005[שני\u0006 מקרים\u0005]\u0006 \u0003למה לי?\u0004 ומשיבים: יש לפרש כי באמת \u0003חדא קתני\u0004 \u0005[\u0006דבר \u0005אחד שנה],\u0006 וכוונתו: שנכנסה \u0003לסתר\u0004 של \u0003חורבה\u0004 ונראים הדברים שלשם בעילה נכנסה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לסתר או לחורבה קתני\u0004 \u0005[שנה],\u0006 משמע ששני מקרים יש לפנינו, ולא דין אחד! ומסבירים באופן אחר: בהלכה \u0003חדא\u0004 \u0005[אחת]\u0006 מדובר שנכנסה \u0003לחורבה דמתא\u0004 \u0005[ש\u0006בתוך \u0005העיר],\u0006 \u0003וחדא\u0004 \u0005[ואחת]\u0006 \u0003לחורבה דדברא\u0004 \u0005[שבשדה],\u0006 רחוק מן העיר. \u0003וצריכי\u0004 \u0005[וצריכים]\u0006 שני הדברים להיאמר, ומדוע? — \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003חורבה דמתא\u0004 \u0005[שבעיר],\u0006 היינו אומרים כך: \u0003בהא קמכשר\u0004 \u0005[בזו\u0006 בלבד \u0005מכשיר]\u0006 \u0003רבן גמליאל, משום\u0004 ש\u0003רוב כשרים אצלה.\u0004 שיש להניח שרוב האנשים המצויים שם כשרים הם לגביה, שמן הסתם האיש שבא לחורבה שבעיר, מאנשי העיר הוא, ורוב אנשי העיר כשרים הם, \u0003אבל לחורבה דדברא\u0004 \u0005[שבשדה],\u0006 ששם \u0003רוב פסולין אצלה\u0004 שהרי אנשים מכל העולם כולו יכולים לבוא לשדה, ורוב אנשי העולם הלא הם פסולים (גוים ועוד), \u0003אימא\u0004 \u0005[אמור,\u0006 שמא\u0005]\u0006 \u0003מודה ליה\u0004 \u0005[לו]\u0006 רבן גמליאל \u0003לר' יהושע\u0004 שאינה נאמנת, לכן הוצרך להשמיע לנו שנחלקו גם במקרה זה.","ולהיפך: \u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק \u0003בההיא,\u0004 בחורבה שבשדה, היינו אומרים: \u0003בההיא קאמר\u0004 \u0005[אומר]\u0006 \u0003ר' יהושע\u0004 שאינה נאמנת, ששם רוב פסולים אצלה, \u0003אבל בהא\u0004 \u0005[בזו]\u0006 בחורבה שבעיר שרוב כשרים אצלה, \u0003אימא\u0004 \u0005[אומר],\u0006 \u0003מודה\u0004 הוא \u0003לרבן גמליאל\u0004 שנאמנת בדבריה וכשירה, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שני המקרים.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא: \u0003זו עדות שהאשה כשרה לה\u0004 כשהיא אומרת שלכשר נבעלה. \u0003ור' יהושע אומר: אינה נאמנת. אמר להם ר' יהושע: אי אתם מודים בשבויה שנשבית ויש לה עדים שנשבית, והיא אומרת טהורה אני\u0004 (שלא נבעלה) \u0003שאינה נאמנת?\u0004 הרי, איפוא, כיוון שיש חזקה שרוב שבויות נבעלות על ידי השובים — אין אנחנו סומכים על דיבורה שאומרת שלא נבעלה.","\u0003אמרו לו: אבל\u0004, כלומר, יש מקום לחלק בין המקרים. \u0003ומה הפרש יש בין זו לזו,\u0004 בין שבויה לסתם אשה שנבעלה? \u0003לזו,\u0004 השבויה — \u0003יש עדים\u0004 שנשבתה ואין לה עוד חזקת כשרות ובודאי נבעלה, \u0003ולזו,\u0004 סתם אשה שנבעלה — \u0003אין לה עדים,\u0004 וצריכה להיאמן בטענת מיגו, שמתוך שהיתה יכולה לומר שלא נבעלה כלל, נאמנת אף במה שאומרת שנבעלה לכשר.","\u0003אמר להם: אף לזו\u0004 שאנחנו דנים בה \u0003יש עדים, שהרי כריסה בין שיניה.\u0004 כלומר, הכל רואים שהיא מעוברת, ואם כן ודאי נבעלה, והרי זו כאילו אומרת דברים במקום שיש עדים המעידים כנגדה! \u0003אמרו לו:\u0004 אינו דומה, כי \u0003רוב גוים פרוצים בעריות הם,\u0004 ולכן יש להניח שהשבויה נבעלה על ידם. אבל כאן אין להניח שנבעלה לפסול דווקא. \u0003אמר להן: אין אפוטרופוס לעריות,\u0004 כלומר, במקום של עריות אין אנשים נאמנים שישמרו עצמם אלא הכל חשודים לגבי זה. ואשה זו, כיון שנבעלה, אין לסמוך שנבעלה לכשר דווקא, ושוב אין לה חזקת כשרות ואין לסמוך עליה כשאומרת למי נבעלה.","ומוסיפים: \u0003במה דברים אמורים\u0004 שנחלקו — \u0003בעדות אשה בגופה,\u0004 האם יש לסמוך על האשה לגבי עצמה, לענין כשרותה להנשא לכהן, \u0003אבל עדות אשה בבתה,\u0004 שאשה מעידה על בתה שנולדה לה שלא מנישואין, ואומרת שמכשר נולדה — \u0003דברי הכל\u0004 אין סומכים על כך, אלא \u0003הולד שתוקי,\u0004 שנחשב כוולד שאין אביו ידוע, ומחמירים בו מכל צד שמא ממזר או פסול הוא.","ותחילה מבררים \u0003מאי קאמר להו ומאי קמהדרי ליה\u0004 \u0005[מה אמר להם ומה החזירו,\u0006 ענו, \u0005לו]?\u0006 שלכאורה נראה מן הויכוח שהם דנים במקרים שונים. ומסבירים: \u0003הכי קאמרי ליה\u0004 \u0005[כך אמרו לו]:\u0006 \u0003השבתנו על המעוברת,\u0004 שאתה אומר שדין המעוברת כדין השבויה, שהרי עדות ההריון דומה לעדות על השבייה. אבל \u0003מה תשיבנו על המדברת?\u0004 שהרי שם אין עדות ברורה שנבעלה. \u0003אמר להם: מדברת היינו שבויה,\u0004 כי רגליים לדבר שנבעלה. \u0003אמרו לו:\u0004 בכל זאת יש להבדיל, שכן \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003שבויה\u0004 כיון ש\u0003רוב גויים פרוצים בעריות הם\u0004 ובודאי נבעלה להם. \u0003אמר להם:\u0004 זו אינה הוכחה, כי \u0003הא נמי\u0004 \u0005[זו,\u0006 מדברת, \u0005גם כן]\u0006 \u0003כיון דאיסתתר\u0004 \u0005[שהסתתרה]\u0006 עם גבר זר, שוב \u0003אין אפוטרופוס לעריות,\u0004 שכיון שהתייחדה עמו — ודאי נבעלה לו, ולא תוכל להעיד שזה שנסתרה עמו כשר היה.","ומעירים לענייננו: \u0003קתני מיהת תרתי\u0004 \u0005[שנינו על כל פנים שני\u0006 מקרים\u0005]\u0006 גם \u0003מדברת ו\u0004גם \u0003מעוברת,\u0004 וראינו שמבדילים בין מקרה של מדברת ששם לא ברור לנו כלל מה היה המעשה, ובין מקרה של מעוברת ששם ברורה לנו העובדה שהיא נבעלה. ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רב אסי\u0004 שפירש \"מדברת\" — נבעלה! ומסכמים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו.","ומקשים לגופה של אותה ברייתא: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 חלוקה זו בין שבויה לסתם אשה מטעם אחר, \u0003דהתם\u0004 \u0005[ששם]\u0006 בשבויה — \u0003רוב פסולין אצלה,\u0004 שהרי רוב האנשים שיכלו לבוא עליה פסולים הם לגביה, \u0003והכא\u0004 \u0005[וכאן]\u0006 בנסתרה — \u0003רוב כשרין אצלה.\u0004 שהרי מדובר בפנויה, ורוב אנשים הם כשרים, ורק מיעוטם יכולים להיות פסולים ואסורים לה! ומעירים: הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' יהושע בן לוי.\u0004 ש\u0003אמר ר' יהושע בן לוי: לדברי המכשיר,\u0004 רבן גמליאל שסומך על נאמנותה — \u0003מכשיר אפילו ברוב פסולין, לדברי הפוסל — פוסל אפילו ברוב כשרים.\u0004","\u0003אמר ר' יוחנן: לדברי המכשיר בה — מכשיר\u0004 גם \u0003בבתה,\u0004 שסומכים על נאמנותה שלכשר נבעלה גם ביחס לכשרות הולד. \u0003לדברי הפוסל בה — פוסל\u0004 גם \u0003בבתה. ו\u0004אילו \u0003ר' אלעזר אומר: לדברי המכשיר בה,\u0004 אפילו הוא — \u0003פוסל בבתה.\u0004","\u0003אמר רבה: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אלעזר\u0004 שמחלק בין עדות האשה לגבי עצמה שנאמנת בה, ובין עדותה לגבי הולד שאינה נאמנת בה — מטעם זה: \u0003בשלמא איהי\u0004 \u0005[נניח היא\u0006 עצמה\u0005]\u0006 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה חזקה\u0004 של \u0003כשרות,\u0004 וכל עוד שלא הוכח אחרת — חזקה שהיא כשירה, וכשאנו באים להוציאה מן החזקה, כיון שאין לכך הוכחות, הריהי נותרת כשירה כשהיתה. אבל \u0003בתה\u0004 שנולדה שלא מן הנישואין, \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה חזקה\u0004 של \u0003כשרות\u0004 ולכן צריכה ראיה מובהקת שאכן כשירה היא.","\u0003איתיביה\u0004 \u0005[הקשה\u0006 לו\u0005]\u0006 \u0003ר' אלעזר לר' יוחנן\u0004 ממה ששנינו: \u0003במה דברים אמורים\u0004 שאשה נאמנת — \u0003בעדות אשה בגופה\u0004 (לגבי עצמה), \u0003אבל עדות אשה בבתה — דברי הכל הולד שתוקי. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה שהוא \u0003שתוקי, ופסול.\u0004 כלומר, הולד פסול לכל דבר עד שיתברר מיהו, ושלא כדבריך שנאמנת גם בבתה! ודוחים: \u0003לא,\u0004 הכוונה היא \u0003שתוקי,\u0004 שלא ברור ייחוסו, אבל \u0003כשר\u0004 לענין נישואין.","ותוהים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 מקרה שהוא קרוי \u0003שתוקי\u0004 ובכל זאת הוא \u0003כשר\u0004 לנישואין? ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 ו\u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל:\u0004 היו \u0003עשרה כהנים עומדים\u0004 במקום אחד, \u0003ופירש אחד מהם\u0004 ואין אנו יודעים מי מהם, \u0003ובעל\u0004 אשה — \u0003הולד\u0004 שנולד מבעילה זו \u0003שתוקי\u0004 הוא.","ומעתה נברר מה דינו, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"שתוקי\"? אילימא\u0004 \u0005[אם תאמר]\u0006 זה \u0003שמשתיקין אותו מנכסי אביו\u0004 ואינו יכול לרשת אותו. הרי דבר זה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 הוא, \u0003ומי ידעינן אבוה מנו\u0004 \u0005[והאם יודעים אנו אביו מיהו]?\u0006 והרי אנחנו יודעים רק שהיה אחד מחבורה זו של כהנים. \u0003אלא\u0004 הכוונה \u0003שמשתיקין אותו מדין כהונה.\u0004 שלמרות שאביו היה ודאי אחד מעשרה כהנים, מכל מקום אין הבן נחשב לכהן. וטעמו של רב — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והיתה לו ולזרעו אחריו ברית כהנת עולם\"\u0004 (במדבר כה, יג), ומכאן למדים: \u0003מי שזרעו מיוחס אחריו\u0004 הרי הוא כהן כאביו, \u0003יצא\u0004 ילד כגון \u0003זה\u0004 שלא ידוע מיהו אביו \u0003שאין זרעו מיוחס אחריו.\u0004 מכל מקום אין הכוונה לומר שהוא שתוקי האסור בבת ישראל, אלא שתוקי מדין כהונה וכשר לנישואין לקהל ישראל.","באותו ענין של בירור האבהות מסופר: \u0003ההוא\u0004 \u0005[אותו]\u0006 \u0003ארוס וארוסתו דאתו לקמיה\u0004 \u0005[שבאו לפני]\u0006 \u0003רב יוסף\u0004 והיתה הארוסה מעוברת, \u0003היא אמרה: מיניה\u0004 \u0005[ממנו]\u0006 היא מעוברת, \u0003והוא\u0004 הארוס \u0003אמר:\u0004"]]};
